-- Additive rule update imported from the public Deutschland Roleplay Google Site.
-- SHA-256: d3b73b98e067414926187ad9665f7203809b1a9d21f935a8119173d2aae9e8a1

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-1';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-1', 'main-1', 'main-1', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§1.0 Regelunklarheiten & Nachfragpflicht', 1, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§1.1"},{"type":"text","text":"Sollte eine Regel unklar sein oder Ungewissheit darüber bestehen, ob eine bestimmte Handlung im Roleplay erlaubt ist, "},{"type":"text","text":"darf nicht eigenständig entschieden"},{"type":"text","text":" werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.2"},{"type":"text","text":"In solchen Fällen ist "},{"type":"text","text":"unverzüglich ein Mitglied des Staff Teams zu kontaktieren"},{"type":"text","text":", um eine verbindliche Klärung zu erhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.3"},{"type":"text","text":" Ausnahmen, Sonderregelungen oder mündliche Zusagen durch Staff oder Fraktionsmanagement sind nicht gültig. Verstöße werden unabhängig davon geahndet; die Verantwortung liegt stets bei der handelnden Person."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.4"},{"type":"text","text":"Das absichtliche Ausnutzen unklarer Regelungen oder das eigenständige Auslegen von Regeln ohne Rücksprache wird als "},{"type":"text","text":"Regelbruch gewertet"},{"type":"text","text":" und entsprechend bestraft."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.5"},{"type":"text","text":"Verantwortlich für die Nachfrage ist "},{"type":"text","text":"immer der jeweilige Spieler selbst"},{"type":"text","text":" – Unwissenheit schützt nicht vor Konsequenzen."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.6"},{"type":"text","text":"Für Anfragen stehen das "},{"type":"text","text":"Ticketsystem im Discord"},{"type":"text","text":", oder ein "},{"type":"text","text":"On-Duty Staff Mitglied"},{"type":"text","text":" zur Verfügung."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.7"},{"type":"text","text":"Wer trotz Unsicherheit handelt, ohne das Team zu informieren, riskiert eine Verwarnung oder härtere Sanktionen – unabhängig davon, wie die Situation im Nachhinein bewertet wird."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.8"},{"type":"text","text":"Die "},{"type":"text","text":"Roblox ToS","marks":[{"type":"link","attrs":{"href":"https://en.help.roblox.com/hc/en-us/articles/115004647846-Roblox-Terms-of-Use","target":"_blank","rel":"noopener noreferrer nofollow","class":null}}]},{"type":"text","text":"Die Nutzerbedingungen (Terms of Service)"},{"type":"text","text":" sind "},{"type":"text","text":"jederzeit und uneingeschränkt"},{"type":"text","text":" einzuhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.9"},{"type":"text","text":" Keine Person steht über diese Niedergeschriebenen Regeln, die ausnahme ist der "},{"type":"text","text":"Founder (Keys) und der Co-Founder Zollstock"},{"type":"text","text":". Jeder hat stehts diese Regeln einzuhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.10 "},{"type":"text","text":"Jeder Spieler ist verpflichtet, im gesamten Roleplay sowie im Umgang miteinander den gesunden Menschenverstand anzuwenden."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.11 "},{"type":"text","text":"Alle Regelverstöße werden "},{"type":"text","text":"situativ und einzelfallbezogen"},{"type":"text","text":" bewertet. Es gibt keine vollständig starren Strafen, die unabhängig vom Kontext angewendet werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.12 "},{"type":"text","text":"Das Regelwerk gilt jederzeit uneingeschränkt – unabhängig davon, ob aktuell aktives Roleplay stattfindet oder nicht."}]},{"type":"paragraph","content":[{"type":"text","text":"Ein sogenannter „RP-Start“ oder „RP-Stop“ setzt keine Regeln außer Kraft und stellt keine Ausnahme von bestehenden Vorschriften dar."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.13 "},{"type":"text","text":"Das Regelwerk gilt für alle Spieler gleichermaßen. CC, CF, Fraktionsleitungen noch andere Personen sind befugt, eigenständig Ausnahmen von bestehenden Regeln zu erteilen. Nicht genehmigte Ausnahmen sind unwirksam. Regelverstöße werden unabhängig von Funktion, Rang oder Status entsprechend geahndet."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§1.0 Regelunklarheiten & Nachfragpflicht' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§1.0 Regelunklarheiten & Nachfragpflicht', "order" = 1, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-1-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§1.1"},{"type":"text","text":"Sollte eine Regel unklar sein oder Ungewissheit darüber bestehen, ob eine bestimmte Handlung im Roleplay erlaubt ist, "},{"type":"text","text":"darf nicht eigenständig entschieden"},{"type":"text","text":" werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.2"},{"type":"text","text":"In solchen Fällen ist "},{"type":"text","text":"unverzüglich ein Mitglied des Staff Teams zu kontaktieren"},{"type":"text","text":", um eine verbindliche Klärung zu erhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.3"},{"type":"text","text":" Ausnahmen, Sonderregelungen oder mündliche Zusagen durch Staff oder Fraktionsmanagement sind nicht gültig. Verstöße werden unabhängig davon geahndet; die Verantwortung liegt stets bei der handelnden Person."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.4"},{"type":"text","text":"Das absichtliche Ausnutzen unklarer Regelungen oder das eigenständige Auslegen von Regeln ohne Rücksprache wird als "},{"type":"text","text":"Regelbruch gewertet"},{"type":"text","text":" und entsprechend bestraft."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.5"},{"type":"text","text":"Verantwortlich für die Nachfrage ist "},{"type":"text","text":"immer der jeweilige Spieler selbst"},{"type":"text","text":" – Unwissenheit schützt nicht vor Konsequenzen."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.6"},{"type":"text","text":"Für Anfragen stehen das "},{"type":"text","text":"Ticketsystem im Discord"},{"type":"text","text":", oder ein "},{"type":"text","text":"On-Duty Staff Mitglied"},{"type":"text","text":" zur Verfügung."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.7"},{"type":"text","text":"Wer trotz Unsicherheit handelt, ohne das Team zu informieren, riskiert eine Verwarnung oder härtere Sanktionen – unabhängig davon, wie die Situation im Nachhinein bewertet wird."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.8"},{"type":"text","text":"Die "},{"type":"text","text":"Roblox ToS","marks":[{"type":"link","attrs":{"href":"https://en.help.roblox.com/hc/en-us/articles/115004647846-Roblox-Terms-of-Use","target":"_blank","rel":"noopener noreferrer nofollow","class":null}}]},{"type":"text","text":"Die Nutzerbedingungen (Terms of Service)"},{"type":"text","text":" sind "},{"type":"text","text":"jederzeit und uneingeschränkt"},{"type":"text","text":" einzuhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.9"},{"type":"text","text":" Keine Person steht über diese Niedergeschriebenen Regeln, die ausnahme ist der "},{"type":"text","text":"Founder (Keys) und der Co-Founder Zollstock"},{"type":"text","text":". Jeder hat stehts diese Regeln einzuhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.10 "},{"type":"text","text":"Jeder Spieler ist verpflichtet, im gesamten Roleplay sowie im Umgang miteinander den gesunden Menschenverstand anzuwenden."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.11 "},{"type":"text","text":"Alle Regelverstöße werden "},{"type":"text","text":"situativ und einzelfallbezogen"},{"type":"text","text":" bewertet. Es gibt keine vollständig starren Strafen, die unabhängig vom Kontext angewendet werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.12 "},{"type":"text","text":"Das Regelwerk gilt jederzeit uneingeschränkt – unabhängig davon, ob aktuell aktives Roleplay stattfindet oder nicht."}]},{"type":"paragraph","content":[{"type":"text","text":"Ein sogenannter „RP-Start“ oder „RP-Stop“ setzt keine Regeln außer Kraft und stellt keine Ausnahme von bestehenden Vorschriften dar."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.13 "},{"type":"text","text":"Das Regelwerk gilt für alle Spieler gleichermaßen. CC, CF, Fraktionsleitungen noch andere Personen sind befugt, eigenständig Ausnahmen von bestehenden Regeln zu erteilen. Nicht genehmigte Ausnahmen sind unwirksam. Regelverstöße werden unabhängig von Funktion, Rang oder Status entsprechend geahndet."}]}]}'::jsonb, '§1.0 Regelunklarheiten & Nachfragpflicht §1.1 Sollte eine Regel unklar sein oder Ungewissheit darüber bestehen, ob eine bestimmte Handlung im Roleplay erlaubt ist, darf nicht eigenständig entschieden werden. §1.2 In solchen Fällen ist unverzüglich ein Mitglied des Staff Teams zu kontaktieren , um eine verbindliche Klärung zu erhalten. §1.3 Ausnahmen, Sonderregelungen oder mündliche Zusagen durch Staff oder Fraktionsmanagement sind nicht gültig. Verstöße werden unabhängig davon geahndet; die Verantwortung liegt stets bei der handelnden Person. §1.4 Das absichtliche Ausnutzen unklarer Regelungen oder das eigenständige Auslegen von Regeln ohne Rücksprache wird als Regelbruch gewertet und entsprechend bestraft. §1.5 Verantwortlich für die Nachfrage ist immer der jeweilige Spieler selbst – Unwissenheit schützt nicht vor Konsequenzen. §1.6 Für Anfragen stehen das Ticketsystem im Discord , oder ein On-Duty Staff Mitglied zur Verfügung. §1.7 Wer trotz Unsicherheit handelt, ohne das Team zu informieren, riskiert eine Verwarnung oder härtere Sanktionen – unabhängig davon, wie die Situation im Nachhinein bewertet wird. §1.8 Die Roblox ToS Die Nutzerbedingungen (Terms of Service) sind jederzeit und uneingeschränkt einzuhalten. §1.9 Keine Person steht über diese Niedergeschriebenen Regeln, die ausnahme ist der Founder (Keys) und der Co-Founder Zollstock . Jeder hat stehts diese Regeln einzuhalten. §1.10 Jeder Spieler ist verpflichtet, im gesamten Roleplay sowie im Umgang miteinander den gesunden Menschenverstand anzuwenden. §1.11 Alle Regelverstöße werden situativ und einzelfallbezogen bewertet. Es gibt keine vollständig starren Strafen, die unabhängig vom Kontext angewendet werden. §1.12 Das Regelwerk gilt jederzeit uneingeschränkt – unabhängig davon, ob aktuell aktives Roleplay stattfindet oder nicht. Ein sogenannter „RP-Start“ oder „RP-Stop“ setzt keine Regeln außer Kraft und stellt keine Ausnahme von bestehenden Vorschriften dar. §1.13 Das Regelwerk gilt für alle Spieler gleichermaßen. CC, CF, Fraktionsleitungen noch andere Personen sind befugt, eigenständig Ausnahmen von bestehenden Regeln zu erteilen. Nicht genehmigte Ausnahmen sind unwirksam. Regelverstöße werden unabhängig von Funktion, Rang oder Status entsprechend geahndet.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-2';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-2', 'main-2', 'main-2', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§2.0 OOC Talk', 2, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§2.1"},{"type":"text","text":"Während einer aktiven Roleplay-Situation darf ausschließlich im Rahmen der eigenen Rolle gesprochen und gehandelt werden. Aussagen oder Verhalten, die nichts mit dem Charakter zu tun haben, stören den Spielfluss und sind nicht erlaubt. Ziel ist ein realistisches und immersives RP-Erlebnis für alle Beteiligten."}]},{"type":"paragraph","content":[{"type":"text","text":"§2.2"},{"type":"text","text":"Jegliche "},{"type":"text","text":"H"},{"type":"text","text":"andlungen und Entscheidungen müssen innerhalb der Charakters erfolgen; das bewusste "},{"type":"text","text":"v"},{"type":"text","text":"ermischen von In-Character- (IC) und Out-Of-Character- (OOC) Informationen ist strengstens untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§2.3"},{"type":"text","text":"Wenn es ausnahmsweise notwendig ist, außerhalb des Rollenspiels (OOC) etwas zu sagen oder zu schreiben, "},{"type":"text","text":"muss"},{"type":"text","text":" dies klar mit "},{"type":"text","text":"Klammern ()"},{"type":"text","text":" gekennzeichnet werden. So bleibt erkennbar, was Teil des RP ist – und was nicht. Dauerhafte oder unnötige OOC-Kommentare innerhalb des RP sind zu vermeiden."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§2.0 OOC Talk' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§2.0 OOC Talk', "order" = 2, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-2-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§2.1"},{"type":"text","text":"Während einer aktiven Roleplay-Situation darf ausschließlich im Rahmen der eigenen Rolle gesprochen und gehandelt werden. Aussagen oder Verhalten, die nichts mit dem Charakter zu tun haben, stören den Spielfluss und sind nicht erlaubt. Ziel ist ein realistisches und immersives RP-Erlebnis für alle Beteiligten."}]},{"type":"paragraph","content":[{"type":"text","text":"§2.2"},{"type":"text","text":"Jegliche "},{"type":"text","text":"H"},{"type":"text","text":"andlungen und Entscheidungen müssen innerhalb der Charakters erfolgen; das bewusste "},{"type":"text","text":"v"},{"type":"text","text":"ermischen von In-Character- (IC) und Out-Of-Character- (OOC) Informationen ist strengstens untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§2.3"},{"type":"text","text":"Wenn es ausnahmsweise notwendig ist, außerhalb des Rollenspiels (OOC) etwas zu sagen oder zu schreiben, "},{"type":"text","text":"muss"},{"type":"text","text":" dies klar mit "},{"type":"text","text":"Klammern ()"},{"type":"text","text":" gekennzeichnet werden. So bleibt erkennbar, was Teil des RP ist – und was nicht. Dauerhafte oder unnötige OOC-Kommentare innerhalb des RP sind zu vermeiden."}]}]}'::jsonb, '§2.0 OOC Talk §2.1 Während einer aktiven Roleplay-Situation darf ausschließlich im Rahmen der eigenen Rolle gesprochen und gehandelt werden. Aussagen oder Verhalten, die nichts mit dem Charakter zu tun haben, stören den Spielfluss und sind nicht erlaubt. Ziel ist ein realistisches und immersives RP-Erlebnis für alle Beteiligten. §2.2 Jegliche H andlungen und Entscheidungen müssen innerhalb der Charakters erfolgen; das bewusste v ermischen von In-Character- (IC) und Out-Of-Character- (OOC) Informationen ist strengstens untersagt. §2.3 Wenn es ausnahmsweise notwendig ist, außerhalb des Rollenspiels (OOC) etwas zu sagen oder zu schreiben, muss dies klar mit Klammern () gekennzeichnet werden. So bleibt erkennbar, was Teil des RP ist – und was nicht. Dauerhafte oder unnötige OOC-Kommentare innerhalb des RP sind zu vermeiden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-3';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-3', 'main-3', 'main-3', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§3.0 Voice Chat (VC), Discord Talk´s Nutzung', 3, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§3.1"},{"type":"text","text":"Die Nutzung von Voice-Chat (VC), sei es über Discord oder andere Plattformen, ist im Zusammenhang mit Roleplay-Situationen auf unserem Server grundsätzlicherlaubt. Dennoch ist auf fairnes zu achten und ggf. auch auf den Ingame Chat zurückzugreifen sofern nicht alle Discord / Voice Chat besitzen."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.2"},{"type":"text","text":"Die "},{"type":"text","text":"RP-Regeln"},{"type":"text","text":" sind "},{"type":"text","text":"im gesamten Chat"},{"type":"text","text":" bindend. Spieler dürfen nach Absprache "},{"type":"text","text":"schriftliches Rollenspiel"},{"type":"text","text":" im Chat durchführen."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.3"},{"type":"text","text":" Sowohl im VC (Voice Chat) als auch auf den RP-Talks auf den Discord ist auf Höflichkeit und die jeweiligen ToS zu achten."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§3.0 Voice Chat (VC), Discord Talk´s Nutzung' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§3.0 Voice Chat (VC), Discord Talk´s Nutzung', "order" = 3, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-3-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§3.1"},{"type":"text","text":"Die Nutzung von Voice-Chat (VC), sei es über Discord oder andere Plattformen, ist im Zusammenhang mit Roleplay-Situationen auf unserem Server grundsätzlicherlaubt. Dennoch ist auf fairnes zu achten und ggf. auch auf den Ingame Chat zurückzugreifen sofern nicht alle Discord / Voice Chat besitzen."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.2"},{"type":"text","text":"Die "},{"type":"text","text":"RP-Regeln"},{"type":"text","text":" sind "},{"type":"text","text":"im gesamten Chat"},{"type":"text","text":" bindend. Spieler dürfen nach Absprache "},{"type":"text","text":"schriftliches Rollenspiel"},{"type":"text","text":" im Chat durchführen."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.3"},{"type":"text","text":" Sowohl im VC (Voice Chat) als auch auf den RP-Talks auf den Discord ist auf Höflichkeit und die jeweiligen ToS zu achten."}]}]}'::jsonb, '§3.0 Voice Chat (VC), Discord Talk´s Nutzung §3.1 Die Nutzung von Voice-Chat (VC), sei es über Discord oder andere Plattformen, ist im Zusammenhang mit Roleplay-Situationen auf unserem Server grundsätzlicherlaubt. Dennoch ist auf fairnes zu achten und ggf. auch auf den Ingame Chat zurückzugreifen sofern nicht alle Discord / Voice Chat besitzen. §3.2 Die RP-Regeln sind im gesamten Chat bindend. Spieler dürfen nach Absprache schriftliches Rollenspiel im Chat durchführen. §3.3 Sowohl im VC (Voice Chat) als auch auf den RP-Talks auf den Discord ist auf Höflichkeit und die jeweiligen ToS zu achten.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-4';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-4', 'main-4', 'main-4', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§4.0 Meta Gaming', 4, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§4.1"},{"type":"text","text":"Das Verwenden von Informationen, die dein Charakter im Roleplay nicht wissen kann – zum Beispiel durch Livestreams, Drittplattformen oder OOC-Gespräche – ist strengstens verboten. Alle Handlungen und Entscheidungen im RP müssen auf dem Wissen deines Charakters basieren, nicht auf deinem eigenen Wissen als Spieler."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.2"},{"type":"text","text":"Das Nutzen von Informationen, die dein Charakter im Roleplay nicht auf legitime Weise erhalten kann – z. B. durch Livestreams, Drittplattformen oder OOC-Gespräche – ist verboten."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.3"},{"type":"text","text":"Dazu zählt auch das Verwenden von Discord-Chats, externen Voice-Channels oder anderen Kommunikationswegen außerhalb des Ingame-Chats, um sich einen Vorteil im RP zu verschaffen."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.4 "},{"type":"text","text":"Alle Handlungen müssen auf dem Wissen deines Charakters basieren, nicht auf deinem Wissen als Spieler."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.5 "},{"type":"text","text":"Ausnahmen gelten ausschließlich für offizielle Fraktionen oder registrierte Gangs"},{"type":"text","text":", die einen zugewiesenen Funk-Channel auf dem Discord-Server besitzen und diesen auch aktiv für ihre RP-Kommunikation nutzen dürfen."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.6"},{"type":"text","text":"Alle Handlungen müssen dennoch auf dem Wissen des RP-Charakters basieren, nicht auf dem Wissen des Spielers."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.7"},{"type":"text","text":"Diese \"Funk"},{"type":"text","text":" Channel´s\" sind ausschließlich für den RP-Zweck gedacht."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.8"},{"type":"text","text":"Zudem ist"},{"type":"text","text":" das Programm"},{"type":"text","text":" \"Zello\" erlaubt und darf von Fraktionen "},{"type":"text","text":"und Gang´s genutzt werden. Für den RP Zweck."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.9"},{"type":"text","text":"Das Nutzen der \"Wanted\" Liste im MDT fällt unteranderem auch unter Metagaming, da man die Personen immer dabei sehen muss wenn sie was \"Verbotenes\" tun."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.10"},{"type":"text","text":"Stream Sniping ist ebenfalls Verboten"},{"type":"text","text":". Dies bedeutet einen Stream anzuschauen und dann zu dem Streamer hinzufahren um ihn zu erschießen, Geiseln etc."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§4.0 Meta Gaming' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§4.0 Meta Gaming', "order" = 4, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-4-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§4.1"},{"type":"text","text":"Das Verwenden von Informationen, die dein Charakter im Roleplay nicht wissen kann – zum Beispiel durch Livestreams, Drittplattformen oder OOC-Gespräche – ist strengstens verboten. Alle Handlungen und Entscheidungen im RP müssen auf dem Wissen deines Charakters basieren, nicht auf deinem eigenen Wissen als Spieler."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.2"},{"type":"text","text":"Das Nutzen von Informationen, die dein Charakter im Roleplay nicht auf legitime Weise erhalten kann – z. B. durch Livestreams, Drittplattformen oder OOC-Gespräche – ist verboten."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.3"},{"type":"text","text":"Dazu zählt auch das Verwenden von Discord-Chats, externen Voice-Channels oder anderen Kommunikationswegen außerhalb des Ingame-Chats, um sich einen Vorteil im RP zu verschaffen."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.4 "},{"type":"text","text":"Alle Handlungen müssen auf dem Wissen deines Charakters basieren, nicht auf deinem Wissen als Spieler."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.5 "},{"type":"text","text":"Ausnahmen gelten ausschließlich für offizielle Fraktionen oder registrierte Gangs"},{"type":"text","text":", die einen zugewiesenen Funk-Channel auf dem Discord-Server besitzen und diesen auch aktiv für ihre RP-Kommunikation nutzen dürfen."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.6"},{"type":"text","text":"Alle Handlungen müssen dennoch auf dem Wissen des RP-Charakters basieren, nicht auf dem Wissen des Spielers."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.7"},{"type":"text","text":"Diese \"Funk"},{"type":"text","text":" Channel´s\" sind ausschließlich für den RP-Zweck gedacht."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.8"},{"type":"text","text":"Zudem ist"},{"type":"text","text":" das Programm"},{"type":"text","text":" \"Zello\" erlaubt und darf von Fraktionen "},{"type":"text","text":"und Gang´s genutzt werden. Für den RP Zweck."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.9"},{"type":"text","text":"Das Nutzen der \"Wanted\" Liste im MDT fällt unteranderem auch unter Metagaming, da man die Personen immer dabei sehen muss wenn sie was \"Verbotenes\" tun."}]},{"type":"paragraph","content":[{"type":"text","text":"§4.10"},{"type":"text","text":"Stream Sniping ist ebenfalls Verboten"},{"type":"text","text":". Dies bedeutet einen Stream anzuschauen und dann zu dem Streamer hinzufahren um ihn zu erschießen, Geiseln etc."}]}]}'::jsonb, '§4.0 Meta Gaming §4.1 Das Verwenden von Informationen, die dein Charakter im Roleplay nicht wissen kann – zum Beispiel durch Livestreams, Drittplattformen oder OOC-Gespräche – ist strengstens verboten. Alle Handlungen und Entscheidungen im RP müssen auf dem Wissen deines Charakters basieren, nicht auf deinem eigenen Wissen als Spieler. §4.2 Das Nutzen von Informationen, die dein Charakter im Roleplay nicht auf legitime Weise erhalten kann – z. B. durch Livestreams, Drittplattformen oder OOC-Gespräche – ist verboten. §4.3 Dazu zählt auch das Verwenden von Discord-Chats, externen Voice-Channels oder anderen Kommunikationswegen außerhalb des Ingame-Chats, um sich einen Vorteil im RP zu verschaffen. §4.4 Alle Handlungen müssen auf dem Wissen deines Charakters basieren, nicht auf deinem Wissen als Spieler. §4.5 Ausnahmen gelten ausschließlich für offizielle Fraktionen oder registrierte Gangs , die einen zugewiesenen Funk-Channel auf dem Discord-Server besitzen und diesen auch aktiv für ihre RP-Kommunikation nutzen dürfen. §4.6 Alle Handlungen müssen dennoch auf dem Wissen des RP-Charakters basieren, nicht auf dem Wissen des Spielers. §4.7 Diese "Funk Channel´s" sind ausschließlich für den RP-Zweck gedacht. §4.8 Zudem ist das Programm "Zello" erlaubt und darf von Fraktionen und Gang´s genutzt werden. Für den RP Zweck. §4.9 Das Nutzen der "Wanted" Liste im MDT fällt unteranderem auch unter Metagaming, da man die Personen immer dabei sehen muss wenn sie was "Verbotenes" tun. §4.10 Stream Sniping ist ebenfalls Verboten . Dies bedeutet einen Stream anzuschauen und dann zu dem Streamer hinzufahren um ihn zu erschießen, Geiseln etc.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-5';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-5', 'main-5', 'main-5', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§5.0 New Life Rule', 5, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§5.1"},{"type":"text","text":"Sobald dein RP-Charakter stirbt und respawnt, "},{"type":"text","text":"darfst du dich nicht mehr an die vorherige RP-Situation erinnern"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.2"},{"type":"text","text":"Das bedeutet: Du darfst nicht zum Ort deines Todes zurückkehren, keine Rache üben, keine Namen oder Informationen weitergeben und keine laufenden Konflikte erneut aufnehmen."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.3"},{"type":"text","text":"Mit dem Respawn beginnt für deinen Charakter ein „neues Leben“ – vergangene Ereignisse gelten als vergessen."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.4"},{"type":"text","text":"Wenn man Gestorben ist (Respawn) dann darf man zu der Situation nicht zurückkehren an der man Gestorben ist, die Gilt für 5 minuten."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.5"},{"type":"text","text":"Wirst du durch einen "},{"type":"text","text":"Sanitäter, Notfallsanitäter oder Notarzt"},{"type":"text","text":" medizinisch versorgt („gehealt“) und "},{"type":"text","text":"nicht respawned"},{"type":"text","text":", so gilt dein Charakter als nicht verstorben. In diesem Fall "},{"type":"text","text":"darfst du dich an alles erinnern"},{"type":"text","text":" und das RP ganz normal fortsetzen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§5.0 New Life Rule' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§5.0 New Life Rule', "order" = 5, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-5-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§5.1"},{"type":"text","text":"Sobald dein RP-Charakter stirbt und respawnt, "},{"type":"text","text":"darfst du dich nicht mehr an die vorherige RP-Situation erinnern"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.2"},{"type":"text","text":"Das bedeutet: Du darfst nicht zum Ort deines Todes zurückkehren, keine Rache üben, keine Namen oder Informationen weitergeben und keine laufenden Konflikte erneut aufnehmen."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.3"},{"type":"text","text":"Mit dem Respawn beginnt für deinen Charakter ein „neues Leben“ – vergangene Ereignisse gelten als vergessen."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.4"},{"type":"text","text":"Wenn man Gestorben ist (Respawn) dann darf man zu der Situation nicht zurückkehren an der man Gestorben ist, die Gilt für 5 minuten."}]},{"type":"paragraph","content":[{"type":"text","text":"§5.5"},{"type":"text","text":"Wirst du durch einen "},{"type":"text","text":"Sanitäter, Notfallsanitäter oder Notarzt"},{"type":"text","text":" medizinisch versorgt („gehealt“) und "},{"type":"text","text":"nicht respawned"},{"type":"text","text":", so gilt dein Charakter als nicht verstorben. In diesem Fall "},{"type":"text","text":"darfst du dich an alles erinnern"},{"type":"text","text":" und das RP ganz normal fortsetzen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§5.0 New Life Rule §5.1 Sobald dein RP-Charakter stirbt und respawnt, darfst du dich nicht mehr an die vorherige RP-Situation erinnern . §5.2 Das bedeutet: Du darfst nicht zum Ort deines Todes zurückkehren, keine Rache üben, keine Namen oder Informationen weitergeben und keine laufenden Konflikte erneut aufnehmen. §5.3 Mit dem Respawn beginnt für deinen Charakter ein „neues Leben“ – vergangene Ereignisse gelten als vergessen. §5.4 Wenn man Gestorben ist (Respawn) dann darf man zu der Situation nicht zurückkehren an der man Gestorben ist, die Gilt für 5 minuten. §5.5 Wirst du durch einen Sanitäter, Notfallsanitäter oder Notarzt medizinisch versorgt („gehealt“) und nicht respawned , so gilt dein Charakter als nicht verstorben. In diesem Fall darfst du dich an alles erinnern und das RP ganz normal fortsetzen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-6';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-6', 'main-6', 'main-6', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§6.0 Fail Roleplay', 6, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§6.1"},{"type":"text","text":"Unter Fail Roleplay versteht man das Ausspielen von "},{"type":"text","text":"unrealistischen oder nicht nachvollziehbaren Handlungen"},{"type":"text","text":", die gegen jede logische oder reale Grundlage verstoßen und somit das RP-Erlebnis stören."}]},{"type":"paragraph","content":[{"type":"text","text":"Beispiele:"},{"type":"hardBreak"},{"type":"text","text":" – Aus 30 Metern Höhe springen und ohne Verletzung weiterlaufen"},{"type":"hardBreak"},{"type":"text","text":" – Nach einem schweren Unfall ohne jegliche Ausspielung einfach aussteigen und weglaufen"},{"type":"hardBreak"},{"type":"text","text":" – Sich im RP wie eine „Superheldenfigur“ verhalten oder das eigene Verletzungs- und Schmerzempfinden ignorieren"}]},{"type":"paragraph","content":[{"type":"text","text":"§6.2"},{"type":"text","text":"Alle Situationen im RP müssen "},{"type":"text","text":"realitätsnah und nachvollziehbar"},{"type":"text","text":" dargestellt werden. Wer FRP betreibt, muss mit einer Verwarnung oder – bei Wiederholung – mit härteren Konsequenzen rechnen."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.3"},{"type":"text","text":"Zudem ist das einmischen in eine Laufende Roleplay (RP) Situation nicht gestattet an der man nicht beteiligt ist, dies fällt dann unter Drittpartei."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.4"},{"type":"text","text":"Bunny Hopping (Das mehrfache Hüpfen) Wären einer Schießerei fällt auch unter FRP. Es muss mind 3 x schnell hintereinander Gehüpft werden, damit man es als Bunny Hopping gesehen werden kann."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.5 "},{"type":"text","text":"Sportwagen dürfen nicht im Gelände gefahren werden."},{"type":"text","text":" Diese Handlungsweise wird als "},{"type":"text","text":"unrealistisches Rollenspiel (FRP)"},{"type":"text","text":" gewertet."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.6 "},{"type":"text","text":"Das unfaire Herausziehen von gefesselten Spielern (mit Cuffs)"},{"type":"text","text":" aus einem Fahrzeug ist untersagt. Solche Aktionen werden als unrealistisches Rollenspiel (FRP) gewertet, da die realistische Interaktion fehlt."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.7 Job Hopping"},{"type":"text","text":", das schnell Job wechseln um sich Vorteile zu verschaffen (Zivi -> DOT -> Auto Reparieren -> Zivi) ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.8 EVT (Emergency-Vehicle Theft)"},{"type":"text","text":" Das grundlose Klauen von Einsatzfahrzeugen (Polizei, Feuerwehr, Rettungsdienst), besonders während die Einsatzkräfte in einem aktiven Einsatz sind, ist verboten."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§6.0 Fail Roleplay' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§6.0 Fail Roleplay', "order" = 6, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-6-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§6.1"},{"type":"text","text":"Unter Fail Roleplay versteht man das Ausspielen von "},{"type":"text","text":"unrealistischen oder nicht nachvollziehbaren Handlungen"},{"type":"text","text":", die gegen jede logische oder reale Grundlage verstoßen und somit das RP-Erlebnis stören."}]},{"type":"paragraph","content":[{"type":"text","text":"Beispiele:"},{"type":"hardBreak"},{"type":"text","text":" – Aus 30 Metern Höhe springen und ohne Verletzung weiterlaufen"},{"type":"hardBreak"},{"type":"text","text":" – Nach einem schweren Unfall ohne jegliche Ausspielung einfach aussteigen und weglaufen"},{"type":"hardBreak"},{"type":"text","text":" – Sich im RP wie eine „Superheldenfigur“ verhalten oder das eigene Verletzungs- und Schmerzempfinden ignorieren"}]},{"type":"paragraph","content":[{"type":"text","text":"§6.2"},{"type":"text","text":"Alle Situationen im RP müssen "},{"type":"text","text":"realitätsnah und nachvollziehbar"},{"type":"text","text":" dargestellt werden. Wer FRP betreibt, muss mit einer Verwarnung oder – bei Wiederholung – mit härteren Konsequenzen rechnen."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.3"},{"type":"text","text":"Zudem ist das einmischen in eine Laufende Roleplay (RP) Situation nicht gestattet an der man nicht beteiligt ist, dies fällt dann unter Drittpartei."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.4"},{"type":"text","text":"Bunny Hopping (Das mehrfache Hüpfen) Wären einer Schießerei fällt auch unter FRP. Es muss mind 3 x schnell hintereinander Gehüpft werden, damit man es als Bunny Hopping gesehen werden kann."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.5 "},{"type":"text","text":"Sportwagen dürfen nicht im Gelände gefahren werden."},{"type":"text","text":" Diese Handlungsweise wird als "},{"type":"text","text":"unrealistisches Rollenspiel (FRP)"},{"type":"text","text":" gewertet."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.6 "},{"type":"text","text":"Das unfaire Herausziehen von gefesselten Spielern (mit Cuffs)"},{"type":"text","text":" aus einem Fahrzeug ist untersagt. Solche Aktionen werden als unrealistisches Rollenspiel (FRP) gewertet, da die realistische Interaktion fehlt."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.7 Job Hopping"},{"type":"text","text":", das schnell Job wechseln um sich Vorteile zu verschaffen (Zivi -> DOT -> Auto Reparieren -> Zivi) ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§6.8 EVT (Emergency-Vehicle Theft)"},{"type":"text","text":" Das grundlose Klauen von Einsatzfahrzeugen (Polizei, Feuerwehr, Rettungsdienst), besonders während die Einsatzkräfte in einem aktiven Einsatz sind, ist verboten."}]}]}'::jsonb, '§6.0 Fail Roleplay §6.1 Unter Fail Roleplay versteht man das Ausspielen von unrealistischen oder nicht nachvollziehbaren Handlungen , die gegen jede logische oder reale Grundlage verstoßen und somit das RP-Erlebnis stören. Beispiele: – Aus 30 Metern Höhe springen und ohne Verletzung weiterlaufen – Nach einem schweren Unfall ohne jegliche Ausspielung einfach aussteigen und weglaufen – Sich im RP wie eine „Superheldenfigur“ verhalten oder das eigene Verletzungs- und Schmerzempfinden ignorieren §6.2 Alle Situationen im RP müssen realitätsnah und nachvollziehbar dargestellt werden. Wer FRP betreibt, muss mit einer Verwarnung oder – bei Wiederholung – mit härteren Konsequenzen rechnen. §6.3 Zudem ist das einmischen in eine Laufende Roleplay (RP) Situation nicht gestattet an der man nicht beteiligt ist, dies fällt dann unter Drittpartei. §6.4 Bunny Hopping (Das mehrfache Hüpfen) Wären einer Schießerei fällt auch unter FRP. Es muss mind 3 x schnell hintereinander Gehüpft werden, damit man es als Bunny Hopping gesehen werden kann. §6.5 Sportwagen dürfen nicht im Gelände gefahren werden. Diese Handlungsweise wird als unrealistisches Rollenspiel (FRP) gewertet. §6.6 Das unfaire Herausziehen von gefesselten Spielern (mit Cuffs) aus einem Fahrzeug ist untersagt. Solche Aktionen werden als unrealistisches Rollenspiel (FRP) gewertet, da die realistische Interaktion fehlt. §6.7 Job Hopping , das schnell Job wechseln um sich Vorteile zu verschaffen (Zivi -> DOT -> Auto Reparieren -> Zivi) ist untersagt. §6.8 EVT (Emergency-Vehicle Theft) Das grundlose Klauen von Einsatzfahrzeugen (Polizei, Feuerwehr, Rettungsdienst), besonders während die Einsatzkräfte in einem aktiven Einsatz sind, ist verboten.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-7';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-7', 'main-7', 'main-7', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§7.0 Baiting/Cop Baiting', 7, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§7.1 "},{"type":"text","text":"Provokations-RP / Fail Roleplay durch gezieltes Provozieren"},{"type":"hardBreak"},{"type":"text","text":" Das absichtliche Provozieren von Polizisten oder anderen Spielern, nur um Aufmerksamkeit zu erlangen oder eine Reaktion zu erzwingen, "},{"type":"text","text":"stellt eine Form von Fail Roleplay dar"},{"type":"text","text":" und ist auf unserem Server "},{"type":"text","text":"nicht gestattet"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Dazu zählt unter anderem:"},{"type":"hardBreak"},{"type":"text","text":" – Das "},{"type":"text","text":"aktive Bedrängen oder Belästigen von Polizeieinheiten"},{"type":"text","text":","},{"type":"hardBreak"},{"type":"text","text":" – Das absichtliche "},{"type":"text","text":"Rammen von Einsatzfahrzeugen"},{"type":"text","text":","},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Über rote Ampeln fahren"},{"type":"text","text":", nur um verfolgt zu werden,"},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Ausbremsen oder Blockieren"},{"type":"text","text":" von Streifenfahrzeugen,"},{"type":"hardBreak"},{"type":"text","text":" – Sowie das "},{"type":"text","text":"gezielte Hineinlocken"},{"type":"text","text":" von Polizei in Gang-Gebiete mit dem Ziel, eine Auseinandersetzung zu provozieren."}]},{"type":"paragraph","content":[{"type":"text","text":"Solches Verhalten widerspricht dem Grundgedanken von realistischem und fairem Roleplay. Verstöße werden entsprechend geahndet – je nach Schwere mit Verwarnungen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§7.0 Baiting/Cop Baiting' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
