      ('revision-main-7-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§7.1 "},{"type":"text","text":"Provokations-RP / Fail Roleplay durch gezieltes Provozieren"},{"type":"hardBreak"},{"type":"text","text":" Das absichtliche Provozieren von Polizisten oder anderen Spielern, nur um Aufmerksamkeit zu erlangen oder eine Reaktion zu erzwingen, "},{"type":"text","text":"stellt eine Form von Fail Roleplay dar"},{"type":"text","text":" und ist auf unserem Server "},{"type":"text","text":"nicht gestattet"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Dazu zählt unter anderem:"},{"type":"hardBreak"},{"type":"text","text":" – Das "},{"type":"text","text":"aktive Bedrängen oder Belästigen von Polizeieinheiten"},{"type":"text","text":","},{"type":"hardBreak"},{"type":"text","text":" – Das absichtliche "},{"type":"text","text":"Rammen von Einsatzfahrzeugen"},{"type":"text","text":","},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Über rote Ampeln fahren"},{"type":"text","text":", nur um verfolgt zu werden,"},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Ausbremsen oder Blockieren"},{"type":"text","text":" von Streifenfahrzeugen,"},{"type":"hardBreak"},{"type":"text","text":" – Sowie das "},{"type":"text","text":"gezielte Hineinlocken"},{"type":"text","text":" von Polizei in Gang-Gebiete mit dem Ziel, eine Auseinandersetzung zu provozieren."}]},{"type":"paragraph","content":[{"type":"text","text":"Solches Verhalten widerspricht dem Grundgedanken von realistischem und fairem Roleplay. Verstöße werden entsprechend geahndet – je nach Schwere mit Verwarnungen."}]}]}'::jsonb, '§7.0 Baiting/Cop Baiting §7.1 Provokations-RP / Fail Roleplay durch gezieltes Provozieren Das absichtliche Provozieren von Polizisten oder anderen Spielern, nur um Aufmerksamkeit zu erlangen oder eine Reaktion zu erzwingen, stellt eine Form von Fail Roleplay dar und ist auf unserem Server nicht gestattet . Dazu zählt unter anderem: – Das aktive Bedrängen oder Belästigen von Polizeieinheiten , – Das absichtliche Rammen von Einsatzfahrzeugen , – Über rote Ampeln fahren , nur um verfolgt zu werden, – Ausbremsen oder Blockieren von Streifenfahrzeugen, – Sowie das gezielte Hineinlocken von Polizei in Gang-Gebiete mit dem Ziel, eine Auseinandersetzung zu provozieren. Solches Verhalten widerspricht dem Grundgedanken von realistischem und fairem Roleplay. Verstöße werden entsprechend geahndet – je nach Schwere mit Verwarnungen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

