      ('revision-main-8-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§8.1 "},{"type":"text","text":"Power Roleplay (Power-RP) ist untersagt."},{"type":"hardBreak"},{"type":"text","text":" Power-RP beschreibt das "},{"type":"text","text":"einseitige Erzwingen einer RP-Situation"},{"type":"text","text":", bei der anderen Spielern "},{"type":"text","text":"keine realistische Möglichkeit zur Reaktion oder zum Ausstieg"},{"type":"text","text":" gegeben wird. Jeder Spieler muss im RP die Gelegenheit haben, "},{"type":"text","text":"angemessen und frei zu handeln"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Beispiel:"},{"type":"hardBreak"},{"type":"text","text":" – Jemand wird ohne Vorwarnung sofort festgenommen oder bewusstlos geschlagen, ohne Chance zur Reaktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Wichtig:"},{"type":"hardBreak"},{"type":"text","text":" – Das bloße "},{"type":"text","text":"Zuparken von Fahrzeugen (PKW, LKW)"},{"type":"text","text":" fällt "},{"type":"text","text":"nicht"},{"type":"text","text":" mehr unter diese Regel, sondern wird separat bewertet."},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Geiselnahmen"},{"type":"text","text":" stellen eine Sonderform im RP dar und "},{"type":"text","text":"fallen nicht unter Power-RP"},{"type":"text","text":", da hier die Einschränkung der Handlungsfreiheit "},{"type":"text","text":"fester Bestandteil"},{"type":"text","text":" der RP-Situation ist. Dabei muss jedoch ein "},{"type":"text","text":"angemessener und realistischer Ablauf"},{"type":"text","text":" eingehalten werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Verstöße gegen diese Regel führen je nach Ausmaß zu einer Verwarnung oder temporären Sanktionen."}]}]}'::jsonb, '§8.0 Power RP §8.1 Power Roleplay (Power-RP) ist untersagt. Power-RP beschreibt das einseitige Erzwingen einer RP-Situation , bei der anderen Spielern keine realistische Möglichkeit zur Reaktion oder zum Ausstieg gegeben wird. Jeder Spieler muss im RP die Gelegenheit haben, angemessen und frei zu handeln . Beispiel: – Jemand wird ohne Vorwarnung sofort festgenommen oder bewusstlos geschlagen, ohne Chance zur Reaktion. Wichtig: – Das bloße Zuparken von Fahrzeugen (PKW, LKW) fällt nicht mehr unter diese Regel, sondern wird separat bewertet. – Geiselnahmen stellen eine Sonderform im RP dar und fallen nicht unter Power-RP , da hier die Einschränkung der Handlungsfreiheit fester Bestandteil der RP-Situation ist. Dabei muss jedoch ein angemessener und realistischer Ablauf eingehalten werden. Verstöße gegen diese Regel führen je nach Ausmaß zu einer Verwarnung oder temporären Sanktionen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
