    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§9.1 "},{"type":"text","text":"Kinder-RP ist unter bestimmten Voraussetzungen erlaubt."},{"type":"hardBreak"},{"type":"text","text":" Das Ausspielen von Kindern im RP ist auf unserem Server "},{"type":"text","text":"grundsätzlich gestattet"},{"type":"text","text":", jedoch gelten hierbei "},{"type":"text","text":"besondere Einschränkungen"},{"type":"text","text":", um ein realistisches und regelkonformes Rollenspiel sicherzustellen. "},{"type":"text","text":"Kinder RP darf nur noch ausgepsielt werden wenn Mindest 1 Elternteil dabei ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§9.2"},{"type":"text","text":"Folgende Regeln sind beim Kinder-RP unbedingt einzuhalten:"},{"type":"hardBreak"},{"type":"text","text":" – Kinder dürfen "},{"type":"text","text":"keine Schusswaffen"},{"type":"text","text":" (z. B. Pistolen, Gewehre, etc.) führen oder benutzen. "},{"type":"text","text":"Darunter fallen auch Messer, Basballschläger etc."},{"type":"hardBreak"},{"type":"text","text":" – Das "},{"type":"text","text":"Führen von motorisierten Fahrzeugen"},{"type":"text","text":" wie "},{"type":"text","text":"PKW, LKW"},{"type":"text","text":" ist nicht gestattet."},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Ausnahme:"},{"type":"text","text":" Kinder dürfen "},{"type":"text","text":"Quads"},{"type":"text","text":" und "},{"type":"text","text":"Rasenmäher"},{"type":"text","text":" nutzen, solange dies im RP nachvollziehbar ausgespielt wird (z. B. privates Spielen im Garten, Mithilfe bei der Gartenarbeit oder einfaches umherfahren)."}]},{"type":"paragraph","content":[{"type":"text","text":"Zuwiderhandlungen gegen diese Regelung können je nach Schwere mit einer Verwarnung bis hin zu temporären RP-Sperren geahndet werden."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§9.0 Kinder RP' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§9.0 Kinder RP', "order" = 9, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-9-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§9.1 "},{"type":"text","text":"Kinder-RP ist unter bestimmten Voraussetzungen erlaubt."},{"type":"hardBreak"},{"type":"text","text":" Das Ausspielen von Kindern im RP ist auf unserem Server "},{"type":"text","text":"grundsätzlich gestattet"},{"type":"text","text":", jedoch gelten hierbei "},{"type":"text","text":"besondere Einschränkungen"},{"type":"text","text":", um ein realistisches und regelkonformes Rollenspiel sicherzustellen. "},{"type":"text","text":"Kinder RP darf nur noch ausgepsielt werden wenn Mindest 1 Elternteil dabei ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§9.2"},{"type":"text","text":"Folgende Regeln sind beim Kinder-RP unbedingt einzuhalten:"},{"type":"hardBreak"},{"type":"text","text":" – Kinder dürfen "},{"type":"text","text":"keine Schusswaffen"},{"type":"text","text":" (z. B. Pistolen, Gewehre, etc.) führen oder benutzen. "},{"type":"text","text":"Darunter fallen auch Messer, Basballschläger etc."},{"type":"hardBreak"},{"type":"text","text":" – Das "},{"type":"text","text":"Führen von motorisierten Fahrzeugen"},{"type":"text","text":" wie "},{"type":"text","text":"PKW, LKW"},{"type":"text","text":" ist nicht gestattet."},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Ausnahme:"},{"type":"text","text":" Kinder dürfen "},{"type":"text","text":"Quads"},{"type":"text","text":" und "},{"type":"text","text":"Rasenmäher"},{"type":"text","text":" nutzen, solange dies im RP nachvollziehbar ausgespielt wird (z. B. privates Spielen im Garten, Mithilfe bei der Gartenarbeit oder einfaches umherfahren)."}]},{"type":"paragraph","content":[{"type":"text","text":"Zuwiderhandlungen gegen diese Regelung können je nach Schwere mit einer Verwarnung bis hin zu temporären RP-Sperren geahndet werden."}]}]}'::jsonb, '§9.0 Kinder RP §9.1 Kinder-RP ist unter bestimmten Voraussetzungen erlaubt. Das Ausspielen von Kindern im RP ist auf unserem Server grundsätzlich gestattet , jedoch gelten hierbei besondere Einschränkungen , um ein realistisches und regelkonformes Rollenspiel sicherzustellen. Kinder RP darf nur noch ausgepsielt werden wenn Mindest 1 Elternteil dabei ist. §9.2 Folgende Regeln sind beim Kinder-RP unbedingt einzuhalten: – Kinder dürfen keine Schusswaffen (z. B. Pistolen, Gewehre, etc.) führen oder benutzen. Darunter fallen auch Messer, Basballschläger etc. – Das Führen von motorisierten Fahrzeugen wie PKW, LKW ist nicht gestattet. – Ausnahme: Kinder dürfen Quads und Rasenmäher nutzen, solange dies im RP nachvollziehbar ausgespielt wird (z. B. privates Spielen im Garten, Mithilfe bei der Gartenarbeit oder einfaches umherfahren). Zuwiderhandlungen gegen diese Regelung können je nach Schwere mit einer Verwarnung bis hin zu temporären RP-Sperren geahndet werden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

