    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Verpflichtung zur aktiven Teilnahme an RP-Situationen"}]},{"type":"paragraph","content":[{"type":"text","text":"§10.1"},{"type":"text","text":"Jeder Spieler ist dazu verpflichtet, an einer laufenden Roleplay-Situation aktiv teilzunehmen, sobald er direkt oder indirekt in diese eingebunden ist."},{"type":"hardBreak"},{"type":"text","text":" Dazu gehört unter anderem auch, "},{"type":"text","text":"Detain-Anfragen"},{"type":"text","text":" (Festnahmen oder Festhaltungen) ordnungsgemäß anzunehmen."}]},{"type":"paragraph","content":[{"type":"text","text":"§10.2"},{"type":"text","text":"Sollte es notwendig sein, kurzfristig "},{"type":"text","text":"AFK (Away from Keyboard)"},{"type":"text","text":" zu gehen, ist Folgendes zu beachten:"},{"type":"hardBreak"},{"type":"text","text":" – Man muss sich in eine "},{"type":"text","text":"Safezone"},{"type":"text","text":" begeben,"},{"type":"hardBreak"},{"type":"text","text":" – Die "},{"type":"text","text":"Hände nach oben halten"},{"type":"text","text":" (z. B. durch eine entsprechende Animation),"},{"type":"hardBreak"},{"type":"text","text":" – Und zusätzlich im Ingame-Chat die Nachricht "},{"type":"text","text":"\"(AFK)\""},{"type":"text","text":" hinterlassen, damit andere Spieler informiert sind."}]},{"type":"paragraph","content":[{"type":"text","text":"Wichtig:"},{"type":"text","text":" Wer sich "},{"type":"text","text":"verweigert"},{"type":"text","text":", das RP korrekt auszuspielen, oder das Spiel gezielt verlässt, um einer Szene zu entgehen, muss mit einer "},{"type":"text","text":"Verwarnung"},{"type":"text","text":" oder "},{"type":"text","text":"weiterführenden Sanktionen"},{"type":"text","text":" rechnen – abhängig vom Einzelfall und der Schwere des Regelbruchs."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§10.0 RP Verwei