    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-10-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Verpflichtung zur aktiven Teilnahme an RP-Situationen"}]},{"type":"paragraph","content":[{"type":"text","text":"§10.1"},{"type":"text","text":"Jeder Spieler ist dazu verpflichtet, an einer laufenden Roleplay-Situation aktiv teilzunehmen, sobald er direkt oder indirekt in diese eingebunden ist."},{"type":"hardBreak"},{"type":"text","text":" Dazu gehört unter anderem auch, "},{"type":"text","text":"Detain-Anfragen"},{"type":"text","text":" (Festnahmen oder Festhaltungen) ordnungsgemäß anzunehmen."}]},{"type":"paragraph","content":[{"type":"text","text":"§10.2"},{"type":"text","text":"Sollte es notwendig sein, kurzfristig "},{"type":"text","text":"AFK (Away from Keyboard)"},{"type":"text","text":" zu gehen, ist Folgendes zu beachten:"},{"type":"hardBreak"},{"type":"text","text":" – Man muss sich in eine "},{"type":"text","text":"Safezone"},{"type":"text","text":" begeben,"},{"type":"hardBreak"},{"type":"text","text":" – Die "},{"type":"text","text":"Hände nach oben halten"},{"type":"text","text":" (z. B. durch eine entsprechende Animation),"},{"type":"hardBreak"},{"type":"text","text":" – Und zusätzlich im Ingame-Chat die Nachricht "},{"type":"text","text":"\"(AFK)\""},{"type":"text","text":" hinterlassen, damit andere Spieler informiert sind."}]},{"type":"paragraph","content":[{"type":"text","text":"Wichtig:"},{"type":"text","text":" Wer sich "},{"type":"text","text":"verweigert"},{"type":"text","text":", das RP korrekt auszuspielen, oder das Spiel gezielt verlässt, um einer Szene zu entgehen, muss mit einer "},{"type":"text","text":"Verwarnung"},{"type":"text","text":" oder "},{"type":"text","text":"weiterführenden Sanktionen"},{"type":"text","text":" rechnen – abhängig vom Einzelfall und der Schwere des Regelbruchs."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§10.0 RP Verweigerung Verpflichtung zur aktiven Teilnahme an RP-Situationen §10.1 Jeder Spieler ist dazu verpflichtet, an einer laufenden Roleplay-Situation aktiv teilzunehmen, sobald er direkt oder indirekt in diese eingebunden ist. Dazu gehört unter anderem auch, Detain-Anfragen (Festnahmen oder Festhaltungen) ordnungsgemäß anzunehmen. §10.2 Sollte es notwendig sein, kurzfristig AFK (Away from Keyboard) zu gehen, ist Folgendes zu beachten: – Man muss sich in eine Safezone begeben, – Die Hände nach oben halten (z. B. durch eine entsprechende Animation), – Und zusätzlich im Ingame-Chat die Nachricht "(AFK)" hinterlassen, damit andere Spieler informiert sind. Wichtig: Wer sich verweigert , das RP korrekt auszuspielen, oder das Spiel gezielt verlässt, um einer Szene zu entgehen, muss mit einer Verwarnung oder weiterführenden Sanktionen rechnen – abhängig vom Einzelfall und der Schwere des Regelbruchs.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-11';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-11', 'main-11', 'main-11', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§11.0 Trolling', 11, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§11.1"},{"type":"text","text":"Das Trollen/Verarschen anderer Personen ist verboten, dies stört nur das Roleplay und kann zu einem Projekt Ausschluss führen."}]},{"type":"paragraph","content":[{"type":"text","text":"§11.2"},{"type":"text","text":"Zudem darf man bei Ausbildungen seitens der Polizei, Feuerwehr, RD und"},{"type":"text","text":" ADAC "},{"type":"text","text":"diese nicht stören da dies auch unter Trolling gewertet werden kann."},{"type":"text","text":" Zudem sind Ausbildungen immer OOC dh sie nehmen am RP nicht Aktiv teil."}]},{"type":"paragraph","content":[{"type":"text","text":"§11.3"},{"type":"text","text":"Soundboard´s über den VC sind verboten und werden dementsprechent bestraft. Das Zählt für "},{"type":"text","text":"jede art (Sirenen, Memes etc)."}]},{"type":"paragraph","content":[{"type":"text","text":"§11.4 "},{"type":"text","text":"Usernames dürfen zudem auch keine Trollnamen beinhalten und werden Sanktioniert."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§11.0 Trolling' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§11.0 Trolling', "order" = 11, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-11-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§11.1"},{"type":"text","text":"Das Trollen/Verarschen anderer Personen ist verboten, dies stört nur das Roleplay und kann zu einem Projekt Ausschluss führen."}]},{"type":"paragraph","content":[{"type":"text","text":"§11.2"},{"type":"text","text":"Zudem darf man bei Ausbildungen seitens der Polizei, Feuerwehr, RD und"},{"type":"text","text":" ADAC "},{"type":"text","text":"diese nicht stören da dies auch unter Trolling gewertet werden kann."},{"type":"text","text":" Zudem sind Ausbildungen immer OOC dh sie nehmen am RP nicht Aktiv teil."}]},{"type":"paragraph","content":[{"type":"text","text":"§11.3"},{"type":"text","text":"Soundboard´s über den VC sind verboten und werden dementsprechent bestraft. Das Zählt für "},{"type":"text","text":"jede art (Sirenen, Memes etc)."}]},{"type":"paragraph","content":[{"type":"text","text":"§11.4 "},{"type":"text","text":"Usernames dürfen zudem auch keine Trollnamen beinhalten und werden Sanktioniert."}]}]}'::jsonb, '§11.0 Trolling §11.1 Das Trollen/Verarschen anderer Personen ist verboten, dies stört nur das Roleplay und kann zu einem Projekt Ausschluss führen. §11.2 Zudem darf man bei Ausbildungen seitens der Polizei, Feuerwehr, RD und ADAC diese nicht stören da dies auch unter Trolling gewertet werden kann. Zudem sind Ausbildungen immer OOC dh sie nehmen am RP nicht Aktiv teil. §11.3 Soundboard´s über den VC sind verboten und werden dementsprechent bestraft. Das Zählt für jede art (Sirenen, Memes etc). §11.4 Usernames dürfen zudem auch keine Trollnamen beinhalten und werden Sanktioniert.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-12';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-12', 'main-12', 'main-12', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§12.0 Clips / Reports', 12, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§12.1"},{"type":"text","text":"Alle Beweise, wie z. B. Videoclips oder Screenshots, die zur Meldung eines Regelverstoßes oder für einen Supportfall verwendet werden sollen, "},{"type":"text","text":"müssen innerhalb von 24 Stunden nach dem Vorfall"},{"type":"text","text":" vollständig eingereicht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.2"},{"type":"text","text":"Nach Ablauf dieser Frist gelten alle Beweise als "},{"type":"text","text":"ungültig und werden im Support nicht mehr berücksichtigt"},{"type":"text","text":" – unabhängig davon, ob sie authentisch oder nachvollziehbar sind."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.3"},{"type":"text","text":"Stimmen dürfen auch für Beweis Zwecke aufgenommen werden dürfen aber nicht weitergegeben werden oder veröffentlicht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.4 "},{"type":"text","text":"Wird ein Report mithilfe eines Videoclips eingereicht, muss der gesamte relevante Roleplay-Verlauf vollständig und ohne Unterbrechungen ersichtlich sein. Das bedeutet, dass der Clip den Vorfall vom Beginn bis zum Ende zeigen muss, sodass der Kontext der Situation klar nachvollzogen werden kann."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.5"},{"type":"text","text":" Das absichtliche "},{"type":"text","text":"Verschleiern, Verheimlichen oder Überspringen von Szenen"},{"type":"text","text":" innerhalb des Clips ist nicht gestattet. Geschnittene oder unvollständige Aufnahmen können dazu führen, dass wichtige Informationen fehlen und der Sachverhalt nicht korrekt bewertet werden kann."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.6"},{"type":"text","text":" Staff-Mitglieder sind jederzeit berechtigt, den "},{"type":"text","text":"vollständigen und ungeschnittenen Clip"},{"type":"text","text":" des Vorfalls anzufordern. Dies dient der fairen und objektiven Prüfung eines Reports."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.7"},{"type":"text","text":" Sollte der vollständige Clip auf Nachfrage nicht bereitgestellt werden oder sich herausstellen, dass der Clip bearbeitet, gekürzt oder unvollständig ist, wird der eingereichte Beweis "},{"type":"text","text":"als ungültig gewertet"},{"type":"text","text":" und der Report kann entsprechend "},{"type":"text","text":"abgelehnt oder geschlossen"},{"type":"text","text":" werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.8 "},{"type":"text","text":"Clips "},{"type":"text","text":"MÜSSEN "},{"type":"text","text":"mind. 24h aufbewahrt werden, ansonsten können Sanktionen Folgen. Zudem wird der Clip dann als \"Ungültig\" erachtet."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§12.0 Clips / Reports' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§12.0 Clips / Reports', "order" = 12, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-12-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§12.1"},{"type":"text","text":"Alle Beweise, wie z. B. Videoclips oder Screenshots, die zur Meldung eines Regelverstoßes oder für einen Supportfall verwendet werden sollen, "},{"type":"text","text":"müssen innerhalb von 24 Stunden nach dem Vorfall"},{"type":"text","text":" vollständig eingereicht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.2"},{"type":"text","text":"Nach Ablauf dieser Frist gelten alle Beweise als "},{"type":"text","text":"ungültig und werden im Support nicht mehr berücksichtigt"},{"type":"text","text":" – unabhängig davon, ob sie authentisch oder nachvollziehbar sind."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.3"},{"type":"text","text":"Stimmen dürfen auch für Beweis Zwecke aufgenommen werden dürfen aber nicht weitergegeben werden oder veröffentlicht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.4 "},{"type":"text","text":"Wird ein Report mithilfe eines Videoclips eingereicht, muss der gesamte relevante Roleplay-Verlauf vollständig und ohne Unterbrechungen ersichtlich sein. Das bedeutet, dass der Clip den Vorfall vom Beginn bis zum Ende zeigen muss, sodass der Kontext der Situation klar nachvollzogen werden kann."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.5"},{"type":"text","text":" Das absichtliche "},{"type":"text","text":"Verschleiern, Verheimlichen oder Überspringen von Szenen"},{"type":"text","text":" innerhalb des Clips ist nicht gestattet. Geschnittene oder unvollständige Aufnahmen können dazu führen, dass wichtige Informationen fehlen und der Sachverhalt nicht korrekt bewertet werden kann."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.6"},{"type":"text","text":" Staff-Mitglieder sind jederzeit berechtigt, den "},{"type":"text","text":"vollständigen und ungeschnittenen Clip"},{"type":"text","text":" des Vorfalls anzufordern. Dies dient der fairen und objektiven Prüfung eines Reports."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.7"},{"type":"text","text":" Sollte der vollständige Clip auf Nachfrage nicht bereitgestellt werden oder sich herausstellen, dass der Clip bearbeitet, gekürzt oder unvollständig ist, wird der eingereichte Beweis "},{"type":"text","text":"als ungültig gewertet"},{"type":"text","text":" und der Report kann entsprechend "},{"type":"text","text":"abgelehnt oder geschlossen"},{"type":"text","text":" werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§12.8 "},{"type":"text","text":"Clips "},{"type":"text","text":"MÜSSEN "},{"type":"text","text":"mind. 24h aufbewahrt werden, ansonsten können Sanktionen Folgen. Zudem wird der Clip dann als \"Ungültig\" erachtet."}]}]}'::jsonb, '§12.0 Clips / Reports §12.1 Alle Beweise, wie z. B. Videoclips oder Screenshots, die zur Meldung eines Regelverstoßes oder für einen Supportfall verwendet werden sollen, müssen innerhalb von 24 Stunden nach dem Vorfall vollständig eingereicht werden. §12.2 Nach Ablauf dieser Frist gelten alle Beweise als ungültig und werden im Support nicht mehr berücksichtigt – unabhängig davon, ob sie authentisch oder nachvollziehbar sind. §12.3 Stimmen dürfen auch für Beweis Zwecke aufgenommen werden dürfen aber nicht weitergegeben werden oder veröffentlicht werden. §12.4 Wird ein Report mithilfe eines Videoclips eingereicht, muss der gesamte relevante Roleplay-Verlauf vollständig und ohne Unterbrechungen ersichtlich sein. Das bedeutet, dass der Clip den Vorfall vom Beginn bis zum Ende zeigen muss, sodass der Kontext der Situation klar nachvollzogen werden kann. §12.5 Das absichtliche Verschleiern, Verheimlichen oder Überspringen von Szenen innerhalb des Clips ist nicht gestattet. Geschnittene oder unvollständige Aufnahmen können dazu führen, dass wichtige Informationen fehlen und der Sachverhalt nicht korrekt bewertet werden kann. §12.6 Staff-Mitglieder sind jederzeit berechtigt, den vollständigen und ungeschnittenen Clip des Vorfalls anzufordern. Dies dient der fairen und objektiven Prüfung eines Reports. §12.7 Sollte der vollständige Clip auf Nachfrage nicht bereitgestellt werden oder sich herausstellen, dass der Clip bearbeitet, gekürzt oder unvollständig ist, wird der eingereichte Beweis als ungültig gewertet und der Report kann entsprechend abgelehnt oder geschlossen werden. §12.8 Clips MÜSSEN mind. 24h aufbewahrt werden, ansonsten können Sanktionen Folgen. Zudem wird der Clip dann als "Ungültig" erachtet.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-13';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-13', 'main-13', 'main-13', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§13.0 Blood Out', 13, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"„Blood Out“ – Finale Charakterlöschung mit RP-Hintergrund"}]},{"type":"paragraph","content":[{"type":"text","text":"Ein sogenannter "},{"type":"text","text":"„Blood Out“"},{"type":"text","text":" stellt den "},{"type":"text","text":"endgültigen Ausstieg"},{"type":"text","text":" eines Charakters aus einer Gang oder Fraktion dar und gilt als "},{"type":"text","text":"dauerhafte Charakterlöschung"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§13.1"},{"type":"text","text":"Ein Blood Out darf "},{"type":"text","text":"nicht leichtfertig"},{"type":"text","text":" durchgeführt werden."},{"type":"hardBreak"},{"type":"text","text":" Es muss ein "},{"type":"text","text":"nachvollziehbarer und tiefgehender RP-Hintergrund"},{"type":"text","text":" vorhanden sein, der diesen Schritt rechtfertigt."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"§13.2"},{"type":"text","text":"Jeder Spieler, der "},{"type":"text","text":"Mitglied einer offiziellen Gang oder Fraktion"},{"type":"text","text":" ist, darf grundsätzlich einen Blood Out im Rahmen des Roleplays aussprechen – sofern es "},{"type":"text","text":"intern geregelt und gut ausgespielt"},{"type":"text","text":" wird."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"§13.3"},{"type":"text","text":"Ein Blood Out ist "},{"type":"text","text":"nicht gleichzusetzen"},{"type":"text","text":" mit einem Hinrichtungs-RP. Es geht hierbei nicht um eine bloße Exekution, sondern um einen "},{"type":"text","text":"sinnvoll aufgebauten Ausstieg"},{"type":"text","text":", der Rollenspiel-basiert umgesetzt werden muss."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"§13.4"},{"type":"text","text":"Wird ein Spieler "},{"type":"text","text":"gebloodoutet"},{"type":"text","text":", so gilt folgendes: – Der betreffende Charakter darf "},{"type":"text","text":"nicht mehr gespielt"},{"type":"text","text":" werden."},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Alle Informationen"},{"type":"text","text":", die dieser Charakter im Laufe seines Lebens gesammelt hat (z. B. Gang-Strukturen, interne Pläne, Namen), "},{"type":"text","text":"dürfen nicht mehr verwendet oder weitergegeben werden"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Ein Missbrauch dieser Regel oder ein Blood Out ohne ausreichendes RP-Fundament kann zur "},{"type":"text","text":"Ungültigkeit"},{"type":"text","text":" des Vorgangs und ggf. zu "},{"type":"text","text":"Strafen"},{"type":"text","text":" führen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§13.0 Blood Out' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§13.0 Blood Out', "order" = 13, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-13-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"„Blood Out“ – Finale Charakterlöschung mit RP-Hintergrund"}]},{"type":"paragraph","content":[{"type":"text","text":"Ein sogenannter "},{"type":"text","text":"„Blood Out“"},{"type":"text","text":" stellt den "},{"type":"text","text":"endgültigen Ausstieg"},{"type":"text","text":" eines Charakters aus einer Gang oder Fraktion dar und gilt als "},{"type":"text","text":"dauerhafte Charakterlöschung"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§13.1"},{"type":"text","text":"Ein Blood Out darf "},{"type":"text","text":"nicht leichtfertig"},{"type":"text","text":" durchgeführt werden."},{"type":"hardBreak"},{"type":"text","text":" Es muss ein "},{"type":"text","text":"nachvollziehbarer und tiefgehender RP-Hintergrund"},{"type":"text","text":" vorhanden sein, der diesen Schritt rechtfertigt."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"§13.2"},{"type":"text","text":"Jeder Spieler, der "},{"type":"text","text":"Mitglied einer offiziellen Gang oder Fraktion"},{"type":"text","text":" ist, darf grundsätzlich einen Blood Out im Rahmen des Roleplays aussprechen – sofern es "},{"type":"text","text":"intern geregelt und gut ausgespielt"},{"type":"text","text":" wird."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"§13.3"},{"type":"text","text":"Ein Blood Out ist "},{"type":"text","text":"nicht gleichzusetzen"},{"type":"text","text":" mit einem Hinrichtungs-RP. Es geht hierbei nicht um eine bloße Exekution, sondern um einen "},{"type":"text","text":"sinnvoll aufgebauten Ausstieg"},{"type":"text","text":", der Rollenspiel-basiert umgesetzt werden muss."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"§13.4"},{"type":"text","text":"Wird ein Spieler "},{"type":"text","text":"gebloodoutet"},{"type":"text","text":", so gilt folgendes: – Der betreffende Charakter darf "},{"type":"text","text":"nicht mehr gespielt"},{"type":"text","text":" werden."},{"type":"hardBreak"},{"type":"text","text":" – "},{"type":"text","text":"Alle Informationen"},{"type":"text","text":", die dieser Charakter im Laufe seines Lebens gesammelt hat (z. B. Gang-Strukturen, interne Pläne, Namen), "},{"type":"text","text":"dürfen nicht mehr verwendet oder weitergegeben werden"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Ein Missbrauch dieser Regel oder ein Blood Out ohne ausreichendes RP-Fundament kann zur "},{"type":"text","text":"Ungültigkeit"},{"type":"text","text":" des Vorgangs und ggf. zu "},{"type":"text","text":"Strafen"},{"type":"text","text":" führen."}]}]}'::jsonb, '§13.0 Blood Out „Blood Out“ – Finale Charakterlöschung mit RP-Hintergrund Ein sogenannter „Blood Out“ stellt den endgültigen Ausstieg eines Charakters aus einer Gang oder Fraktion dar und gilt als dauerhafte Charakterlöschung . §13.1 Ein Blood Out darf nicht leichtfertig durchgeführt werden. Es muss ein nachvollziehbarer und tiefgehender RP-Hintergrund vorhanden sein, der diesen Schritt rechtfertigt. §13.2 Jeder Spieler, der Mitglied einer offiziellen Gang oder Fraktion ist, darf grundsätzlich einen Blood Out im Rahmen des Roleplays aussprechen – sofern es intern geregelt und gut ausgespielt wird. §13.3 Ein Blood Out ist nicht gleichzusetzen mit einem Hinrichtungs-RP. Es geht hierbei nicht um eine bloße Exekution, sondern um einen sinnvoll aufgebauten Ausstieg , der Rollenspiel-basiert umgesetzt werden muss. §13.4 Wird ein Spieler gebloodoutet , so gilt folgendes: – Der betreffende Charakter darf nicht mehr gespielt werden. – Alle Informationen , die dieser Charakter im Laufe seines Lebens gesammelt hat (z. B. Gang-Strukturen, interne Pläne, Namen), dürfen nicht mehr verwendet oder weitergegeben werden . Ein Missbrauch dieser Regel oder ein Blood Out ohne ausreichendes RP-Fundament kann zur Ungültigkeit des Vorgangs und ggf. zu Strafen führen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-14';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-14', 'main-14', 'main-14', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§14.0 Random DeathMatch', 14, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§14.1 "},{"type":"text","text":"RP-Hintergrund"},{"type":"hardBreak"},{"type":"text","text":" Jede Situation, in der eine Waffe zum Einsatz kommt, muss auf einem nachvollziehbaren RP-Hintergrund basieren. Es reicht nicht, einfach jemanden zu erschießen, nur weil eine Meinungsverschiedenheit besteht oder eine Provokation stattgefunden hat. Gewalt muss immer im RP-Kontext begründet sein."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.2 "},{"type":"text","text":"Schusscall Pflicht"},{"type":"hardBreak"},{"type":"text","text":" Bevor ein Schuss abgegeben wird, muss eindeutig und sichtbar ein Schusscall gesetzt werden. Dieser kann durch mindestens drei Sekunden aktives Zielen auf die Zielperson oder deren Fahrzeug erfolgen, durch einen Warnschuss in die Luft oder auf den Boden oder durch eine klar erkennbare Textnachricht im Ingame-Chat. Nur so wird der Call gültig und eine RP-Situation mit Waffengebrauch korrekt eingeleitet."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.3 "},{"type":"text","text":"Gültigkeitsdauer des Schusscalls"},{"type":"hardBreak"},{"type":"text","text":" Ein abgegebener Schusscall bleibt für drei Minuten aktiv. Innerhalb dieses Zeitraums darf gehandelt werden, solange sich die Situation nicht verändert oder aufgelöst hat. Danach muss bei weiterer Eskalation ein neuer Call erfolgen."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.4 "},{"type":"text","text":"Unzulässige Call-Arten"},{"type":"hardBreak"},{"type":"text","text":" Ein Schusscall über externe Plattformen wie Discord ist nicht erlaubt. Alle Ankündigungen müssen für alle Beteiligten sichtbar und ingame nachvollziehbar sein."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.5 "},{"type":"text","text":"Besonderheiten bei Ganggebieten"},{"type":"hardBreak"},{"type":"text","text":" Betritt ein Spieler ein aktives Ganggebiet, darf die Gang auch ohne gesonderte Ankündigung handeln – vorausgesetzt, es besteht eine aktive RP-Situation und es wird nicht gegen die Fairness verstoßen. Dennoch ist auch hier das Gambo-RP zu beachten."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.6 "},{"type":"text","text":"Reaktionszeit & Fairness"},{"type":"hardBreak"},{"type":"text","text":" Ein Schusscall muss mindestens fünf Sekunden vor der eigentlichen Handlung erkennbar erfolgen, damit andere Spieler fair reagieren können. Sollte sich eine betroffene Person in einem Menü befinden (z. B. beim Tanken oder Autospawn), muss gewartet werden, bis sie wieder handlungsfähig ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.7 "},{"type":"text","text":"Sichtbarkeit & Reichweite"},{"type":"hardBreak"},{"type":"text","text":" Der Schusscall muss sichtbar sein. Eine Gültigkeit besteht nur, wenn sich die betroffenen Personen in einem Radius von maximal 20 Metern befinden. Alles darüber hinaus gilt nicht als klar erkennbare Ankündigung."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.8 "},{"type":"text","text":"Leichen Schändigung & arten"},{"type":"hardBreak"},{"type":"text","text":"Leichenschändigung (Verunglimpfung ausgeschalteter Spieler) ist auf unserem Server strikt untersagt und wird mit einem unmittelbaren Serverausschluss geahndet."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.9 Leichenschändigungs bedingung"}]},{"type":"paragraph","content":[{"type":"text","text":"Damit eine Handlung als Leichenschändung gewertet werden kann, muss gegenüber einer bewusstlosen, verletzten oder bereits verstorben ausgespielten Person eine "},{"type":"text","text":"vorsätzliche und respektlose Handlung"},{"type":"text","text":" erfolgen. Dabei muss erkennbar sein, dass die Handlung bewusst durchgeführt wurde und nicht versehentlich entstanden ist."}]},{"type":"paragraph","content":[{"type":"text","text":"Als Leichenschändung gelten insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"wiederholtes Schießen auf eine bereits handlungsunfähige Person,"}]},{"type":"paragraph","content":[{"type":"text","text":"mehrfaches Überfahren oder absichtliches Anfahren einer am Boden liegenden Person,"}]},{"type":"paragraph","content":[{"type":"text","text":"wiederholtes Überlaufen, Anspringen oder anderweitiges Herabwürdigen einer handlungsunfähigen Person,"}]},{"type":"paragraph","content":[{"type":"text","text":"sonstige vergleichbare Handlungen, die ausschließlich der Verhöhnung, Demütigung oder Missachtung der betroffenen Person dienen."}]},{"type":"paragraph","content":[{"type":"text","text":"Einzelne versehentliche Berührungen, Fahrfehler oder einmalige Missgeschicke gelten in der Regel nicht als Leichenschändung. Für die Bewertung werden stets die Umstände des Einzelfalls, die Absicht des Spielers sowie die Häufigkeit der Handlung berücksichtigt."}]},{"type":"paragraph","content":[{"type":"text","text":"Die endgültige Einstufung, ob eine Handlung als Leichenschändung zu werten ist und welche Sanktion angemessen erscheint, obliegt dem zuständigen Moderator oder Administrator. Dieser entscheidet unter Berücksichtigung der Schwere des Verstoßes, der vorliegenden Beweise sowie der Gesamtsituation."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"§14.10 Verbot von Auftragskiller-RP"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Ausführen, Anbieten oder Vermitteln von sogenannten „Auftragskiller“-Handlungen ist im Roleplay vollständig untersagt. Darunter fällt insbesondere das gezielte Beauftragen, Planen oder Durchführen von Tötungen gegen andere Spieler gegen Bezahlung oder sonstige Gegenleistungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von Auftragsmorden, unabhängig davon ob diese erfolgreich umgesetzt oder lediglich geplant werden, stellt einen Verstoß gegen das Regelwerk dar. Dies gilt auch für indirekte Absprachen oder das Umgehen dieser Regel durch Dritte."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§14.0 Random DeathMatch' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§14.0 Random DeathMatch', "order" = 14, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-14-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§14.1 "},{"type":"text","text":"RP-Hintergrund"},{"type":"hardBreak"},{"type":"text","text":" Jede Situation, in der eine Waffe zum Einsatz kommt, muss auf einem nachvollziehbaren RP-Hintergrund basieren. Es reicht nicht, einfach jemanden zu erschießen, nur weil eine Meinungsverschiedenheit besteht oder eine Provokation stattgefunden hat. Gewalt muss immer im RP-Kontext begründet sein."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.2 "},{"type":"text","text":"Schusscall Pflicht"},{"type":"hardBreak"},{"type":"text","text":" Bevor ein Schuss abgegeben wird, muss eindeutig und sichtbar ein Schusscall gesetzt werden. Dieser kann durch mindestens drei Sekunden aktives Zielen auf die Zielperson oder deren Fahrzeug erfolgen, durch einen Warnschuss in die Luft oder auf den Boden oder durch eine klar erkennbare Textnachricht im Ingame-Chat. Nur so wird der Call gültig und eine RP-Situation mit Waffengebrauch korrekt eingeleitet."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.3 "},{"type":"text","text":"Gültigkeitsdauer des Schusscalls"},{"type":"hardBreak"},{"type":"text","text":" Ein abgegebener Schusscall bleibt für drei Minuten aktiv. Innerhalb dieses Zeitraums darf gehandelt werden, solange sich die Situation nicht verändert oder aufgelöst hat. Danach muss bei weiterer Eskalation ein neuer Call erfolgen."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.4 "},{"type":"text","text":"Unzulässige Call-Arten"},{"type":"hardBreak"},{"type":"text","text":" Ein Schusscall über externe Plattformen wie Discord ist nicht erlaubt. Alle Ankündigungen müssen für alle Beteiligten sichtbar und ingame nachvollziehbar sein."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.5 "},{"type":"text","text":"Besonderheiten bei Ganggebieten"},{"type":"hardBreak"},{"type":"text","text":" Betritt ein Spieler ein aktives Ganggebiet, darf die Gang auch ohne gesonderte Ankündigung handeln – vorausgesetzt, es besteht eine aktive RP-Situation und es wird nicht gegen die Fairness verstoßen. Dennoch ist auch hier das Gambo-RP zu beachten."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.6 "},{"type":"text","text":"Reaktionszeit & Fairness"},{"type":"hardBreak"},{"type":"text","text":" Ein Schusscall muss mindestens fünf Sekunden vor der eigentlichen Handlung erkennbar erfolgen, damit andere Spieler fair reagieren können. Sollte sich eine betroffene Person in einem Menü befinden (z. B. beim Tanken oder Autospawn), muss gewartet werden, bis sie wieder handlungsfähig ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.7 "},{"type":"text","text":"Sichtbarkeit & Reichweite"},{"type":"hardBreak"},{"type":"text","text":" Der Schusscall muss sichtbar sein. Eine Gültigkeit besteht nur, wenn sich die betroffenen Personen in einem Radius von maximal 20 Metern befinden. Alles darüber hinaus gilt nicht als klar erkennbare Ankündigung."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.8 "},{"type":"text","text":"Leichen Schändigung & arten"},{"type":"hardBreak"},{"type":"text","text":"Leichenschändigung (Verunglimpfung ausgeschalteter Spieler) ist auf unserem Server strikt untersagt und wird mit einem unmittelbaren Serverausschluss geahndet."}]},{"type":"paragraph","content":[{"type":"text","text":"§14.9 Leichenschändigungs bedingung"}]},{"type":"paragraph","content":[{"type":"text","text":"Damit eine Handlung als Leichenschändung gewertet werden kann, muss gegenüber einer bewusstlosen, verletzten oder bereits verstorben ausgespielten Person eine "},{"type":"text","text":"vorsätzliche und respektlose Handlung"},{"type":"text","text":" erfolgen. Dabei muss erkennbar sein, dass die Handlung bewusst durchgeführt wurde und nicht versehentlich entstanden ist."}]},{"type":"paragraph","content":[{"type":"text","text":"Als Leichenschändung gelten insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"wiederholtes Schießen auf eine bereits handlungsunfähige Person,"}]},{"type":"paragraph","content":[{"type":"text","text":"mehrfaches Überfahren oder absichtliches Anfahren einer am Boden liegenden Person,"}]},{"type":"paragraph","content":[{"type":"text","text":"wiederholtes Überlaufen, Anspringen oder anderweitiges Herabwürdigen einer handlungsunfähigen Person,"}]},{"type":"paragraph","content":[{"type":"text","text":"sonstige vergleichbare Handlungen, die ausschließlich der Verhöhnung, Demütigung oder Missachtung der betroffenen Person dienen."}]},{"type":"paragraph","content":[{"type":"text","text":"Einzelne versehentliche Berührungen, Fahrfehler oder einmalige Missgeschicke gelten in der Regel nicht als Leichenschändung. Für die Bewertung werden stets die Umstände des Einzelfalls, die Absicht des Spielers sowie die Häufigkeit der Handlung berücksichtigt."}]},{"type":"paragraph","content":[{"type":"text","text":"Die endgültige Einstufung, ob eine Handlung als Leichenschändung zu werten ist und welche Sanktion angemessen erscheint, obliegt dem zuständigen Moderator oder Administrator. Dieser entscheidet unter Berücksichtigung der Schwere des Verstoßes, der vorliegenden Beweise sowie der Gesamtsituation."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"§14.10 Verbot von Auftragskiller-RP"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Ausführen, Anbieten oder Vermitteln von sogenannten „Auftragskiller“-Handlungen ist im Roleplay vollständig untersagt. Darunter fällt insbesondere das gezielte Beauftragen, Planen oder Durchführen von Tötungen gegen andere Spieler gegen Bezahlung oder sonstige Gegenleistungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von Auftragsmorden, unabhängig davon ob diese erfolgreich umgesetzt oder lediglich geplant werden, stellt einen Verstoß gegen das Regelwerk dar. Dies gilt auch für indirekte Absprachen oder das Umgehen dieser Regel durch Dritte."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§14.0 Random DeathMatch §14.1 RP-Hintergrund Jede Situation, in der eine Waffe zum Einsatz kommt, muss auf einem nachvollziehbaren RP-Hintergrund basieren. Es reicht nicht, einfach jemanden zu erschießen, nur weil eine Meinungsverschiedenheit besteht oder eine Provokation stattgefunden hat. Gewalt muss immer im RP-Kontext begründet sein. §14.2 Schusscall Pflicht Bevor ein Schuss abgegeben wird, muss eindeutig und sichtbar ein Schusscall gesetzt werden. Dieser kann durch mindestens drei Sekunden aktives Zielen auf die Zielperson oder deren Fahrzeug erfolgen, durch einen Warnschuss in die Luft oder auf den Boden oder durch eine klar erkennbare Textnachricht im Ingame-Chat. Nur so wird der Call gültig und eine RP-Situation mit Waffengebrauch korrekt eingeleitet. §14.3 Gültigkeitsdauer des Schusscalls Ein abgegebener Schusscall bleibt für drei Minuten aktiv. Innerhalb dieses Zeitraums darf gehandelt werden, solange sich die Situation nicht verändert oder aufgelöst hat. Danach muss bei weiterer Eskalation ein neuer Call erfolgen. §14.4 Unzulässige Call-Arten Ein Schusscall über externe Plattformen wie Discord ist nicht erlaubt. Alle Ankündigungen müssen für alle Beteiligten sichtbar und ingame nachvollziehbar sein. §14.5 Besonderheiten bei Ganggebieten Betritt ein Spieler ein aktives Ganggebiet, darf die Gang auch ohne gesonderte Ankündigung handeln – vorausgesetzt, es besteht eine aktive RP-Situation und es wird nicht gegen die Fairness verstoßen. Dennoch ist auch hier das Gambo-RP zu beachten. §14.6 Reaktionszeit & Fairness Ein Schusscall muss mindestens fünf Sekunden vor der eigentlichen Handlung erkennbar erfolgen, damit andere Spieler fair reagieren können. Sollte sich eine betroffene Person in einem Menü befinden (z. B. beim Tanken oder Autospawn), muss gewartet werden, bis sie wieder handlungsfähig ist. §14.7 Sichtbarkeit & Reichweite Der Schusscall muss sichtbar sein. Eine Gültigkeit besteht nur, wenn sich die betroffenen Personen in einem Radius von maximal 20 Metern befinden. Alles darüber hinaus gilt nicht als klar erkennbare Ankündigung. §14.8 Leichen Schändigung & arten Leichenschändigung (Verunglimpfung ausgeschalteter Spieler) ist auf unserem Server strikt untersagt und wird mit einem unmittelbaren Serverausschluss geahndet. §14.9 Leichenschändigungs bedingung Damit eine Handlung als Leichenschändung gewertet werden kann, muss gegenüber einer bewusstlosen, verletzten oder bereits verstorben ausgespielten Person eine vorsätzliche und respektlose Handlung erfolgen. Dabei muss erkennbar sein, dass die Handlung bewusst durchgeführt wurde und nicht versehentlich entstanden ist. Als Leichenschändung gelten insbesondere: wiederholtes Schießen auf eine bereits handlungsunfähige Person, mehrfaches Überfahren oder absichtliches Anfahren einer am Boden liegenden Person, wiederholtes Überlaufen, Anspringen oder anderweitiges Herabwürdigen einer handlungsunfähigen Person, sonstige vergleichbare Handlungen, die ausschließlich der Verhöhnung, Demütigung oder Missachtung der betroffenen Person dienen. Einzelne versehentliche Berührungen, Fahrfehler oder einmalige Missgeschicke gelten in der Regel nicht als Leichenschändung. Für die Bewertung werden stets die Umstände des Einzelfalls, die Absicht des Spielers sowie die Häufigkeit der Handlung berücksichtigt. Die endgültige Einstufung, ob eine Handlung als Leichenschändung zu werten ist und welche Sanktion angemessen erscheint, obliegt dem zuständigen Moderator oder Administrator. Dieser entscheidet unter Berücksichtigung der Schwere des Verstoßes, der vorliegenden Beweise sowie der Gesamtsituation. §14.10 Verbot von Auftragskiller-RP Das Ausführen, Anbieten oder Vermitteln von sogenannten „Auftragskiller“-Handlungen ist im Roleplay vollständig untersagt. Darunter fällt insbesondere das gezielte Beauftragen, Planen oder Durchführen von Tötungen gegen andere Spieler gegen Bezahlung oder sonstige Gegenleistungen. Jegliche Form von Auftragsmorden, unabhängig davon ob diese erfolgreich umgesetzt oder lediglich geplant werden, stellt einen Verstoß gegen das Regelwerk dar. Dies gilt auch für indirekte Absprachen oder das Umgehen dieser Regel durch Dritte.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-15';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-15', 'main-15', 'main-15', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§15.0 Vehicle Death Match', 15, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§15.1"},{"type":"text","text":"Das gezielte Anfahren von Personen mit einem Fahrzeug, mit der Absicht diese zu verletzen oder zu töten, ist untersagt. Insbesondere gilt dies, wenn eine Person mehrfach hintereinander oder mehrere Personen innerhalb kurzer Zeit angefahren werden. Als Richtwert gilt: Wer innerhalb von drei Minuten dieselbe Person mindestens drei Mal oder mehrere Personen in kurzer Abfolge anfährt, handelt regelwidrig und riskiert Konsequenzen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§15.0 Vehicle Death Match' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§15.0 Vehicle Death Match', "order" = 15, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-15-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§15.1"},{"type":"text","text":"Das gezielte Anfahren von Personen mit einem Fahrzeug, mit der Absicht diese zu verletzen oder zu töten, ist untersagt. Insbesondere gilt dies, wenn eine Person mehrfach hintereinander oder mehrere Personen innerhalb kurzer Zeit angefahren werden. Als Richtwert gilt: Wer innerhalb von drei Minuten dieselbe Person mindestens drei Mal oder mehrere Personen in kurzer Abfolge anfährt, handelt regelwidrig und riskiert Konsequenzen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§15.0 Vehicle Death Match §15.1 Das gezielte Anfahren von Personen mit einem Fahrzeug, mit der Absicht diese zu verletzen oder zu töten, ist untersagt. Insbesondere gilt dies, wenn eine Person mehrfach hintereinander oder mehrere Personen innerhalb kurzer Zeit angefahren werden. Als Richtwert gilt: Wer innerhalb von drei Minuten dieselbe Person mindestens drei Mal oder mehrere Personen in kurzer Abfolge anfährt, handelt regelwidrig und riskiert Konsequenzen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

