DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-17';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-17', 'main-17', 'main-17', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§17.1 Das Entführen, Bedrohen , Grundlose umfahren oder Erschießen von Personen innerhalb einer Safe-Zone ist ausdrücklich verboten. Safe-Zones dienen dem Schutz und der Neutralität und sind frei von jeglichen gewaltsamen Handlungen. Sollte sich eine Person jedoch aktiv aus einer laufenden RP-Situation in eine Safe-Zone retten, verliert diese in diesem speziellen Fall ihren Schutzstatus gegenüber der verfolgenden Partei. Dennoch ist auch hier stets auf ein faires und realistisches Ausspielen der Situation zu achten. Zudem dürfen auch Waffen aler art nicht in der Safezone gezogen werden.', 17, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Folgende Orte gelten als Safe-Zones:"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"– Spawnpunkt in River City (Das Parken auf den Staff Parkplätzen ist ebenfalls verboten)"},{"type":"hardBreak"},{"type":"text","text":" – Krankenhaus (Parkplatz Vorne + Hinten)"},{"type":"hardBreak"},{"type":"text","text":" – Feuerwehrwache 1 & 2"},{"type":"hardBreak"},{"type":"text","text":" –Polizei Wache im gebäude als auch"},{"type":"text","text":" beide Parkplätze des Polizeipräsidiumes."},{"type":"hardBreak"},{"type":"text","text":" – Department of Transportation"}]},{"type":"paragraph","content":[{"type":"text","text":"§17.2"},{"type":"text","text":"Das Abschleppen von Fahrzeugen innerhalb dieser Safe-Zones ist ebenfalls untersagt, unabhängig davon, ob ein Spieler anwesend ist oder nicht."}]},{"type":"paragraph","content":[{"type":"text","text":"§17.3 "},{"type":"text","text":"Wenn man während einer Aktiven Verfolgung in eine Safezone \"Flüchtet\" Verliert man den Safezone-\"Status\"."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§17.1 Das Entführen, Bedrohen , Grundlose umfahren oder Erschießen von Personen innerhalb einer Safe-Zone ist ausdrücklich verboten. Safe-Zones dienen dem Schutz und der Neutralität und sind frei von jeglichen gewaltsamen Handlungen. Sollte sich eine Person jedoch aktiv aus einer laufenden RP-Situation in eine Safe-Zone retten, verliert diese in diesem speziellen Fall ihren Schutzstatus gegenüber der verfolgenden Partei. Dennoch ist auch hier stets auf ein faires und realistisches Ausspielen der Situation zu achten. Zudem dürfen auch Waffen aler art nicht in der Safezone gezogen werden.' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§17.1 Das Entführen, Bedrohen , Grundlose umfahren oder Erschießen von Personen innerhalb einer Safe-Zone ist ausdrücklich verboten. Safe-Zones dienen dem Schutz und der Neutralität und sind frei von jeglichen gewaltsamen Handlungen. Sollte sich eine Person jedoch aktiv aus einer laufenden RP-Situation in eine Safe-Zone retten, verliert diese in diesem speziellen Fall ihren Schutzstatus gegenüber der verfolgenden Partei. Dennoch ist auch hier stets auf ein faires und realistisches Ausspielen der Situation zu achten. Zudem dürfen auch Waffen aler art nicht in der Safezone gezogen werden.', "order" = 17, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-17-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Folgende Orte gelten als Safe-Zones:"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"– Spawnpunkt in River City (Das Parken auf den Staff Parkplätzen ist ebenfalls verboten)"},{"type":"hardBreak"},{"type":"text","text":" – Krankenhaus (Parkplatz Vorne + Hinten)"},{"type":"hardBreak"},{"type":"text","text":" – Feuerwehrwache 1 & 2"},{"type":"hardBreak"},{"type":"text","text":" –Polizei Wache im gebäude als auch"},{"type":"text","text":" beide Parkplätze des Polizeipräsidiumes."},{"type":"hardBreak"},{"type":"text","text":" – Department of Transportation"}]},{"type":"paragraph","content":[{"type":"text","text":"§17.2"},{"type":"text","text":"Das Abschleppen von Fahrzeugen innerhalb dieser Safe-Zones ist ebenfalls untersagt, unabhängig davon, ob ein Spieler anwesend ist oder nicht."}]},{"type":"paragraph","content":[{"type":"text","text":"§17.3 "},{"type":"text","text":"Wenn man während einer Aktiven Verfolgung in eine Safezone \"Flüchtet\" Verliert man den Safezone-\"Status\"."}]}]}'::jsonb, '§17.1 Das Entführen, Bedrohen , Grundlose umfahren oder Erschießen von Personen innerhalb einer Safe-Zone ist ausdrücklich verboten. Safe-Zones dienen dem Schutz und der Neutralität und sind frei von jeglichen gewaltsamen Handlungen. Sollte sich eine Person jedoch aktiv aus einer laufenden RP-Situation in eine Safe-Zone retten, verliert diese in diesem speziellen Fall ihren Schutzstatus gegenüber der verfolgenden Partei. Dennoch ist auch hier stets auf ein faires und realistisches Ausspielen der Situation zu achten. Zudem dürfen auch Waffen aler art nicht in der Safezone gezogen werden. Folgende Orte gelten als Safe-Zones: – Spawnpunkt in River City (Das Parken auf den Staff Parkplätzen ist ebenfalls verboten) – Krankenhaus (Parkplatz Vorne + Hinten) – Feuerwehrwache 1 & 2 –Polizei Wache im gebäude als auch beide Parkplätze des Polizeipräsidiumes. – Department of Transportation §17.2 Das Abschleppen von Fahrzeugen innerhalb dieser Safe-Zones ist ebenfalls untersagt, unabhängig davon, ob ein Spieler anwesend ist oder nicht. §17.3 Wenn man während einer Aktiven Verfolgung in eine Safezone "Flüchtet" Verliert man den Safezone-"Status".', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-18';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-18', 'main-18', 'main-18', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§18.0 Gambo Roleplay', 18, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unverhältnismäßiger Waffengebrauch"}]},{"type":"paragraph","content":[{"type":"text","text":"§18.1"},{"type":"text","text":"Ein übermäßiger und grundlos häufiger Einsatz von Waffen ist untersagt. Waffen sollten im RP nur dann verwendet werden, wenn die Situation es realistisch und nachvollziehbar erfordert. Jeder Spieler trägt die volle Verantwortung für den eigenen Waffengebrauch und muss diesen stets angemessen im RP begründen können."}]},{"type":"paragraph","content":[{"type":"text","text":"§18.2"},{"type":"text","text":"Sollte der Umgang mit Waffen als unangemessen, störend oder regelwidrig eingestuft werden, kann dies zu Einschränkungen bis hin zur Sperrung der Waffe oder sogar zu weiteren Sanktionen führen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§18.0 Gambo Roleplay' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§18.0 Gambo Roleplay', "order" = 18, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-18-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unverhältnismäßiger Waffengebrauch"}]},{"type":"paragraph","content":[{"type":"text","text":"§18.1"},{"type":"text","text":"Ein übermäßiger und grundlos häufiger Einsatz von Waffen ist untersagt. Waffen sollten im RP nur dann verwendet werden, wenn die Situation es realistisch und nachvollziehbar erfordert. Jeder Spieler trägt die volle Verantwortung für den eigenen Waffengebrauch und muss diesen stets angemessen im RP begründen können."}]},{"type":"paragraph","content":[{"type":"text","text":"§18.2"},{"type":"text","text":"Sollte der Umgang mit Waffen als unangemessen, störend oder regelwidrig eingestuft werden, kann dies zu Einschränkungen bis hin zur Sperrung der Waffe oder sogar zu weiteren Sanktionen führen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§18.0 Gambo Roleplay Unverhältnismäßiger Waffengebrauch §18.1 Ein übermäßiger und grundlos häufiger Einsatz von Waffen ist untersagt. Waffen sollten im RP nur dann verwendet werden, wenn die Situation es realistisch und nachvollziehbar erfordert. Jeder Spieler trägt die volle Verantwortung für den eigenen Waffengebrauch und muss diesen stets angemessen im RP begründen können. §18.2 Sollte der Umgang mit Waffen als unangemessen, störend oder regelwidrig eingestuft werden, kann dies zu Einschränkungen bis hin zur Sperrung der Waffe oder sogar zu weiteren Sanktionen führen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-19';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-19', 'main-19', 'main-19', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§19.0 Value your Life', 19, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Schutz des eigenen Lebens (Höchstgut-Regel)"}]},{"type":"paragraph","content":[{"type":"text","text":"§19.1"},{"type":"text","text":"Das eigene Leben stellt im Roleplay das höchste Gut dar und muss unter allen Umständen geschützt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§19.2"},{"type":"text","text":" Steht man unter direkter Schusswaffenbedrohung (Waffe ist auf einen gerichtet), ist jegliche Flucht (Wegrennen, Wegfahren) sowie das Ziehen einer eigenen Waffe untersagt. Den Anweisungen des Bedrohenden ist unverzüglich Folge zu leisten, solange diese nicht gegen das Server-Regelwerk verstoßen. Das Ausnutzen von Überzahl gilt ebenso: Steht man mehreren bewaffneten Personen gegenüber, ist Gegenwehr als Verstoß gegen \"Value your Life\" zu werten."}]},{"type":"paragraph","content":[{"type":"text","text":"§19.3"},{"type":"text","text":"Ebenso ist es untersagt, in einem brennenden Fahrzeug sitzen zu bleiben, da dies nicht der realistischen Selbsterhaltungspflicht entspricht."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§19.0 Value your Life' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§19.0 Value your Life', "order" = 19, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-19-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Schutz des eigenen Lebens (Höchstgut-Regel)"}]},{"type":"paragraph","content":[{"type":"text","text":"§19.1"},{"type":"text","text":"Das eigene Leben stellt im Roleplay das höchste Gut dar und muss unter allen Umständen geschützt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§19.2"},{"type":"text","text":" Steht man unter direkter Schusswaffenbedrohung (Waffe ist auf einen gerichtet), ist jegliche Flucht (Wegrennen, Wegfahren) sowie das Ziehen einer eigenen Waffe untersagt. Den Anweisungen des Bedrohenden ist unverzüglich Folge zu leisten, solange diese nicht gegen das Server-Regelwerk verstoßen. Das Ausnutzen von Überzahl gilt ebenso: Steht man mehreren bewaffneten Personen gegenüber, ist Gegenwehr als Verstoß gegen \"Value your Life\" zu werten."}]},{"type":"paragraph","content":[{"type":"text","text":"§19.3"},{"type":"text","text":"Ebenso ist es untersagt, in einem brennenden Fahrzeug sitzen zu bleiben, da dies nicht der realistischen Selbsterhaltungspflicht entspricht."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§19.0 Value your Life Schutz des eigenen Lebens (Höchstgut-Regel) §19.1 Das eigene Leben stellt im Roleplay das höchste Gut dar und muss unter allen Umständen geschützt werden. §19.2 Steht man unter direkter Schusswaffenbedrohung (Waffe ist auf einen gerichtet), ist jegliche Flucht (Wegrennen, Wegfahren) sowie das Ziehen einer eigenen Waffe untersagt. Den Anweisungen des Bedrohenden ist unverzüglich Folge zu leisten, solange diese nicht gegen das Server-Regelwerk verstoßen. Das Ausnutzen von Überzahl gilt ebenso: Steht man mehreren bewaffneten Personen gegenüber, ist Gegenwehr als Verstoß gegen "Value your Life" zu werten. §19.3 Ebenso ist es untersagt, in einem brennenden Fahrzeug sitzen zu bleiben, da dies nicht der realistischen Selbsterhaltungspflicht entspricht.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

