      ('revision-main-20-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Geiselnahmen im Roleplay – Regeln & Vorgaben"}]},{"type":"paragraph","content":[{"type":"text","text":"§20.1"},{"type":"text","text":"– "},{"type":"text","text":"Safe-Zones sind tabu:"},{"type":"text","text":" Geiselnahmen dürfen "},{"type":"text","text":"nicht"},{"type":"text","text":" innerhalb einer Safe-Zone stattfinden."},{"type":"hardBreak"},{"type":"text","text":"§20.2"},{"type":"text","text":"– "},{"type":"text","text":"Geeignetes Fahrzeug:"},{"type":"text","text":" Die Geiselnahme muss in einem "},{"type":"text","text":"Fahrzeug mit mindestens vier Sitzplätzen"},{"type":"text","text":" erfolgen."},{"type":"hardBreak"},{"type":"text","text":"§20.3"},{"type":"text","text":"– "},{"type":"text","text":"Verhandlungsbereitschaft:"},{"type":"text","text":"Sowohl Polizei als auch Geiselnehmer"},{"type":"text","text":" müssen jederzeit zur Verhandlung bereit sein."},{"type":"hardBreak"},{"type":"text","text":"§20.4"},{"type":"text","text":"– "},{"type":"text","text":"Forderungsgrenze:"},{"type":"text","text":" Pro Geisel ist "},{"type":"text","text":"nur eine konkrete Forderung"},{"type":"text","text":" erlaubt – diese muss zudem "},{"type":"text","text":"realistisch und umsetzbar"},{"type":"text","text":" sein."},{"type":"hardBreak"},{"type":"text","text":"§20.5"},{"type":"text","text":"– "},{"type":"text","text":"Einhaltung der Forderungen:"},{"type":"text","text":" Vereinbarte Forderungen müssen "},{"type":"text","text":"von beiden Seiten eingehalten"},{"type":"text","text":" werden."},{"type":"hardBreak"},{"type":"text","text":"§20.6"},{"type":"text","text":"– "},{"type":"text","text":"Freie Flucht:"},{"type":"text","text":" Eine „Freie Flucht“-Forderung darf maximal "},{"type":"text","text":"15 Sekunden"},{"type":"text","text":" lang sein – bei "},{"type":"text","text":"E-Fahrzeugen"},{"type":"text","text":" nur "},{"type":"text","text":"10 Sekunden"},{"type":"text","text":". Bei einer Freien-fl"},{"type":"text","text":"ucht, ist es Verboten während der ausgehandelten Zeit Stopsticks / Spikes etc zu \"Werfen\", zudem ist es auch Verboten währendessen auf das Auto zu Schießen."},{"type":"hardBreak"},{"type":"text","text":"§20.7 "},{"type":"text","text":"– Die Freie Flucht zu Blockieren wird zudem auch als Bruch der Ver"},{"type":"text","text":"ha"},{"type":"text","text":"ndlungen angesehen. "},{"type":"hardBreak"},{"type":"text","text":"§20."},{"type":"text","text":"8"},{"type":"text","text":"– "},{"type":"text","text":"Geiseln pro Geiselnehmer:"},{"type":"text","text":" Jeder Geiselnehmer darf "},{"type":"text","text":"maximal eine Geisel"},{"type":"text","text":" nehmen."},{"type":"hardBreak"},{"type":"text","text":"§20."},{"type":"text","text":"9"},{"type":"text","text":"– "},{"type":"text","text":"Zeitlimit:"},{"type":"text","text":" Eine Geisel darf "},{"type":"text","text":"nicht länger als 20 Minuten"},{"type":"text","text":" festgehalten werden. Danach muss die Geisel freigelassen werden."},{"type":"hardBreak"},{"type":"text","text":"§20."},{"type":"text","text":"10"},{"type":"text","text":"– "},{"type":"text","text":"Sicherstellung der Unversehrtheit:"},{"type":"text","text":"Alle Beteiligten"},{"type":"text","text":", "},{"type":"text","text":"Polizei wie Geiselnehmer müssen sich bemühen, die Geisel während der gesamten Situation zu "},{"type":"text","text":"schützen"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":"§20."},{"type":"text","text":"11"},{"type":"text","text":"– "},{"type":"text","text":"Stürmungsrecht der Polizei:"},{"type":"text","text":" Die Polizei darf die Situation "},{"type":"text","text":"stürmen"},{"type":"text","text":", wenn "},{"type":"text","text":"keine akute Gefahr"},{"type":"text","text":" mehr für die Geisel besteht – zum Beispiel, wenn "},{"type":"text","text":"niemand mehr aktiv auf sie zielt"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":"§20.1"},{"type":"text","text":"2"},{"type":"text","text":"– "},{"type":"text","text":"Sonderregelung für Dienst-Fraktionen:"},{"type":"text","text":"Rettungsdienst, Feuerwehr und ADAC "},{"type":"text","text":"dürfen "},{"type":"text","text":"nur dann"},{"type":"text","text":" als Geiseln genommen werden, wenn eine "},{"type":"text","text":"akute Ausnahmesituation"},{"type":"text","text":" vorliegt – etwa wenn Geiselnehmer von der Polizei verfolgt werden und keine andere Fluchtmöglichkeit mehr haben."},{"type":"hardBreak"},{"type":"text","text":"§20.1"},{"type":"text","text":"3"},{"type":"text","text":"– "},{"type":"text","text":"Kinderschutz:"},{"type":"text","text":"Kinder dürfen niemals"},{"type":"text","text":" als Geiseln genommen werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§20.1"},{"type":"text","text":"4"},{"type":"text","text":"Schein-Geiseln sind ausnahmslos unzulässig, da sie den Grundsatz fairen Rollenspiels verletzen."}]},{"type":"paragraph","content":[{"type":"text","text":"§20.1"},{"type":"text","text":"5"},{"type":"text","text":"Die Geiselnahme eines Polizeibeamten ist erst ab einer Mindestpräsenz von 3 aktiven Polizeikräften im Rollenspiel zulässig. Die Unterschreitung dieser Mindestanzahl ist strikt untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§20.16 "},{"type":"text","text":"Zwischen zwei Geiselnahmen muss ein Mindestabstand von 30 Minuten liegen. Geiselnahmen, die innerhalb dieses Zeitraums erneut begonnen werden, sind unzulässig."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§20.0 Geiselnahmen Geiselnahmen im Roleplay – Regeln & Vorgaben §20.1 – Safe-Zones sind tabu: Geiselnahmen dürfen nicht innerhalb einer Safe-Zone stattfinden. §20.2 – Geeignetes Fahrzeug: Die Geiselnahme muss in einem Fahrzeug mit mindestens vier Sitzplätzen erfolgen. §20.3 – Verhandlungsbereitschaft: Sowohl Polizei als auch Geiselnehmer müssen jederzeit zur Verhandlung bereit sein. §20.4 – Forderungsgrenze: Pro Geisel ist nur eine konkrete Forderung erlaubt – diese muss zudem realistisch und umsetzbar sein. §20.5 – Einhaltung der Forderungen: Vereinbarte Forderungen müssen von beiden Seiten eingehalten werden. §20.6 – Freie Flucht: Eine „Freie Flucht“-Forderung darf maximal 15 Sekunden lang sein – bei E-Fahrzeugen nur 10 Sekunden . Bei einer Freien-fl ucht, ist es Verboten während der ausgehandelten Zeit Stopsticks / Spikes etc zu "Werfen", zudem ist es auch Verboten währendessen auf das Auto zu Schießen. §20.7 – Die Freie Flucht zu Blockieren wird zudem auch als Bruch der Ver ha ndlungen angesehen. §20. 8 – Geiseln pro Geiselnehmer: Jeder Geiselnehmer darf maximal eine Geisel nehmen. §20. 9 – Zeitlimit: Eine Geisel darf nicht länger als 20 Minuten festgehalten werden. Danach muss die Geisel freigelassen werden. §20. 10 – Sicherstellung der Unversehrtheit: Alle Beteiligten , Polizei wie Geiselnehmer müssen sich bemühen, die Geisel während der gesamten Situation zu schützen . §20. 11 – Stürmungsrecht der Polizei: Die Polizei darf die Situation stürmen , wenn keine akute Gefahr mehr für die Geisel besteht – zum Beispiel, wenn niemand mehr aktiv auf sie zielt . §20.1 2 – Sonderregelung für Dienst-Fraktionen: Rettungsdienst, Feuerwehr und ADAC dürfen nur dann als Geiseln genommen werden, wenn eine akute Ausnahmesituation vorliegt – etwa wenn Geiselnehmer von der Polizei verfolgt werden und keine andere Fluchtmöglichkeit mehr haben. §20.1 3 – Kinderschutz: Kinder dürfen niemals als Geiseln genommen werden. §20.1 4 Schein-Geiseln sind ausnahmslos unzulässig, da sie den Grundsatz fairen Rollenspiels verletzen. §20.1 5 Die Geiselnahme eines Polizeibeamten ist erst ab einer Mindestpräsenz von 3 aktiven Polizeikräften im Rollenspiel zulässig. Die Unterschreitung dieser Mindestanzahl ist strikt untersagt. §20.16 Zwischen zwei Geiselnahmen muss ein Mindestabstand von 30 Minuten liegen. Geiselnahmen, die innerhalb dieses Zeitraums erneut begonnen werden, sind unzulässig.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

