    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tier-RP & unzulässige Charakterdarstellungen"}]},{"type":"paragraph","content":[{"type":"text","text":"§21.1"},{"type":"text","text":"Das Ausspielen von Tier-RP ist auf unserem Server "},{"type":"text","text":"strengstens untersagt"},{"type":"text","text":" und kann entsprechende Konsequenzen nach sich ziehen."},{"type":"hardBreak"},{"type":"text","text":" Es gibt "},{"type":"text","text":"keinerlei Ausnahmen"},{"type":"text","text":" von dieser Regel – "},{"type":"text","text":"das gilt auch für"},{"type":"text","text":" andere tierähnliche Charaktere."}]},{"type":"paragraph","content":[{"type":"text","text":"§21.2"},{"type":"text","text":"Sollte die Identität des Charakters "},{"type":"text","text":"nicht eindeutig menschlich erkennbar"},{"type":"text","text":" sein, ist der Skin "},{"type":"text","text":"nicht erlaubt"},{"type":"text","text":" und der Charakter darf im RP nicht genutzt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§21.3 "},{"type":"text","text":"Furry-Skins sind nicht am Spawn und im RP erlaubt"}]},{"type":"paragraph","content":[{"type":"text","text":"§21.4"},{"type":"text","text":"Charaktere müssen ein realistisches und zum Serverkonzept passendes Erscheinungsbild besitzen. Unrealistische oder auffällige Darstellungen, die nicht in das angestrebte Roleplay passen, sind nicht erlaubt."}]},{"type":"paragraph","content":[{"type":"text","text":"Hierzu zählen insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"Tiermasken oder vollständige Tierkostüme,"}]},{"type":"paragraph","content":[{"type":"text","text":"stark fantasiebezogene Accessoires oder Outfits,"}]},{"type":"paragraph","content":[{"type":"text","text":"sowie vergleichbare kosmetische Gegenstände, die den Realismus des Roleplays beeinträchtigen."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Serverteam kann im Einzelfall entscheiden, ob ein Charakterdesign mit dem Serverkonzept vereinbar ist oder angepasst werden muss."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§21.0 Tier RP' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
