    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§21.0 Tier RP', "order" = 21, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-21-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tier-RP & unzulässige Charakterdarstellungen"}]},{"type":"paragraph","content":[{"type":"text","text":"§21.1"},{"type":"text","text":"Das Ausspielen von Tier-RP ist auf unserem Server "},{"type":"text","text":"strengstens untersagt"},{"type":"text","text":" und kann entsprechende Konsequenzen nach sich ziehen."},{"type":"hardBreak"},{"type":"text","text":" Es gibt "},{"type":"text","text":"keinerlei Ausnahmen"},{"type":"text","text":" von dieser Regel – "},{"type":"text","text":"das gilt auch für"},{"type":"text","text":" andere tierähnliche Charaktere."}]},{"type":"paragraph","content":[{"type":"text","text":"§21.2"},{"type":"text","text":"Sollte die Identität des Charakters "},{"type":"text","text":"nicht eindeutig menschlich erkennbar"},{"type":"text","text":" sein, ist der Skin "},{"type":"text","text":"nicht erlaubt"},{"type":"text","text":" und der Charakter darf im RP nicht genutzt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§21.3 "},{"type":"text","text":"Furry-Skins sind nicht am Spawn und im RP erlaubt"}]},{"type":"paragraph","content":[{"type":"text","text":"§21.4"},{"type":"text","text":"Charaktere müssen ein realistisches und zum Serverkonzept passendes Erscheinungsbild besitzen. Unrealistische oder auffällige Darstellungen, die nicht in das angestrebte Roleplay passen, sind nicht erlaubt."}]},{"type":"paragraph","content":[{"type":"text","text":"Hierzu zählen insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"Tiermasken oder vollständige Tierkostüme,"}]},{"type":"paragraph","content":[{"type":"text","text":"stark fantasiebezogene Accessoires oder Outfits,"}]},{"type":"paragraph","content":[{"type":"text","text":"sowie vergleichbare kosmetische Gegenstände, die den Realismus des Roleplays beeinträchtigen."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Serverteam kann im Einzelfall entscheiden, ob ein Charakterdesign mit dem Serverkonzept vereinbar ist oder angepasst werden muss."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§21.0 Tier RP Tier-RP & unzulässige Charakterdarstellungen §21.1 Das Ausspielen von Tier-RP ist auf unserem Server strengstens untersagt und kann entsprechende Konsequenzen nach sich ziehen. Es gibt keinerlei Ausnahmen von dieser Regel – das gilt auch für andere tierähnliche Charaktere. §21.2 Sollte die Identität des Charakters nicht eindeutig menschlich erkennbar sein, ist der Skin nicht erlaubt und der Charakter darf im RP nicht genutzt werden. §21.3 Furry-Skins sind nicht am Spawn und im RP erlaubt §21.4 Charaktere müssen ein realistisches und zum Serverkonzept passendes Erscheinungsbild besitzen. Unrealistische oder auffällige Darstellungen, die nicht in das angestrebte Roleplay passen, sind nicht erlaubt. Hierzu zählen insbesondere: Tiermasken oder vollständige Tierkostüme, stark fantasiebezogene Accessoires oder Outfits, sowie vergleichbare kosmetische Gegenstände, die den Realismus des Roleplays beeinträchtigen. Das Serverteam kann im Einzelfall entscheiden, ob ein Charakterdesign mit dem Serverkonzept vereinbar ist oder angepasst werden muss.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-22';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-22', 'main-22', 'main-22', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§22.0 Medic Roleplay', 22, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
