      ('revision-main-22-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Medic Roleplay (Rettungsdienst-RP)"}]},{"type":"paragraph","content":[{"type":"text","text":"§22.1"},{"type":"text","text":"Das Medic Roleplay ist verpflichtend und muss "},{"type":"text","text":"jederzeit ernsthaft ausgespielt"},{"type":"text","text":" werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.2 "},{"type":"text","text":"Während eine medizinische Behandlung stattfindet, gilt im Umkreis von "},{"type":"text","text":"5 Metern eine Safe-Zone"},{"type":"text","text":" – Einsätze des Rettungsdienstes dürfen "},{"type":"text","text":"nicht gestört oder angegriffen"},{"type":"text","text":" werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.3 "},{"type":"text","text":"Verletzte Personen "},{"type":"text","text":"müssen mit einem RTW, KTW oder ITW"},{"type":"text","text":" transportiert werden."},{"type":"hardBreak"},{"type":"text","text":" Eine Ausnahme besteht nur, wenn aktuell "},{"type":"text","text":"keines dieser Fahrzeuge verfügbar"},{"type":"text","text":" ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.4 "},{"type":"text","text":"Eigenschutz geht vor:"},{"type":"text","text":" Einsatzkräfte dürfen sich "},{"type":"text","text":"nicht unnötig in Gefahr bringen"},{"type":"text","text":". Bei aktiver Bedrohung ist der Rückzug erlaubt."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.5 "},{"type":"text","text":"Nach dem eigenen Tod muss "},{"type":"text","text":"verpflichtend der \"EMS Call\" Button gedrückt"},{"type":"text","text":" werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.6 "},{"type":"text","text":"Befindet sich "},{"type":"text","text":"kein Mitglied des Rettungsdienstes"},{"type":"text","text":" im Dienst, muss man "},{"type":"text","text":"mindestens 5 Minuten"},{"type":"text","text":" warten, bevor man respawnen darf."},{"type":"hardBreak"},{"type":"text","text":" Sind "},{"type":"text","text":"aktive Medics"},{"type":"text","text":" im Dienst, beträgt die Wartezeit "},{"type":"text","text":"mindestens 7 Minuten"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.7 "},{"type":"text","text":"Befindet sich "},{"type":"text","text":"Rettungspersonal in der Nähe"},{"type":"text","text":", ist das Respawnen "},{"type":"text","text":"nicht erlaubt"},{"type":"text","text":" – man muss die Versorgung durch das Rettungsteam abwarten."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.8 "},{"type":"text","text":"Ausschließlich der offizielle Rettungsdienst ist befugt, Medic RP zu betreiben."},{"type":"text","text":" Jegliches eigenmächtige Medic RP durch Nicht-Mitglieder wird als "},{"type":"text","text":"Regelverstoß"},{"type":"text","text":" gewertet."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.8 "},{"type":"text","text":"Medic RP Dürfen auch Zivilisten / Polizisten etc auch ausspielen wenn "},{"type":"text","text":"KEIN "},{"type":"text","text":"einziger Medic Online ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§22.9 "},{"type":"text","text":"Sich bewusst „tot zu stellen“ oder den eigenen Charakter ohne nachvollziehbaren RP-Grund als tot darzustellen, ist untersagt. Dieses Verhalten gilt als RP-Verweigerung, da dadurch laufende RP-Situationen – insbesondere Maßnahmen des Rettungsdienstes, der Polizei oder anderer Spieler – absichtlich blockiert oder umgangen werden."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§22.0 Medic Roleplay Medic Roleplay (Rettungsdienst-RP) §22.1 Das Medic Roleplay ist verpflichtend und muss jederzeit ernsthaft ausgespielt werden. §22.2 Während eine medizinische Behandlung stattfindet, gilt im Umkreis von 5 Metern eine Safe-Zone – Einsätze des Rettungsdienstes dürfen nicht gestört oder angegriffen werden. §22.3 Verletzte Personen müssen mit einem RTW, KTW oder ITW transportiert werden. Eine Ausnahme besteht nur, wenn aktuell keines dieser Fahrzeuge verfügbar ist. §22.4 Eigenschutz geht vor: Einsatzkräfte dürfen sich nicht unnötig in Gefahr bringen . Bei aktiver Bedrohung ist der Rückzug erlaubt. §22.5 Nach dem eigenen Tod muss verpflichtend der "EMS Call" Button gedrückt werden. §22.6 Befindet sich kein Mitglied des Rettungsdienstes im Dienst, muss man mindestens 5 Minuten warten, bevor man respawnen darf. Sind aktive Medics im Dienst, beträgt die Wartezeit mindestens 7 Minuten . §22.7 Befindet sich Rettungspersonal in der Nähe , ist das Respawnen nicht erlaubt – man muss die Versorgung durch das Rettungsteam abwarten. §22.8 Ausschließlich der offizielle Rettungsdienst ist befugt, Medic RP zu betreiben. Jegliches eigenmächtige Medic RP durch Nicht-Mitglieder wird als Regelverstoß gewertet. §22.8 Medic RP Dürfen auch Zivilisten / Polizisten etc auch ausspielen wenn KEIN einziger Medic Online ist. §22.9 Sich bewusst „tot zu stellen“ oder den eigenen Charakter ohne nachvollziehbaren RP-Grund als tot darzustellen, ist untersagt. Dieses Verhalten gilt als RP-Verweigerung, da dadurch laufende RP-Situationen – insbesondere Maßnahmen des Rettungsdienstes, der Polizei oder anderer Spieler – absichtlich blockiert oder umgangen werden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

