    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§23.0 Waffen', "order" = 23, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-23-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§23.1 "},{"type":"text","text":"Das Mitführen oder Benutzen von Waffen ist in "},{"type":"text","text":"allen Safe-Zonen strengstens untersagt"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":" Dazu zählen unter anderem: "},{"type":"text","text":"Messer, Pistolen, Gewehre und andere Waffen"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§23."},{"type":"text","text":"2 "},{"type":"text","text":"Das "},{"type":"text","text":"Schießen mit Waffen unter Wasser"},{"type":"text","text":" ist "},{"type":"text","text":"nicht erlaubt"},{"type":"text","text":" – ebenso ist das "},{"type":"text","text":"Tasern unter Wasser verboten"},{"type":"text","text":", da dies in keiner Weise realistisch wäre."}]},{"type":"paragraph","content":[{"type":"text","text":"§23."},{"type":"text","text":"3 "},{"type":"text","text":"Der Befehl "},{"type":"text","text":"„Zieht Waffe“ (ZW)"},{"type":"text","text":" ist auf unserem Server "},{"type":"text","text":"keine Pflicht"},{"type":"text","text":". Es liegt im Ermessen des Spielers, ob er diesen zur Verdeutlichung verwendet, doch er ersetzt "},{"type":"text","text":"keine RP-Handlung"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§23."},{"type":"text","text":"4 "},{"type":"text","text":"Es gibt auf unserem Server "},{"type":"text","text":"keine sogenannten „Fake-Waffen“"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":"Jede gezogene Waffe ist als echt zu betrachten"},{"type":"text","text":" – auch Spielzeuge, Airsoft-Waffen o. ä. gelten als "},{"type":"text","text":"vollwertige Bedrohung"},{"type":"text","text":" innerhalb des Roleplays."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§23.0 Waffen §23.1 Das Mitführen oder Benutzen von Waffen ist in allen Safe-Zonen strengstens untersagt . Dazu zählen unter anderem: Messer, Pistolen, Gewehre und andere Waffen . §23. 2 Das Schießen mit Waffen unter Wasser ist nicht erlaubt – ebenso ist das Tasern unter Wasser verboten , da dies in keiner Weise realistisch wäre. §23. 3 Der Befehl „Zieht Waffe“ (ZW) ist auf unserem Server keine Pflicht . Es liegt im Ermessen des Spielers, ob er diesen zur Verdeutlichung verwendet, doch er ersetzt keine RP-Handlung . §23. 4 Es gibt auf unserem Server keine sogenannten „Fake-Waffen“ . Jede gezogene Waffe ist als echt zu betrachten – auch Spielzeuge, Airsoft-Waffen o. ä. gelten als vollwertige Bedrohung innerhalb des Roleplays.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
