      ('rule-main-24', 'main-24', 'main-24', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§24.0 Drohnen Regel', 24, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Drohnenverwendung"}]},{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"4"},{"type":"text","text":".1 "},{"type":"text","text":"Das "},{"type":"text","text":"Verwenden von Drohnen ist in allen Safe-Zonen sowie in der unmittelbaren Nähe eines aktiven Modcalls untersagt"},{"type":"text","text":". Dies dient dem Schutz der Privatsphäre und der ungestörten Bearbeitung von Supportfällen."}]},{"type":"paragraph","content":[{"type":"text","text":"§24."},{"type":"text","text":"2 "},{"type":"text","text":"Auch in "},{"type":"text","text":"Gang-Gebieten ist der Einsatz von Drohnen strengstens verboten"},{"type":"text","text":", um unfaire Informationsvorteile oder Metagaming zu verhindern."}]},{"type":"paragraph","content":[{"type":"text","text":"§24."},{"type":"text","text":"3 "},{"type":"text","text":"Drohnen dürfen nur in öffentlichen Bereichen außerhalb dieser Zonen genutzt werden – stets unter Beachtung der allgemeinen RP-Regeln."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§24.0 Drohnen Regel' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§24.0 Drohnen Regel', "order" = 24, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-24-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Drohnenverwendung"}]},{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"4"},{"type":"text","text":".1 "},{"type":"text","text":"Das "},{"type":"text","text":"Verwenden von Drohnen ist in allen Safe-Zonen sowie in der unmittelbaren Nähe eines aktiven Modcalls untersagt"},{"type":"text","text":". Dies dient dem Schutz der Privatsphäre und der ungestörten Bearbeitung von Supportfällen."}]},{"type":"paragraph","content":[{"type":"text","text":"§24."},{"type":"text","text":"2 "},{"type":"text","text":"Auch in "},{"type":"text","text":"Gang-Gebieten ist der Einsatz von Drohnen strengstens verboten"},{"type":"text","text":", um unfaire Informationsvorteile oder Metagaming zu verhindern."}]},{"type":"paragraph","content":[{"type":"text","text":"§24."},{"type":"text","text":"3 "},{"type":"text","text":"Drohnen dürfen nur in öffentlichen Bereichen außerhalb dieser Zonen genutzt werden – stets unter Beachtung der allgemeinen RP-Regeln."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§24.0 Drohnen Regel Drohnenverwendung §2 4 .1 Das Verwenden von Drohnen ist in allen Safe-Zonen sowie in der unmittelbaren Nähe eines aktiven Modcalls untersagt . Dies dient dem Schutz der Privatsphäre und der ungestörten Bearbeitung von Supportfällen. §24. 2 Auch in Gang-Gebieten ist der Einsatz von Drohnen strengstens verboten , um unfaire Informationsvorteile oder Metagaming zu verhindern. §24. 3 Drohnen dürfen nur in öffentlichen Bereichen außerhalb dieser Zonen genutzt werden – stets unter Beachtung der allgemeinen RP-Regeln.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-25';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-25', 'main-25', 'main-25', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§25.0 RP Flucht', 25, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unzulässige RP-Flucht"}]},{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"5"},{"type":"text","text":".1 "},{"type":"text","text":"Das "},{"type":"text","text":"unerlaubte Verlassen einer aktiven RP-Situation"},{"type":"text","text":" – auch bekannt als "},{"type":"text","text":"RP-Flucht"},{"type":"text","text":" – ist auf unserem Server "},{"type":"text","text":"nicht gestattet"},{"type":"text","text":", da es den Spielfluss und die Immersion erheblich stört."}]},{"type":"paragraph","content":[{"type":"text","text":"Als RP-Flucht gelten unter anderem folgende Handlungen:"},{"type":"hardBreak"},{"type":"text","text":" – Das Entfernen von der RP-Situation um mehr als 50 Meter ohne ersichtlichen RP-Grund."},{"type":"hardBreak"},{"type":"text","text":" – Das Verlassen des Ingame-Servers während einer laufenden Szene."},{"type":"hardBreak"},{"type":"text","text":" – Das Wechseln des Teams oder Jobs, um sich einer Situation zu entziehen."}]},{"type":"paragraph","content":[{"type":"text","text":"§25."},{"type":"text","text":"2 "},{"type":"text","text":"Jeder Spieler ist verpflichtet, eine begonnene RP-Situation "},{"type":"text","text":"vollständig und realistisch zu Ende zu spielen"},{"type":"text","text":". Zuwiderhandlungen können zu Verwarnungen oder weiteren Konsequenzen führen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§25.0 RP Flucht' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§25.0 RP Flucht', "order" = 25, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-25-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unzulässige RP-Flucht"}]},{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"5"},{"type":"text","text":".1 "},{"type":"text","text":"Das "},{"type":"text","text":"unerlaubte Verlassen einer aktiven RP-Situation"},{"type":"text","text":" – auch bekannt als "},{"type":"text","text":"RP-Flucht"},{"type":"text","text":" – ist auf unserem Server "},{"type":"text","text":"nicht gestattet"},{"type":"text","text":", da es den Spielfluss und die Immersion erheblich stört."}]},{"type":"paragraph","content":[{"type":"text","text":"Als RP-Flucht gelten unter anderem folgende Handlungen:"},{"type":"hardBreak"},{"type":"text","text":" – Das Entfernen von der RP-Situation um mehr als 50 Meter ohne ersichtlichen RP-Grund."},{"type":"hardBreak"},{"type":"text","text":" – Das Verlassen des Ingame-Servers während einer laufenden Szene."},{"type":"hardBreak"},{"type":"text","text":" – Das Wechseln des Teams oder Jobs, um sich einer Situation zu entziehen."}]},{"type":"paragraph","content":[{"type":"text","text":"§25."},{"type":"text","text":"2 "},{"type":"text","text":"Jeder Spieler ist verpflichtet, eine begonnene RP-Situation "},{"type":"text","text":"vollständig und realistisch zu Ende zu spielen"},{"type":"text","text":". Zuwiderhandlungen können zu Verwarnungen oder weiteren Konsequenzen führen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§25.0 RP Flucht Unzulässige RP-Flucht §2 5 .1 Das unerlaubte Verlassen einer aktiven RP-Situation – auch bekannt als RP-Flucht – ist auf unserem Server nicht gestattet , da es den Spielfluss und die Immersion erheblich stört. Als RP-Flucht gelten unter anderem folgende Handlungen: – Das Entfernen von der RP-Situation um mehr als 50 Meter ohne ersichtlichen RP-Grund. – Das Verlassen des Ingame-Servers während einer laufenden Szene. – Das Wechseln des Teams oder Jobs, um sich einer Situation zu entziehen. §25. 2 Jeder Spieler ist verpflichtet, eine begonnene RP-Situation vollständig und realistisch zu Ende zu spielen . Zuwiderhandlungen können zu Verwarnungen oder weiteren Konsequenzen führen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

