      ('revision-main-26-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Support-Flucht"}]},{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"6"},{"type":"text","text":".1 "},{"type":"text","text":"Das absichtliche "},{"type":"text","text":"Flüchten vor einem Supporter"},{"type":"text","text":" ist "},{"type":"text","text":"strengstens untersagt"},{"type":"text","text":" und wird als Support-Flucht gewertet. Jeder Spieler ist dazu verpflichtet, bei einem eingeleiteten Supportfall mitzuwirken und erreichbar zu bleiben."}]},{"type":"paragraph","content":[{"type":"text","text":"Folgende Handlungen gelten als Support-Flucht:"},{"type":"hardBreak"},{"type":"text","text":" – Das Entfernen um mehr als 50 Meter vom Supporter ohne Zustimmung."},{"type":"hardBreak"},{"type":"text","text":" – Das Verlassen des Ingame-Servers während eines laufenden Supports."},{"type":"hardBreak"},{"type":"text","text":" – Das Wechseln des Jobs oder Teams, um sich dem Support zu entziehen."}]},{"type":"paragraph","content":[{"type":"text","text":"§26."},{"type":"text","text":"2 "},{"type":"text","text":"Support-Situationen sind genauso verbindlich wie RP-Situationen. Ein Verstoß gegen diese Regel kann direkte Sanktionen nach sich ziehen."}]}]}'::jsonb, '§26.0 Support Flucht Support-Flucht §2 6 .1 Das absichtliche Flüchten vor einem Supporter ist strengstens untersagt und wird als Support-Flucht gewertet. Jeder Spieler ist dazu verpflichtet, bei einem eingeleiteten Supportfall mitzuwirken und erreichbar zu bleiben. Folgende Handlungen gelten als Support-Flucht: – Das Entfernen um mehr als 50 Meter vom Supporter ohne Zustimmung. – Das Verlassen des Ingame-Servers während eines laufenden Supports. – Das Wechseln des Jobs oder Teams, um sich dem Support zu entziehen. §26. 2 Support-Situationen sind genauso verbindlich wie RP-Situationen. Ein Verstoß gegen diese Regel kann direkte Sanktionen nach sich ziehen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

