  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Überfälle auf Banken und Juweliere"}]},{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"8"},{"type":"text","text":".1 "},{"type":"text","text":"Überfälle auf die "},{"type":"text","text":"Bank"},{"type":"text","text":" müssen immer "},{"type":"text","text":"zwei Personen"},{"type":"text","text":" involvieren. Ein Überfall kann nur dann durchgeführt werden, wenn mindestens zwei Spieler aktiv an der Tat beteiligt sind."}]},{"type":"paragraph","content":[{"type":"text","text":"§28."},{"type":"text","text":"2 "},{"type":"text","text":"Für alle anderen "},{"type":"text","text":"ausraubbaren Gegenstände"},{"type":"text","text":", wie zum Beispiel "},{"type":"text","text":"Kassen"},{"type":"text","text":", "},{"type":"text","text":"Geldautomaten"},{"type":"text","text":" oder ähnliche Ziele, ist es auch "},{"type":"text","text":"einzelnen Spielern"},{"type":"text","text":" gestattet, diese zu überfallen."}]},{"type":"paragraph","content":[{"type":"text","text":"§28."},{"type":"text","text":"3 "},{"type":"text","text":"Das Ziel dieser Regel ist es, bestimmte Überfälle, "},{"type":"text","text":"auf die"},{"type":"text","text":" Banken, als größere, komplexere Aktionen darzustellen, bei denen Teamarbeit erforderlich ist, während kleinere Raubüberfälle durch Einzelpersonen durchgeführt werden können."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§28.0 Überfälle' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
