    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§28.0 Überfälle', "order" = 28, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-28-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Überfälle auf Banken und Juweliere"}]},{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"8"},{"type":"text","text":".1 "},{"type":"text","text":"Überfälle auf die "},{"type":"text","text":"Bank"},{"type":"text","text":" müssen immer "},{"type":"text","text":"zwei Personen"},{"type":"text","text":" involvieren. Ein Überfall kann nur dann durchgeführt werden, wenn mindestens zwei Spieler aktiv an der Tat beteiligt sind."}]},{"type":"paragraph","content":[{"type":"text","text":"§28."},{"type":"text","text":"2 "},{"type":"text","text":"Für alle anderen "},{"type":"text","text":"ausraubbaren Gegenstände"},{"type":"text","text":", wie zum Beispiel "},{"type":"text","text":"Kassen"},{"type":"text","text":", "},{"type":"text","text":"Geldautomaten"},{"type":"text","text":" oder ähnliche Ziele, ist es auch "},{"type":"text","text":"einzelnen Spielern"},{"type":"text","text":" gestattet, diese zu überfallen."}]},{"type":"paragraph","content":[{"type":"text","text":"§28."},{"type":"text","text":"3 "},{"type":"text","text":"Das Ziel dieser Regel ist es, bestimmte Überfälle, "},{"type":"text","text":"auf die"},{"type":"text","text":" Banken, als größere, komplexere Aktionen darzustellen, bei denen Teamarbeit erforderlich ist, während kleinere Raubüberfälle durch Einzelpersonen durchgeführt werden können."}]}]}'::jsonb, '§28.0 Überfälle Überfälle auf Banken und Juweliere §2 8 .1 Überfälle auf die Bank müssen immer zwei Personen involvieren. Ein Überfall kann nur dann durchgeführt werden, wenn mindestens zwei Spieler aktiv an der Tat beteiligt sind. §28. 2 Für alle anderen ausraubbaren Gegenstände , wie zum Beispiel Kassen , Geldautomaten oder ähnliche Ziele, ist es auch einzelnen Spielern gestattet, diese zu überfallen. §28. 3 Das Ziel dieser Regel ist es, bestimmte Überfälle, auf die Banken, als größere, komplexere Aktionen darzustellen, bei denen Teamarbeit erforderlich ist, während kleinere Raubüberfälle durch Einzelpersonen durchgeführt werden können.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

