      ('revision-main-29-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§2"},{"type":"text","text":"9"},{"type":"text","text":".1 "},{"type":"text","text":"Der Einsatz von Falschgeld ist "},{"type":"text","text":"im RP grundsätzlich erlaubt"},{"type":"text","text":", solange er "},{"type":"text","text":"realistisch ausgespielt"},{"type":"text","text":" wird und "},{"type":"text","text":"nicht zum massiven Wirtschaftsmissbrauch"},{"type":"text","text":" führt. Es darf "},{"type":"text","text":"nicht dauerhaft als primäre Einnahmequelle"},{"type":"text","text":" genutzt werden. Ein Missbrauch kann durch das Team jederzeit geahndet werden."}]}]}'::jsonb, '§29.0 Falschgeld §2 9 .1 Der Einsatz von Falschgeld ist im RP grundsätzlich erlaubt , solange er realistisch ausgespielt wird und nicht zum massiven Wirtschaftsmissbrauch führt. Es darf nicht dauerhaft als primäre Einnahmequelle genutzt werden. Ein Missbrauch kann durch das Team jederzeit geahndet werden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

