    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Verbotene und erlaubte Gamepass-Nutzung und Tools"}]},{"type":"paragraph","content":[{"type":"text","text":"§"},{"type":"text","text":"31"},{"type":"text","text":".1 "},{"type":"text","text":"Das "},{"type":"text","text":"Nutzen des Gamepasses \"Instant Refuel\""},{"type":"text","text":" ist auf unserem Server "},{"type":"text","text":"verboten"},{"type":"text","text":". Dies verstößt gegen die Prinzipien des fairen Gameplays und verzerrt das Spielerlebnis."}]},{"type":"paragraph","content":[{"type":"text","text":"§31."},{"type":"text","text":"2"},{"type":"text","text":"Das "},{"type":"text","text":"Verwenden des Scanners"},{"type":"text","text":" ist ebenfalls "},{"type":"text","text":"verboten"},{"type":"text","text":" und wird als "},{"type":"text","text":"Meta Gaming"},{"type":"text","text":" angesehen. Informationen, die auf diesem Weg erhalten werden, dürfen nicht in das Ingame-RP eingebracht werden, da dies das Spiel unfair macht."}]},{"type":"paragraph","content":[{"type":"text","text":"§31."},{"type":"text","text":"3"},{"type":"text","text":"Das "},{"type":"text","text":"Nutzen des Polizeihelikopters"},{"type":"text","text":" ist "},{"type":"text","text":"verboten"},{"type":"text","text":" und fällt unter "},{"type":"text","text":"Meta Gaming"},{"type":"text","text":". Das Fliegen und die Nutzung des Helikopters für die Erfassung von Informationen oder Überwachung von Spielern sind nicht gestattet, da sie ebenfalls den Verlauf des Spiels manipulieren können."}]},{"type":"paragraph","content":[{"type":"text","text":"§31."},{"type":"text","text":"4"},{"type":"text","text":"Das "},{"type":"text","text":"Nutzen der \"Spray Can\""},{"type":"text","text":" (Sprühdose) ist "},{"type":"text","text":"erlaubt"},{"type":"text","text":", jedoch sollte man dabei stets das "},{"type":"text","text":"Ausmaß"},{"type":"text","text":" im Blick behalten. Übermäßiger oder unnötiger Einsatz dieser Dosen, der das RP stört oder unrealistisch wirkt, sollte vermieden werden."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§31.0 Gamepässe und Werkzeuge' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
