      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§31.0 Gamepässe und Werkzeuge', "order" = 31, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-31-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Verbotene und erlaubte Gamepass-Nutzung und Tools"}]},{"type":"paragraph","content":[{"type":"text","text":"§"},{"type":"text","text":"31"},{"type":"text","text":".1 "},{"type":"text","text":"Das "},{"type":"text","text":"Nutzen des Gamepasses \"Instant Refuel\""},{"type":"text","text":" ist auf unserem Server "},{"type":"text","text":"verboten"},{"type":"text","text":". Dies verstößt gegen die Prinzipien des fairen Gameplays und verzerrt das Spielerlebnis."}]},{"type":"paragraph","content":[{"type":"text","text":"§31."},{"type":"text","text":"2"},{"type":"text","text":"Das "},{"type":"text","text":"Verwenden des Scanners"},{"type":"text","text":" ist ebenfalls "},{"type":"text","text":"verboten"},{"type":"text","text":" und wird als "},{"type":"text","text":"Meta Gaming"},{"type":"text","text":" angesehen. Informationen, die auf diesem Weg erhalten werden, dürfen nicht in das Ingame-RP eingebracht werden, da dies das Spiel unfair macht."}]},{"type":"paragraph","content":[{"type":"text","text":"§31."},{"type":"text","text":"3"},{"type":"text","text":"Das "},{"type":"text","text":"Nutzen des Polizeihelikopters"},{"type":"text","text":" ist "},{"type":"text","text":"verboten"},{"type":"text","text":" und fällt unter "},{"type":"text","text":"Meta Gaming"},{"type":"text","text":". Das Fliegen und die Nutzung des Helikopters für die Erfassung von Informationen oder Überwachung von Spielern sind nicht gestattet, da sie ebenfalls den Verlauf des Spiels manipulieren können."}]},{"type":"paragraph","content":[{"type":"text","text":"§31."},{"type":"text","text":"4"},{"type":"text","text":"Das "},{"type":"text","text":"Nutzen der \"Spray Can\""},{"type":"text","text":" (Sprühdose) ist "},{"type":"text","text":"erlaubt"},{"type":"text","text":", jedoch sollte man dabei stets das "},{"type":"text","text":"Ausmaß"},{"type":"text","text":" im Blick behalten. Übermäßiger oder unnötiger Einsatz dieser Dosen, der das RP stört oder unrealistisch wirkt, sollte vermieden werden."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§31.0 Gamepässe und Werkzeuge Verbotene und erlaubte Gamepass-Nutzung und Tools § 31 .1 Das Nutzen des Gamepasses "Instant Refuel" ist auf unserem Server verboten . Dies verstößt gegen die Prinzipien des fairen Gameplays und verzerrt das Spielerlebnis. §31. 2 Das Verwenden des Scanners ist ebenfalls verboten und wird als Meta Gaming angesehen. Informationen, die auf diesem Weg erhalten werden, dürfen nicht in das Ingame-RP eingebracht werden, da dies das Spiel unfair macht. §31. 3 Das Nutzen des Polizeihelikopters ist verboten und fällt unter Meta Gaming . Das Fliegen und die Nutzung des Helikopters für die Erfassung von Informationen oder Überwachung von Spielern sind nicht gestattet, da sie ebenfalls den Verlauf des Spiels manipulieren können. §31. 4 Das Nutzen der "Spray Can" (Sprühdose) ist erlaubt , jedoch sollte man dabei stets das Ausmaß im Blick behalten. Übermäßiger oder unnötiger Einsatz dieser Dosen, der das RP stört oder unrealistisch wirkt, sollte vermieden werden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

