    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Crash Roleplay (CRP) – Unfall und Folgen"}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"2"},{"type":"text","text":".1 "},{"type":"text","text":"Das "},{"type":"text","text":"Crash Roleplay"},{"type":"text","text":" muss immer nach einem Unfall "},{"type":"text","text":"ausgespielt"},{"type":"text","text":" werden, der eine Geschwindigkeit von "},{"type":"text","text":"mindestens "},{"type":"text","text":"40"},{"type":"text","text":"km/"},{"type":"text","text":"h"},{"type":"text","text":" überschreitet. Dies stellt sicher, dass jeder Unfall realistisch und im Einklang mit den RP-Regeln behandelt wird."}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"2"},{"type":"text","text":"."},{"type":"text","text":"2 "},{"type":"text","text":"Bei "},{"type":"text","text":"sehr hohen Geschwindigkeiten"},{"type":"text","text":" von "},{"type":"text","text":"100"},{"type":"text","text":"km/"},{"type":"text","text":"h oder mehr"},{"type":"text","text":" muss zwingend ein "},{"type":"text","text":"Notruf"},{"type":"text","text":" getätigt werden, um den Vorfall korrekt zu melden und die nötigen Rettungsmaßnahmen einzuleiten."}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"2"},{"type":"text","text":"."},{"type":"text","text":"3 "},{"type":"text","text":"Nach einem Unfall ist es erforderlich, dass der Spieler "},{"type":"text","text":"zuerst auf sich selbst"},{"type":"text","text":" sowie auf das "},{"type":"text","text":"beschädigte Fahrzeug"},{"type":"text","text":" achtet. Das sofortige "},{"type":"text","text":"Weiterfahren"},{"type":"text","text":" nach einem Unfall ohne eine realistische Reaktion auf den Schaden ist nicht gestattet und verstößt gegen das Prinzip des realistischen Rollenspiels."}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"2"},{"type":"text","text":"."},{"type":"text","text":"4"},{"type":"text","text":"Sollte das Fahrzeug "},{"type":"text","text":"schwer beschädigt"},{"type":"text","text":" sein, so muss ebenfalls umgehend ein "},{"type":"text","text":"Notruf"},{"type":"text","text":" getätigt werden. Bei größeren Schäden ist es entscheidend, die nötigen Rettungsdienste zu alarmieren, um das Spielgeschehen aufrechtzuerhalten und die Sicherheit aller Beteiligten zu gewährleisten."}]},{"type":"paragraph","content":[{"type":"text","text":"§32.5 "},{"type":"text","text":"Der Swat Truck von der POL muss das Crash-RP erst ab einer Geschwindigkeit von ca 80 km/h ausspielen."}]},{"type":"paragraph","content":[{"type":"text","text":"§32.6"},{"type":"text","text":" Das Crash RP entfällt bei Objekten die umgefahren werden können (Zaun, Laternen, Schilder etc.)"},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§32.0 Crash Roleplay' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
