verstoßen. Spieler, die gesperrte Liverys oder Uniformen verwenden, müssen mit sofortigen Maßnahmen rechnen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§33.0 Livery´s / Uniformen' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
