      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§33.0 Livery´s / Uniformen', "order" = 33, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-33-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Verwendung von Liverys und Uniformen"}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"3"},{"type":"text","text":".1 "},{"type":"text","text":"Es ist ausschließlich erlaubt, die "},{"type":"text","text":"Liverys"},{"type":"text","text":" und "},{"type":"text","text":"Uniformen"},{"type":"text","text":" zu verwenden, die "},{"type":"text","text":"vom Server bereitgestellt"},{"type":"text","text":" werden. Diese wurden speziell für den Server erstellt und müssen zu allen Zeiten genutzt werden, um Konsistenz und ein authentisches Spielerlebnis zu gewährleisten."}]},{"type":"paragraph","content":[{"type":"text","text":"§33.2 "},{"type":"text","text":"Liverys und Uniformen mit dem Zusatz "},{"type":"text","text":"„DC Only“"},{"type":"text","text":" im Namen dürfen nur von Spielern genutzt werden, die "},{"type":"text","text":"im entsprechenden Discord-Server"},{"type":"text","text":" (DC) Mitglied sind. Diese speziellen Designs sind für bestimmte Gruppen und müssen daher nur von den berechtigten Nutzern verwendet werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§33.3 "},{"type":"text","text":"Uniformen müssen stets "},{"type":"text","text":"klar erkennbar"},{"type":"text","text":" und sichtbar sein. Es darf nichts die Uniform verdecken, um Missverständnissen vorzubeugen. Dies gewährleistet, dass jeder Spieler im RP die Rolle und Funktion des jeweiligen Charakters eindeutig erkennt."}]},{"type":"paragraph","content":[{"type":"text","text":"§33.4 "},{"type":"text","text":"Liverys und Uniformen, die "},{"type":"text","text":"„gesperrt“"},{"type":"text","text":" sind, dürfen "},{"type":"text","text":"nicht"},{"type":"text","text":" verwendet werden. Die Verwendung solcher Designs kann "},{"type":"text","text":"schwere Konsequenzen"},{"type":"text","text":" nach sich ziehen, da sie gegen die Server-Regeln verstoßen. Spieler, die gesperrte Liverys oder Uniformen verwenden, müssen mit sofortigen Maßnahmen rechnen."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§33.0 Livery´s / Uniformen Verwendung von Liverys und Uniformen §3 3 .1 Es ist ausschließlich erlaubt, die Liverys und Uniformen zu verwenden, die vom Server bereitgestellt werden. Diese wurden speziell für den Server erstellt und müssen zu allen Zeiten genutzt werden, um Konsistenz und ein authentisches Spielerlebnis zu gewährleisten. §33.2 Liverys und Uniformen mit dem Zusatz „DC Only“ im Namen dürfen nur von Spielern genutzt werden, die im entsprechenden Discord-Server (DC) Mitglied sind. Diese speziellen Designs sind für bestimmte Gruppen und müssen daher nur von den berechtigten Nutzern verwendet werden. §33.3 Uniformen müssen stets klar erkennbar und sichtbar sein. Es darf nichts die Uniform verdecken, um Missverständnissen vorzubeugen. Dies gewährleistet, dass jeder Spieler im RP die Rolle und Funktion des jeweiligen Charakters eindeutig erkennt. §33.4 Liverys und Uniformen, die „gesperrt“ sind, dürfen nicht verwendet werden. Die Verwendung solcher Designs kann schwere Konsequenzen nach sich ziehen, da sie gegen die Server-Regeln verstoßen. Spieler, die gesperrte Liverys oder Uniformen verwenden, müssen mit sofortigen Maßnahmen rechnen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-34';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-34', 'main-34', 'main-34', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§34.0 Polizei', 34, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§34.1 "},{"type":"text","text":"Festnahmen und Uniformen"},{"type":"hardBreak"},{"type":"text","text":" Als Polizist muss immer ein Grund für eine Festnahme vorhanden sein. Man darf nur die Uniformen tragen, die für den eigenen Rang zugelassen sind. Das Nutzen von Langwaffen im Inventar ist ausschließlich für Spezialeinheiten erlaubt. Streifenpolizisten dürfen Langwaffen nur im Kofferraum führen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.2 "},{"type":"text","text":"Verhalten und Missbrauch"},{"type":"hardBreak"},{"type":"text","text":" Das Missbrauchen der Handschellen ist verboten, ebenso wie das sogenannte „Cuff Rush“. Bei einer Geiselnahme hat immer der höhergestellte Polizist das Sagen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.3 "},{"type":"text","text":"Disziplin und Verantwortung"},{"type":"hardBreak"},{"type":"text","text":" Der Höherdienst ist berechtigt, Suspendierungen von bis zu einem Monat auszusprechen. Das Ausgeben als eine höhergestellte Person ist untersagt. Als Polizist muss das eigene Leben immer an erster Stelle stehen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.4 "},{"type":"text","text":"Zusammenarbeit und Absperrung"},{"type":"hardBreak"},{"type":"text","text":" Polizisten dürfen keine Unterstützung für Gang- oder Mafia-Mitglieder leisten. Bei Absperrungen muss darauf geachtet werden, dass immer noch Autos vorbeifahren können. Ein vollständiges Sperren von Straßen ist verboten. Spezialeinheiten sind nicht berechtigt, Verkehrskontrollen durchzuführen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.5 "},{"type":"text","text":"Festnahmeprozedere"},{"type":"hardBreak"},{"type":"text","text":" Nach der Festnahme einer Person hat der Polizist fünf Sekunden Zeit, „cuff“ zu schreiben."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§34.0 Polizei' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§34.0 Polizei', "order" = 34, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-34-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§34.1 "},{"type":"text","text":"Festnahmen und Uniformen"},{"type":"hardBreak"},{"type":"text","text":" Als Polizist muss immer ein Grund für eine Festnahme vorhanden sein. Man darf nur die Uniformen tragen, die für den eigenen Rang zugelassen sind. Das Nutzen von Langwaffen im Inventar ist ausschließlich für Spezialeinheiten erlaubt. Streifenpolizisten dürfen Langwaffen nur im Kofferraum führen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.2 "},{"type":"text","text":"Verhalten und Missbrauch"},{"type":"hardBreak"},{"type":"text","text":" Das Missbrauchen der Handschellen ist verboten, ebenso wie das sogenannte „Cuff Rush“. Bei einer Geiselnahme hat immer der höhergestellte Polizist das Sagen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.3 "},{"type":"text","text":"Disziplin und Verantwortung"},{"type":"hardBreak"},{"type":"text","text":" Der Höherdienst ist berechtigt, Suspendierungen von bis zu einem Monat auszusprechen. Das Ausgeben als eine höhergestellte Person ist untersagt. Als Polizist muss das eigene Leben immer an erster Stelle stehen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.4 "},{"type":"text","text":"Zusammenarbeit und Absperrung"},{"type":"hardBreak"},{"type":"text","text":" Polizisten dürfen keine Unterstützung für Gang- oder Mafia-Mitglieder leisten. Bei Absperrungen muss darauf geachtet werden, dass immer noch Autos vorbeifahren können. Ein vollständiges Sperren von Straßen ist verboten. Spezialeinheiten sind nicht berechtigt, Verkehrskontrollen durchzuführen."}]},{"type":"paragraph","content":[{"type":"text","text":"§34.5 "},{"type":"text","text":"Festnahmeprozedere"},{"type":"hardBreak"},{"type":"text","text":" Nach der Festnahme einer Person hat der Polizist fünf Sekunden Zeit, „cuff“ zu schreiben."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§34.0 Polizei §34.1 Festnahmen und Uniformen Als Polizist muss immer ein Grund für eine Festnahme vorhanden sein. Man darf nur die Uniformen tragen, die für den eigenen Rang zugelassen sind. Das Nutzen von Langwaffen im Inventar ist ausschließlich für Spezialeinheiten erlaubt. Streifenpolizisten dürfen Langwaffen nur im Kofferraum führen. §34.2 Verhalten und Missbrauch Das Missbrauchen der Handschellen ist verboten, ebenso wie das sogenannte „Cuff Rush“. Bei einer Geiselnahme hat immer der höhergestellte Polizist das Sagen. §34.3 Disziplin und Verantwortung Der Höherdienst ist berechtigt, Suspendierungen von bis zu einem Monat auszusprechen. Das Ausgeben als eine höhergestellte Person ist untersagt. Als Polizist muss das eigene Leben immer an erster Stelle stehen. §34.4 Zusammenarbeit und Absperrung Polizisten dürfen keine Unterstützung für Gang- oder Mafia-Mitglieder leisten. Bei Absperrungen muss darauf geachtet werden, dass immer noch Autos vorbeifahren können. Ein vollständiges Sperren von Straßen ist verboten. Spezialeinheiten sind nicht berechtigt, Verkehrskontrollen durchzuführen. §34.5 Festnahmeprozedere Nach der Festnahme einer Person hat der Polizist fünf Sekunden Zeit, „cuff“ zu schreiben.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-35';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-35', 'main-35', 'main-35', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§35.0 Rettungsdienst', 35, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"5.1 "},{"type":"text","text":"Medic RP und Verantwortung"},{"type":"hardBreak"},{"type":"text","text":" Der Rettungsdienst muss immer das Medic RP ausspielen und sich an die Regeln des Roleplays halten. Der Rettungsdienst ist nicht berechtigt, andere Dinge zu löschen oder zu verändern, außer bei Fahrzeugbränden, bei denen ein Feuerlöscher (CO2) eingesetzt werden darf."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.2 "},{"type":"text","text":"Rollenanforderungen"},{"type":"hardBreak"},{"type":"text","text":" Das Spielen als Notarzt, Leitender Notarzt (LNA), Desinfektor oder Organisatorische Leitung (OrgL) ist nur erlaubt, wenn der Spieler die entsprechende Rolle im Discord besitzt."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.3 "},{"type":"text","text":"Verbotene Aktivitäten"},{"type":"hardBreak"},{"type":"text","text":" Das Aufbauen von Impfstationen ist verboten. Der Rettungsdienst ist nicht befugt, große Brände zu löschen. Eine Ausnahme besteht nur bei Fahrzeugbränden, bei denen der CO2-Feuerlöscher verwendet werden darf."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.4 "},{"type":"text","text":"Neutralität und Schweigepflicht"},{"type":"hardBreak"},{"type":"text","text":" Der Rettungsdienst ist verpflichtet, stets neutral zu bleiben und die ärztliche Schweigepflicht zu wahren."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.5 "},{"type":"text","text":"Beinflussung des Rettungsdienstes"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Einflussnahme auf den Rettungsdienst ist untersagt. Anweisungen oder Forderungen wie „Versorge nur meine Leute“ oder das bewusste Zurücklassen anderer verletzter Personen sind im Roleplay nicht gestattet. Der Rettungsdienst ist verpflichtet, alle Personen unabhängig von Fraktion, Zugehörigkeit oder Rolle gleich zu behandeln."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§35.0 Rettungsdienst' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§35.0 Rettungsdienst', "order" = 35, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-35-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"5.1 "},{"type":"text","text":"Medic RP und Verantwortung"},{"type":"hardBreak"},{"type":"text","text":" Der Rettungsdienst muss immer das Medic RP ausspielen und sich an die Regeln des Roleplays halten. Der Rettungsdienst ist nicht berechtigt, andere Dinge zu löschen oder zu verändern, außer bei Fahrzeugbränden, bei denen ein Feuerlöscher (CO2) eingesetzt werden darf."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.2 "},{"type":"text","text":"Rollenanforderungen"},{"type":"hardBreak"},{"type":"text","text":" Das Spielen als Notarzt, Leitender Notarzt (LNA), Desinfektor oder Organisatorische Leitung (OrgL) ist nur erlaubt, wenn der Spieler die entsprechende Rolle im Discord besitzt."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.3 "},{"type":"text","text":"Verbotene Aktivitäten"},{"type":"hardBreak"},{"type":"text","text":" Das Aufbauen von Impfstationen ist verboten. Der Rettungsdienst ist nicht befugt, große Brände zu löschen. Eine Ausnahme besteht nur bei Fahrzeugbränden, bei denen der CO2-Feuerlöscher verwendet werden darf."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.4 "},{"type":"text","text":"Neutralität und Schweigepflicht"},{"type":"hardBreak"},{"type":"text","text":" Der Rettungsdienst ist verpflichtet, stets neutral zu bleiben und die ärztliche Schweigepflicht zu wahren."}]},{"type":"paragraph","content":[{"type":"text","text":"§35.5 "},{"type":"text","text":"Beinflussung des Rettungsdienstes"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Einflussnahme auf den Rettungsdienst ist untersagt. Anweisungen oder Forderungen wie „Versorge nur meine Leute“ oder das bewusste Zurücklassen anderer verletzter Personen sind im Roleplay nicht gestattet. Der Rettungsdienst ist verpflichtet, alle Personen unabhängig von Fraktion, Zugehörigkeit oder Rolle gleich zu behandeln."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§35.0 Rettungsdienst §3 5.1 Medic RP und Verantwortung Der Rettungsdienst muss immer das Medic RP ausspielen und sich an die Regeln des Roleplays halten. Der Rettungsdienst ist nicht berechtigt, andere Dinge zu löschen oder zu verändern, außer bei Fahrzeugbränden, bei denen ein Feuerlöscher (CO2) eingesetzt werden darf. §35.2 Rollenanforderungen Das Spielen als Notarzt, Leitender Notarzt (LNA), Desinfektor oder Organisatorische Leitung (OrgL) ist nur erlaubt, wenn der Spieler die entsprechende Rolle im Discord besitzt. §35.3 Verbotene Aktivitäten Das Aufbauen von Impfstationen ist verboten. Der Rettungsdienst ist nicht befugt, große Brände zu löschen. Eine Ausnahme besteht nur bei Fahrzeugbränden, bei denen der CO2-Feuerlöscher verwendet werden darf. §35.4 Neutralität und Schweigepflicht Der Rettungsdienst ist verpflichtet, stets neutral zu bleiben und die ärztliche Schweigepflicht zu wahren. §35.5 Beinflussung des Rettungsdienstes Jegliche Einflussnahme auf den Rettungsdienst ist untersagt. Anweisungen oder Forderungen wie „Versorge nur meine Leute“ oder das bewusste Zurücklassen anderer verletzter Personen sind im Roleplay nicht gestattet. Der Rettungsdienst ist verpflichtet, alle Personen unabhängig von Fraktion, Zugehörigkeit oder Rolle gleich zu behandeln.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-36';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-36', 'main-36', 'main-36', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§36.0 Feuerwehr', 36, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Feuerwehr-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"6.1 "},{"type":"text","text":"Die Feuerwehr ist nicht befugt, Personen ins Krankenhaus zu fahren. Dies liegt in der Verantwortung des Rettungsdienstes, der die notwendige medizinische Versorgung leisten muss. Ebenso ist es der Feuerwehr untersagt, das Gerät „Monitor/EKG“ zu verwenden, da dieses ausschließlich dem Rettungsdienst vorbehalten ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§36.2 "},{"type":"text","text":"Das Missbrauchen der Drehleiter (DLK) ist ebenfalls verboten. Die DLK darf nur für feuerwehrtechnische Einsätze genutzt werden, bei denen sie tatsächlich erforderlich ist. Zudem ist die Nutzung der „Simpel Fire Hose“ untersagt. Diese darf garnicht verwendet werden, um das Gameplay fair zu halten."}]},{"type":"paragraph","content":[{"type":"text","text":"§36.3 "},{"type":"text","text":"Das Zweckentfremden oder wahllose Platzieren von Wasserbecken auf Straßen, an Plätzen oder in Gebäuden ist untersagt. Der Einsatz ist nur der Feuerwehr (FD) im Rahmen von aktiven Löscheinsätzen gestattet."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§36.0 Feuerwehr' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§36.0 Feuerwehr', "order" = 36, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-36-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Feuerwehr-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"6.1 "},{"type":"text","text":"Die Feuerwehr ist nicht befugt, Personen ins Krankenhaus zu fahren. Dies liegt in der Verantwortung des Rettungsdienstes, der die notwendige medizinische Versorgung leisten muss. Ebenso ist es der Feuerwehr untersagt, das Gerät „Monitor/EKG“ zu verwenden, da dieses ausschließlich dem Rettungsdienst vorbehalten ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§36.2 "},{"type":"text","text":"Das Missbrauchen der Drehleiter (DLK) ist ebenfalls verboten. Die DLK darf nur für feuerwehrtechnische Einsätze genutzt werden, bei denen sie tatsächlich erforderlich ist. Zudem ist die Nutzung der „Simpel Fire Hose“ untersagt. Diese darf garnicht verwendet werden, um das Gameplay fair zu halten."}]},{"type":"paragraph","content":[{"type":"text","text":"§36.3 "},{"type":"text","text":"Das Zweckentfremden oder wahllose Platzieren von Wasserbecken auf Straßen, an Plätzen oder in Gebäuden ist untersagt. Der Einsatz ist nur der Feuerwehr (FD) im Rahmen von aktiven Löscheinsätzen gestattet."}]}]}'::jsonb, '§36.0 Feuerwehr Feuerwehr-Richtlinien §3 6.1 Die Feuerwehr ist nicht befugt, Personen ins Krankenhaus zu fahren. Dies liegt in der Verantwortung des Rettungsdienstes, der die notwendige medizinische Versorgung leisten muss. Ebenso ist es der Feuerwehr untersagt, das Gerät „Monitor/EKG“ zu verwenden, da dieses ausschließlich dem Rettungsdienst vorbehalten ist. §36.2 Das Missbrauchen der Drehleiter (DLK) ist ebenfalls verboten. Die DLK darf nur für feuerwehrtechnische Einsätze genutzt werden, bei denen sie tatsächlich erforderlich ist. Zudem ist die Nutzung der „Simpel Fire Hose“ untersagt. Diese darf garnicht verwendet werden, um das Gameplay fair zu halten. §36.3 Das Zweckentfremden oder wahllose Platzieren von Wasserbecken auf Straßen, an Plätzen oder in Gebäuden ist untersagt. Der Einsatz ist nur der Feuerwehr (FD) im Rahmen von aktiven Löscheinsätzen gestattet.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

