  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ADAC-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"7.1 "},{"type":"text","text":"D"},{"type":"text","text":"as Move Berlin"},{"type":"text","text":" ist berechtigt, Fahrzeuge abzuschleppen, jedoch nur mit einem entsprechenden RP-Hintergrund. Das Abschleppen darf nur in Situationen erfolgen, in denen Fahrzeuge die Straße blockieren, falsch parken oder ähnliche Probleme verursachen."}]},{"type":"paragraph","content":[{"type":"text","text":"§37.2 "},{"type":"text","text":"Wichtig ist, dass d"},{"type":"text","text":"as Move Berlin "},{"type":"text","text":"kein Einsatzfahrzeug ist. Das bedeutet, dass die "},{"type":"text","text":"Move Berlin"},{"type":"text","text":"-Fahrzeuge nicht über rote Ampeln fahren oder sich mit überhöhter Geschwindigkeit fortbewegen dürfen."}]},{"type":"paragraph","content":[{"type":"text","text":"§37.3 "},{"type":"text","text":"Mehrfaches, grundloses Abschleppen von Fahrzeugen kann als Trolling betrachtet werden und zu entsprechenden Konsequenzen führen. Jeder Abschleppvorgang muss einen klaren RP-Hintergrund und einen realistischen Grund haben."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§37.0 Move-Berlin' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
