      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§37.0 Move-Berlin', "order" = 37, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-37-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ADAC-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§3"},{"type":"text","text":"7.1 "},{"type":"text","text":"D"},{"type":"text","text":"as Move Berlin"},{"type":"text","text":" ist berechtigt, Fahrzeuge abzuschleppen, jedoch nur mit einem entsprechenden RP-Hintergrund. Das Abschleppen darf nur in Situationen erfolgen, in denen Fahrzeuge die Straße blockieren, falsch parken oder ähnliche Probleme verursachen."}]},{"type":"paragraph","content":[{"type":"text","text":"§37.2 "},{"type":"text","text":"Wichtig ist, dass d"},{"type":"text","text":"as Move Berlin "},{"type":"text","text":"kein Einsatzfahrzeug ist. Das bedeutet, dass die "},{"type":"text","text":"Move Berlin"},{"type":"text","text":"-Fahrzeuge nicht über rote Ampeln fahren oder sich mit überhöhter Geschwindigkeit fortbewegen dürfen."}]},{"type":"paragraph","content":[{"type":"text","text":"§37.3 "},{"type":"text","text":"Mehrfaches, grundloses Abschleppen von Fahrzeugen kann als Trolling betrachtet werden und zu entsprechenden Konsequenzen führen. Jeder Abschleppvorgang muss einen klaren RP-Hintergrund und einen realistischen Grund haben."}]}]}'::jsonb, '§37.0 Move-Berlin ADAC-Richtlinien §3 7.1 D as Move Berlin ist berechtigt, Fahrzeuge abzuschleppen, jedoch nur mit einem entsprechenden RP-Hintergrund. Das Abschleppen darf nur in Situationen erfolgen, in denen Fahrzeuge die Straße blockieren, falsch parken oder ähnliche Probleme verursachen. §37.2 Wichtig ist, dass d as Move Berlin kein Einsatzfahrzeug ist. Das bedeutet, dass die Move Berlin -Fahrzeuge nicht über rote Ampeln fahren oder sich mit überhöhter Geschwindigkeit fortbewegen dürfen. §37.3 Mehrfaches, grundloses Abschleppen von Fahrzeugen kann als Trolling betrachtet werden und zu entsprechenden Konsequenzen führen. Jeder Abschleppvorgang muss einen klaren RP-Hintergrund und einen realistischen Grund haben.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-38';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-38', 'main-38', 'main-38', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§38.0 Gang´s', 38, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gang-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§38.1"},{"type":"text","text":"Eine inoffizielle Gang darf nur aus maximal "},{"type":"text","text":"3"},{"type":"text","text":" Mitgliedern bestehen. Möchte man mit mehr Mitgliedern in einer Gang RP betreiben, muss eine offizielle Gang gegründet werden. Offizielle Gangs haben bestimmte Rechte und Pflichten innerhalb des Servers."}]},{"type":"paragraph","content":[{"type":"text","text":"§38.2 "},{"type":"text","text":"Innerhalb des Ganggebiets gilt immer ein Schusscall, der den Gangmitgliedern erlaubt, in ihrem Gebiet zu agieren. Dabei müssen sie jedoch das \"Gambo RP\" beachten, um unrealistische oder unangemessene Situationen zu vermeiden."}]},{"type":"paragraph","content":[{"type":"text","text":"§38.3"},{"type":"text","text":"Die New Life Rule (NLR) entfällt für Gangmitglieder in ihrem eigenen Ganggebiet. Das bedeutet, wenn ein Gangmitglied in seinem Ganggebiet stirbt, darf es dorthin zurückkehren, da es als „Zuhause“ der Gang betrachtet wird. Jedoch ist es weiterhin wichtig, das RP realistisch zu gestalten und die anderen Regeln zu respektieren."}]},{"type":"paragraph","content":[{"type":"text","text":"§38."},{"type":"text","text":"4"},{"type":"text","text":"Weiteres und genaueres kann man"},{"type":"text","text":" unter"},{"type":"text","text":" \""},{"type":"text","text":"Fraktions Regelwerk","marks":[{"type":"link","attrs":{"href":"","target":"_blank","rel":"noopener noreferrer nofollow","class":null}}]},{"type":"text","text":"\" "},{"type":"text","text":"Nachlesen"}]},{"type":"paragraph","content":[{"type":"text","text":"§38.5"},{"type":"text","text":"Gangs sind verpflichtet, sich im Roleplay eindeutig kenntlich zu machen."},{"type":"hardBreak"},{"type":"text","text":" Dies erfolgt durch die Verwendung ihrer zugewiesenen Farben, Erkennungsmerkmale sowie ggf. weiterer charakteristischer Kennzeichen.Die Zugehörigkeit zu einer Gang muss für andere Spieler im RP nachvollziehbar und erkennbar sein, um ein realistisches und strukturiertes Spielgeschehen zu gewährleisten."}]},{"type":"paragraph","content":[{"type":"text","text":"§38.6 "},{"type":"text","text":"Es ist strengstens verboten, Polizeibeamte mutwillig oder durch Vortäuschung falscher Tatsachen in ein Gang-Gebiet zu locken (sog. Cop-Baiting). Zuwiderhandlungen werden als Regelverstoß gewertet."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§38.0 Gang´s' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§38.0 Gang´s', "order" = 38, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-38-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gang-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§38.1"},{"type":"text","text":"Eine inoffizielle Gang darf nur aus maximal "},{"type":"text","text":"3"},{"type":"text","text":" Mitgliedern bestehen. Möchte man mit mehr Mitgliedern in einer Gang RP betreiben, muss eine offizielle Gang gegründet werden. Offizielle Gangs haben bestimmte Rechte und Pflichten innerhalb des Servers."}]},{"type":"paragraph","content":[{"type":"text","text":"§38.2 "},{"type":"text","text":"Innerhalb des Ganggebiets gilt immer ein Schusscall, der den Gangmitgliedern erlaubt, in ihrem Gebiet zu agieren. Dabei müssen sie jedoch das \"Gambo RP\" beachten, um unrealistische oder unangemessene Situationen zu vermeiden."}]},{"type":"paragraph","content":[{"type":"text","text":"§38.3"},{"type":"text","text":"Die New Life Rule (NLR) entfällt für Gangmitglieder in ihrem eigenen Ganggebiet. Das bedeutet, wenn ein Gangmitglied in seinem Ganggebiet stirbt, darf es dorthin zurückkehren, da es als „Zuhause“ der Gang betrachtet wird. Jedoch ist es weiterhin wichtig, das RP realistisch zu gestalten und die anderen Regeln zu respektieren."}]},{"type":"paragraph","content":[{"type":"text","text":"§38."},{"type":"text","text":"4"},{"type":"text","text":"Weiteres und genaueres kann man"},{"type":"text","text":" unter"},{"type":"text","text":" \""},{"type":"text","text":"Fraktions Regelwerk","marks":[{"type":"link","attrs":{"href":"","target":"_blank","rel":"noopener noreferrer nofollow","class":null}}]},{"type":"text","text":"\" "},{"type":"text","text":"Nachlesen"}]},{"type":"paragraph","content":[{"type":"text","text":"§38.5"},{"type":"text","text":"Gangs sind verpflichtet, sich im Roleplay eindeutig kenntlich zu machen."},{"type":"hardBreak"},{"type":"text","text":" Dies erfolgt durch die Verwendung ihrer zugewiesenen Farben, Erkennungsmerkmale sowie ggf. weiterer charakteristischer Kennzeichen.Die Zugehörigkeit zu einer Gang muss für andere Spieler im RP nachvollziehbar und erkennbar sein, um ein realistisches und strukturiertes Spielgeschehen zu gewährleisten."}]},{"type":"paragraph","content":[{"type":"text","text":"§38.6 "},{"type":"text","text":"Es ist strengstens verboten, Polizeibeamte mutwillig oder durch Vortäuschung falscher Tatsachen in ein Gang-Gebiet zu locken (sog. Cop-Baiting). Zuwiderhandlungen werden als Regelverstoß gewertet."}]}]}'::jsonb, '§38.0 Gang´s Gang-Richtlinien §38.1 Eine inoffizielle Gang darf nur aus maximal 3 Mitgliedern bestehen. Möchte man mit mehr Mitgliedern in einer Gang RP betreiben, muss eine offizielle Gang gegründet werden. Offizielle Gangs haben bestimmte Rechte und Pflichten innerhalb des Servers. §38.2 Innerhalb des Ganggebiets gilt immer ein Schusscall, der den Gangmitgliedern erlaubt, in ihrem Gebiet zu agieren. Dabei müssen sie jedoch das "Gambo RP" beachten, um unrealistische oder unangemessene Situationen zu vermeiden. §38.3 Die New Life Rule (NLR) entfällt für Gangmitglieder in ihrem eigenen Ganggebiet. Das bedeutet, wenn ein Gangmitglied in seinem Ganggebiet stirbt, darf es dorthin zurückkehren, da es als „Zuhause“ der Gang betrachtet wird. Jedoch ist es weiterhin wichtig, das RP realistisch zu gestalten und die anderen Regeln zu respektieren. §38. 4 Weiteres und genaueres kann man unter " Fraktions Regelwerk " Nachlesen §38.5 Gangs sind verpflichtet, sich im Roleplay eindeutig kenntlich zu machen. Dies erfolgt durch die Verwendung ihrer zugewiesenen Farben, Erkennungsmerkmale sowie ggf. weiterer charakteristischer Kennzeichen.Die Zugehörigkeit zu einer Gang muss für andere Spieler im RP nachvollziehbar und erkennbar sein, um ein realistisches und strukturiertes Spielgeschehen zu gewährleisten. §38.6 Es ist strengstens verboten, Polizeibeamte mutwillig oder durch Vortäuschung falscher Tatsachen in ein Gang-Gebiet zu locken (sog. Cop-Baiting). Zuwiderhandlungen werden als Regelverstoß gewertet.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-39';
