      ('rule-main-39', 'main-39', 'main-39', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§39.0 Imunitäten', 39, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grundsatz"}]},{"type":"paragraph","content":[{"type":"text","text":"Im Deutschland Roleplay gilt uneingeschränkt:"},{"type":"hardBreak"},{"type":"text","text":"Alle Spieler:innen unterliegen gleichermaßen den RP-Regeln und den geltenden Gesetzen."},{"type":"text","text":" Es existieren "},{"type":"text","text":"keine Immunitäten"},{"type":"text","text":" – unabhängig von Rang, Fraktion, Rolle oder Funktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Geltungsbereich"}]},{"type":"paragraph","content":[{"type":"text","text":"Dieses Verbot umfasst unter anderem:"}]},{"type":"paragraph","content":[{"type":"text","text":"Schutz vor Kontrollen, Festnahmen oder Durchsuchungen"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Unantastbarkeit im Straf- oder Ermittlungsverfahren"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Umgehung von Strafen oder RP-Folgen durch Dienstgrad oder Rang"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"\"God-Roleplay\" (Unverletzlichkeit, Übermenschlichkeit etc.)"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahmen"}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahmen sind "},{"type":"text","text":"nur im Vorfeld genehmigte RP-Events"},{"type":"text","text":", die vom "},{"type":"text","text":"Serverteam explizit angekündigt und freigegeben"},{"type":"text","text":" wurden. Eine selbstbestimmte Immunität ohne klare Genehmigung ist "},{"type":"text","text":"nicht erlaubt"},{"type":"text","text":"."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§39.0 Imunitäten' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§39.0 Imunitäten', "order" = 39, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-39-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grundsatz"}]},{"type":"paragraph","content":[{"type":"text","text":"Im Deutschland Roleplay gilt uneingeschränkt:"},{"type":"hardBreak"},{"type":"text","text":"Alle Spieler:innen unterliegen gleichermaßen den RP-Regeln und den geltenden Gesetzen."},{"type":"text","text":" Es existieren "},{"type":"text","text":"keine Immunitäten"},{"type":"text","text":" – unabhängig von Rang, Fraktion, Rolle oder Funktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Geltungsbereich"}]},{"type":"paragraph","content":[{"type":"text","text":"Dieses Verbot umfasst unter anderem:"}]},{"type":"paragraph","content":[{"type":"text","text":"Schutz vor Kontrollen, Festnahmen oder Durchsuchungen"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Unantastbarkeit im Straf- oder Ermittlungsverfahren"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Umgehung von Strafen oder RP-Folgen durch Dienstgrad oder Rang"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"\"God-Roleplay\" (Unverletzlichkeit, Übermenschlichkeit etc.)"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahmen"}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahmen sind "},{"type":"text","text":"nur im Vorfeld genehmigte RP-Events"},{"type":"text","text":", die vom "},{"type":"text","text":"Serverteam explizit angekündigt und freigegeben"},{"type":"text","text":" wurden. Eine selbstbestimmte Immunität ohne klare Genehmigung ist "},{"type":"text","text":"nicht erlaubt"},{"type":"text","text":"."}]}]}'::jsonb, '§39.0 Imunitäten Grundsatz Im Deutschland Roleplay gilt uneingeschränkt: Alle Spieler:innen unterliegen gleichermaßen den RP-Regeln und den geltenden Gesetzen. Es existieren keine Immunitäten – unabhängig von Rang, Fraktion, Rolle oder Funktion. Geltungsbereich Dieses Verbot umfasst unter anderem: Schutz vor Kontrollen, Festnahmen oder Durchsuchungen Unantastbarkeit im Straf- oder Ermittlungsverfahren Umgehung von Strafen oder RP-Folgen durch Dienstgrad oder Rang "God-Roleplay" (Unverletzlichkeit, Übermenschlichkeit etc.) Ausnahmen Ausnahmen sind nur im Vorfeld genehmigte RP-Events , die vom Serverteam explizit angekündigt und freigegeben wurden. Eine selbstbestimmte Immunität ohne klare Genehmigung ist nicht erlaubt .', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-40';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-40', 'main-40', 'main-40', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§40.0 Staff Team', 40, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Staff Team Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§"},{"type":"text","text":"40.1 "},{"type":"text","text":"Staff Team Mitglieder sind im Roleplay (RP) unsichtbar, was bedeutet, dass sie nicht aktiv in RP-Situationen eingebunden werden, es sei denn, sie handeln in ihrer offiziellen Funktion als Moderatoren."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.2 "},{"type":"text","text":"Das grundlose Rufen eines Staff Team Mitglieds wird bestraft, da es den normalen RP-Fluss stört und das Team nicht unnötig involviert werden soll. Sollte man ein Staff Team Auto rammen, muss kein Crash RP ausgespielt werden. Jedoch wird das absichtliche Rammen eines Staff Team Autos bestraft, da es als respektlos gegenüber den Regeln und den Teammitgliedern angesehen wird."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.3 "},{"type":"text","text":"Als Beweis für Regelverstöße reicht auch eine Aussage eines Moderators aus, solange das Teammitglied On Duty ist. Sollte zu dem Zeitpunkt kein Staff Mitglied ingame sein, kann der Spieler ein Ticket auf dem Discord-Server eröffnen, um das Problem zu schildern und eine Lösung zu finden."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.4"},{"type":"text","text":" D"},{"type":"text","text":"er Support-fall und der damit beinhaltetnde "},{"type":"text","text":"RP Stopp"},{"type":"text","text":" begint erst wenn das Staffmitglied vorort ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.5 "},{"type":"text","text":"Nach einer RP auflösung durch ein Staff-Mitglied dürfen die \"Selben\" Parteien für 5 minuten dort keine neue RP Szene beginnen."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.6 "},{"type":"text","text":"Wenn ein Staffmitglied einen Kick vergibt so muss man 20 Minuten warten bis man erneut dem Server beitreten kann, sollte man vorher beitreten folgen weiter Sanktionen."}]},{"type":"paragraph","content":[{"type":"text","text":"§"},{"type":"text","text":"40"},{"type":"text","text":"."},{"type":"text","text":"7"},{"type":"text","text":"Disskussionen aller art sind unerwünscht das Staff Team hat immer das letzte Wort."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§40.0 Staff Team' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§40.0 Staff Team', "order" = 40, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-40-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Staff Team Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"§"},{"type":"text","text":"40.1 "},{"type":"text","text":"Staff Team Mitglieder sind im Roleplay (RP) unsichtbar, was bedeutet, dass sie nicht aktiv in RP-Situationen eingebunden werden, es sei denn, sie handeln in ihrer offiziellen Funktion als Moderatoren."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.2 "},{"type":"text","text":"Das grundlose Rufen eines Staff Team Mitglieds wird bestraft, da es den normalen RP-Fluss stört und das Team nicht unnötig involviert werden soll. Sollte man ein Staff Team Auto rammen, muss kein Crash RP ausgespielt werden. Jedoch wird das absichtliche Rammen eines Staff Team Autos bestraft, da es als respektlos gegenüber den Regeln und den Teammitgliedern angesehen wird."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.3 "},{"type":"text","text":"Als Beweis für Regelverstöße reicht auch eine Aussage eines Moderators aus, solange das Teammitglied On Duty ist. Sollte zu dem Zeitpunkt kein Staff Mitglied ingame sein, kann der Spieler ein Ticket auf dem Discord-Server eröffnen, um das Problem zu schildern und eine Lösung zu finden."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.4"},{"type":"text","text":" D"},{"type":"text","text":"er Support-fall und der damit beinhaltetnde "},{"type":"text","text":"RP Stopp"},{"type":"text","text":" begint erst wenn das Staffmitglied vorort ist."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.5 "},{"type":"text","text":"Nach einer RP auflösung durch ein Staff-Mitglied dürfen die \"Selben\" Parteien für 5 minuten dort keine neue RP Szene beginnen."}]},{"type":"paragraph","content":[{"type":"text","text":"§40.6 "},{"type":"text","text":"Wenn ein Staffmitglied einen Kick vergibt so muss man 20 Minuten warten bis man erneut dem Server beitreten kann, sollte man vorher beitreten folgen weiter Sanktionen."}]},{"type":"paragraph","content":[{"type":"text","text":"§"},{"type":"text","text":"40"},{"type":"text","text":"."},{"type":"text","text":"7"},{"type":"text","text":"Disskussionen aller art sind unerwünscht das Staff Team hat immer das letzte Wort."}]}]}'::jsonb, '§40.0 Staff Team Staff Team Richtlinien § 40.1 Staff Team Mitglieder sind im Roleplay (RP) unsichtbar, was bedeutet, dass sie nicht aktiv in RP-Situationen eingebunden werden, es sei denn, sie handeln in ihrer offiziellen Funktion als Moderatoren. §40.2 Das grundlose Rufen eines Staff Team Mitglieds wird bestraft, da es den normalen RP-Fluss stört und das Team nicht unnötig involviert werden soll. Sollte man ein Staff Team Auto rammen, muss kein Crash RP ausgespielt werden. Jedoch wird das absichtliche Rammen eines Staff Team Autos bestraft, da es als respektlos gegenüber den Regeln und den Teammitgliedern angesehen wird. §40.3 Als Beweis für Regelverstöße reicht auch eine Aussage eines Moderators aus, solange das Teammitglied On Duty ist. Sollte zu dem Zeitpunkt kein Staff Mitglied ingame sein, kann der Spieler ein Ticket auf dem Discord-Server eröffnen, um das Problem zu schildern und eine Lösung zu finden. §40.4 D er Support-fall und der damit beinhaltetnde RP Stopp begint erst wenn das Staffmitglied vorort ist. §40.5 Nach einer RP auflösung durch ein Staff-Mitglied dürfen die "Selben" Parteien für 5 minuten dort keine neue RP Szene beginnen. §40.6 Wenn ein Staffmitglied einen Kick vergibt so muss man 20 Minuten warten bis man erneut dem Server beitreten kann, sollte man vorher beitreten folgen weiter Sanktionen. § 40 . 7 Disskussionen aller art sind unerwünscht das Staff Team hat immer das letzte Wort.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
