      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§41.0 Spezial Events', "order" = 41, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-41-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§41.1 "},{"type":"text","text":"Winter Event"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Befahren von Eisflächen mit Fahrzeugen ist "},{"type":"text","text":"untersagt"},{"type":"text","text":", da es dem "},{"type":"text","text":"realistischen Rollenspiel (RP)"},{"type":"text","text":" widerspricht und als "},{"type":"text","text":"unzulässiges FRP"},{"type":"text","text":" bestraft wird."}]},{"type":"paragraph","content":[{"type":"text","text":"§41.2 "},{"type":"text","text":"Halloween / Murder Mysterie"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Einnahme von Tränken (Potions)"},{"type":"text","text":" oder ähnlichen magischen/fantastischen Konsumgütern ist "},{"type":"text","text":"untersagt"},{"type":"text","text":". Solche Gegenstände verstoßen gegen die "},{"type":"text","text":"Realismus-Anforderung des Rollenspiels (FRP)"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"§41.3 "},{"type":"text","text":"Razzia"}]},{"type":"paragraph","content":[{"type":"text","text":"Im Falle einer "},{"type":"text","text":"Razzia"},{"type":"text","text":" innerhalb des Gang-Gebiets wird die "},{"type":"text","text":"New Life Rule (NLR)"},{"type":"text","text":" für die beteiligten Gang-Mitglieder "},{"type":"text","text":"nicht angewandt"},{"type":"text","text":". Stirbt ein Gang-Mitglied während der Razzia, ist ihm die "},{"type":"text","text":"Rückkehr in das umkämpfte Gebiet"},{"type":"text","text":" für die Dauer des Events "},{"type":"text","text":"strikt untersagt."}]}]}'::jsonb, '§41.0 Spezial Events §41.1 Winter Event Das Befahren von Eisflächen mit Fahrzeugen ist untersagt , da es dem realistischen Rollenspiel (RP) widerspricht und als unzulässiges FRP bestraft wird. §41.2 Halloween / Murder Mysterie Die Einnahme von Tränken (Potions) oder ähnlichen magischen/fantastischen Konsumgütern ist untersagt . Solche Gegenstände verstoßen gegen die Realismus-Anforderung des Rollenspiels (FRP) . §41.3 Razzia Im Falle einer Razzia innerhalb des Gang-Gebiets wird die New Life Rule (NLR) für die beteiligten Gang-Mitglieder nicht angewandt . Stirbt ein Gang-Mitglied während der Razzia, ist ihm die Rückkehr in das umkämpfte Gebiet für die Dauer des Events strikt untersagt.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-42';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-42', 'main-42', 'main-42', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§42.0 Neutralität', 42, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§42.1 Neutralität im Roleplay"}]},{"type":"paragraph","content":[{"type":"text","text":"Innerhalb des gesamten Roleplays auf dem Server ist ein neutraler Umgang mit religiösen Themen verpflichtend. Religion darf weder aktiv dargestellt, noch als Teil einer Rolle, Organisation oder Handlung im Spiel eingebunden werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.2 Verbot religiöser Darstellungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Ausspielen von Religionen oder religiösen Gruppierungen im Roleplay ist nicht gestattet. Hierzu zählen unter anderem religiöse Organisationen, Geistliche Rollen, religiöse Versammlungen oder vergleichbare Darstellungen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.3 Verbot religiöser Aussagen"}]},{"type":"paragraph","content":[{"type":"text","text":"Religiöse Aussagen, Gebete oder Ausrufe sind im Roleplay nicht erwünscht und daher zu unterlassen. Dazu zählen beispielsweise Formulierungen wie „Allahu Akbar“ oder vergleichbare religiöse Ausdrücke aus anderen Glaubensrichtungen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.4 Schutz religiöser Neutralität"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von religiöser Einflussnahme auf andere Spieler, Gruppen oder Fraktionen ist untersagt. Das Roleplay soll frei von religiösen Inhalten bleiben, um Konflikte, Provokationen oder Missverständnisse innerhalb der Community zu vermeiden."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.5 Gleichbehandlung aller Glaubensrichtungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Diese Regelung gilt unabhängig von der jeweiligen Religion oder Weltanschauung. Es werden keine einzelnen Religionen gesondert behandelt; sämtliche religiösen Inhalte sind im Roleplay gleichermaßen untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.6 Konsequenzen bei Verstößen"}]},{"type":"paragraph","content":[{"type":"text","text":"Verstöße gegen diese Regelung können je nach Schwere des Vorfalls durch das Serverteam sanktioniert werden. Mögliche Maßnahmen reichen von Verwarnungen bis hin zu temporären oder permanenten Ausschlüssen vom Server."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.7 Verbot realer Kriege und Konflikte"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Darstellen, Ausspielen oder Thematisieren realer militärischer Konflikte und Kriege im Roleplay ist untersagt. Hierzu zählen unter anderem aktuelle oder vergangene Konflikte zwischen realen Staaten oder Regionen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.8 Bezug auf aktuelle geopolitische Ereignisse"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Erwähnung, Darstellung oder Nachstellung aktueller geopolitischer Ereignisse innerhalb des Roleplays ist nicht gestattet. Der Server soll frei von realpolitischen Spannungen und Konflikten bleiben."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.9 Politische Neutralität"}]},{"type":"paragraph","content":[{"type":"text","text":"Innerhalb des Roleplays ist eine strikt neutrale Haltung gegenüber politischen Themen verpflichtend. Politische Diskussionen, Aussagen oder Darstellungen sind im Roleplay nicht erwünscht."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.10 Verbot politischer Parteien und Ideologien"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Darstellen, Unterstützen oder Erwähnen realer politischer Parteien, Bewegungen oder Ideologien ist im Roleplay untersagt. Hierzu zählen beispielsweise Parteien, politische Gruppierungen oder vergleichbare Organisationen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.11 Politische Parolen und Symbole"}]},{"type":"paragraph","content":[{"type":"text","text":"Politische Parolen, Symbole, Flaggen oder vergleichbare Darstellungen, welche eine politische Position oder Ideologie ausdrücken, dürfen im Roleplay weder verwendet noch gezeigt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.12 Einflussnahme durch politische Inhalte"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von politischer Einflussnahme, Propaganda oder politischer Überzeugungsarbeit gegenüber anderen Spielern ist im Roleplay untersagt, um eine neutrale und konfliktfreie Spielumgebung zu gewährleisten."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.13 Extremistische Inhalte"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Darstellung, Unterstüzung oder Verherrlichung extremistischer, terroristischer oder verfassungsfeindlicher Organisationen, Symbolen, Uniformen, Namen, Parolen, Propaganda oder Gesten ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.14 Realweltiche Tragödien"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Nachtellen, Verherrlichen oder Lächerlichmachen realer Katastrophen, Terroranschläge oder vergleichbarer tragischer Ereignisse ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.15 Religiöse Zeichen"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Tragen und Darstellen religiöser Symbole (wie Schmuck, Flaggen, Schilder, Texte, Ketten o. Ä.) ist nicht gestattet."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§42.0 Neutralität' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§42.0 Neutralität', "order" = 42, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-42-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§42.1 Neutralität im Roleplay"}]},{"type":"paragraph","content":[{"type":"text","text":"Innerhalb des gesamten Roleplays auf dem Server ist ein neutraler Umgang mit religiösen Themen verpflichtend. Religion darf weder aktiv dargestellt, noch als Teil einer Rolle, Organisation oder Handlung im Spiel eingebunden werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.2 Verbot religiöser Darstellungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Ausspielen von Religionen oder religiösen Gruppierungen im Roleplay ist nicht gestattet. Hierzu zählen unter anderem religiöse Organisationen, Geistliche Rollen, religiöse Versammlungen oder vergleichbare Darstellungen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.3 Verbot religiöser Aussagen"}]},{"type":"paragraph","content":[{"type":"text","text":"Religiöse Aussagen, Gebete oder Ausrufe sind im Roleplay nicht erwünscht und daher zu unterlassen. Dazu zählen beispielsweise Formulierungen wie „Allahu Akbar“ oder vergleichbare religiöse Ausdrücke aus anderen Glaubensrichtungen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.4 Schutz religiöser Neutralität"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von religiöser Einflussnahme auf andere Spieler, Gruppen oder Fraktionen ist untersagt. Das Roleplay soll frei von religiösen Inhalten bleiben, um Konflikte, Provokationen oder Missverständnisse innerhalb der Community zu vermeiden."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.5 Gleichbehandlung aller Glaubensrichtungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Diese Regelung gilt unabhängig von der jeweiligen Religion oder Weltanschauung. Es werden keine einzelnen Religionen gesondert behandelt; sämtliche religiösen Inhalte sind im Roleplay gleichermaßen untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.6 Konsequenzen bei Verstößen"}]},{"type":"paragraph","content":[{"type":"text","text":"Verstöße gegen diese Regelung können je nach Schwere des Vorfalls durch das Serverteam sanktioniert werden. Mögliche Maßnahmen reichen von Verwarnungen bis hin zu temporären oder permanenten Ausschlüssen vom Server."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.7 Verbot realer Kriege und Konflikte"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Darstellen, Ausspielen oder Thematisieren realer militärischer Konflikte und Kriege im Roleplay ist untersagt. Hierzu zählen unter anderem aktuelle oder vergangene Konflikte zwischen realen Staaten oder Regionen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.8 Bezug auf aktuelle geopolitische Ereignisse"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Erwähnung, Darstellung oder Nachstellung aktueller geopolitischer Ereignisse innerhalb des Roleplays ist nicht gestattet. Der Server soll frei von realpolitischen Spannungen und Konflikten bleiben."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.9 Politische Neutralität"}]},{"type":"paragraph","content":[{"type":"text","text":"Innerhalb des Roleplays ist eine strikt neutrale Haltung gegenüber politischen Themen verpflichtend. Politische Diskussionen, Aussagen oder Darstellungen sind im Roleplay nicht erwünscht."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.10 Verbot politischer Parteien und Ideologien"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Darstellen, Unterstützen oder Erwähnen realer politischer Parteien, Bewegungen oder Ideologien ist im Roleplay untersagt. Hierzu zählen beispielsweise Parteien, politische Gruppierungen oder vergleichbare Organisationen."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.11 Politische Parolen und Symbole"}]},{"type":"paragraph","content":[{"type":"text","text":"Politische Parolen, Symbole, Flaggen oder vergleichbare Darstellungen, welche eine politische Position oder Ideologie ausdrücken, dürfen im Roleplay weder verwendet noch gezeigt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.12 Einflussnahme durch politische Inhalte"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von politischer Einflussnahme, Propaganda oder politischer Überzeugungsarbeit gegenüber anderen Spielern ist im Roleplay untersagt, um eine neutrale und konfliktfreie Spielumgebung zu gewährleisten."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.13 Extremistische Inhalte"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Darstellung, Unterstüzung oder Verherrlichung extremistischer, terroristischer oder verfassungsfeindlicher Organisationen, Symbolen, Uniformen, Namen, Parolen, Propaganda oder Gesten ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.14 Realweltiche Tragödien"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Nachtellen, Verherrlichen oder Lächerlichmachen realer Katastrophen, Terroranschläge oder vergleichbarer tragischer Ereignisse ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§42.15 Religiöse Zeichen"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Tragen und Darstellen religiöser Symbole (wie Schmuck, Flaggen, Schilder, Texte, Ketten o. Ä.) ist nicht gestattet."}]}]}'::jsonb, '§42.0 Neutralität §42.1 Neutralität im Roleplay Innerhalb des gesamten Roleplays auf dem Server ist ein neutraler Umgang mit religiösen Themen verpflichtend. Religion darf weder aktiv dargestellt, noch als Teil einer Rolle, Organisation oder Handlung im Spiel eingebunden werden. §42.2 Verbot religiöser Darstellungen Das Ausspielen von Religionen oder religiösen Gruppierungen im Roleplay ist nicht gestattet. Hierzu zählen unter anderem religiöse Organisationen, Geistliche Rollen, religiöse Versammlungen oder vergleichbare Darstellungen. §42.3 Verbot religiöser Aussagen Religiöse Aussagen, Gebete oder Ausrufe sind im Roleplay nicht erwünscht und daher zu unterlassen. Dazu zählen beispielsweise Formulierungen wie „Allahu Akbar“ oder vergleichbare religiöse Ausdrücke aus anderen Glaubensrichtungen. §42.4 Schutz religiöser Neutralität Jegliche Form von religiöser Einflussnahme auf andere Spieler, Gruppen oder Fraktionen ist untersagt. Das Roleplay soll frei von religiösen Inhalten bleiben, um Konflikte, Provokationen oder Missverständnisse innerhalb der Community zu vermeiden. §42.5 Gleichbehandlung aller Glaubensrichtungen Diese Regelung gilt unabhängig von der jeweiligen Religion oder Weltanschauung. Es werden keine einzelnen Religionen gesondert behandelt; sämtliche religiösen Inhalte sind im Roleplay gleichermaßen untersagt. §42.6 Konsequenzen bei Verstößen Verstöße gegen diese Regelung können je nach Schwere des Vorfalls durch das Serverteam sanktioniert werden. Mögliche Maßnahmen reichen von Verwarnungen bis hin zu temporären oder permanenten Ausschlüssen vom Server. §42.7 Verbot realer Kriege und Konflikte Das Darstellen, Ausspielen oder Thematisieren realer militärischer Konflikte und Kriege im Roleplay ist untersagt. Hierzu zählen unter anderem aktuelle oder vergangene Konflikte zwischen realen Staaten oder Regionen. §42.8 Bezug auf aktuelle geopolitische Ereignisse Die Erwähnung, Darstellung oder Nachstellung aktueller geopolitischer Ereignisse innerhalb des Roleplays ist nicht gestattet. Der Server soll frei von realpolitischen Spannungen und Konflikten bleiben. §42.9 Politische Neutralität Innerhalb des Roleplays ist eine strikt neutrale Haltung gegenüber politischen Themen verpflichtend. Politische Diskussionen, Aussagen oder Darstellungen sind im Roleplay nicht erwünscht. §42.10 Verbot politischer Parteien und Ideologien Das Darstellen, Unterstützen oder Erwähnen realer politischer Parteien, Bewegungen oder Ideologien ist im Roleplay untersagt. Hierzu zählen beispielsweise Parteien, politische Gruppierungen oder vergleichbare Organisationen. §42.11 Politische Parolen und Symbole Politische Parolen, Symbole, Flaggen oder vergleichbare Darstellungen, welche eine politische Position oder Ideologie ausdrücken, dürfen im Roleplay weder verwendet noch gezeigt werden. §42.12 Einflussnahme durch politische Inhalte Jegliche Form von politischer Einflussnahme, Propaganda oder politischer Überzeugungsarbeit gegenüber anderen Spielern ist im Roleplay untersagt, um eine neutrale und konfliktfreie Spielumgebung zu gewährleisten. §42.13 Extremistische Inhalte Die Darstellung, Unterstüzung oder Verherrlichung extremistischer, terroristischer oder verfassungsfeindlicher Organisationen, Symbolen, Uniformen, Namen, Parolen, Propaganda oder Gesten ist untersagt. §42.14 Realweltiche Tragödien Das Nachtellen, Verherrlichen oder Lächerlichmachen realer Katastrophen, Terroranschläge oder vergleichbarer tragischer Ereignisse ist untersagt. §42.15 Religiöse Zeichen Das Tragen und Darstellen religiöser Symbole (wie Schmuck, Flaggen, Schilder, Texte, Ketten o. Ä.) ist nicht gestattet.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-43';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-43', 'main-43', 'main-43', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§43 Charakterregelung', 43, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§43.1 – Ein Charakter pro Fraktion"},{"type":"hardBreak"},{"type":"text","text":" Jeder Spieler darf innerhalb einer Fraktion ausschließlich "},{"type":"text","text":"einen festen Charakter"},{"type":"text","text":" führen. Mehrere Charaktere innerhalb derselben Fraktion sind nicht gestattet."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.2 – Trennung von Charakteren"},{"type":"hardBreak"},{"type":"text","text":" Das gleichzeitige oder abwechselnde Spielen mehrerer Charaktere in derselben Fraktion, um sich Vorteile zu verschaffen oder Rollen zu umgehen, ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.3 – Fraktionsübergreifende Charaktere"},{"type":"hardBreak"},{"type":"text","text":" Es ist erlaubt, unterschiedliche Charaktere in "},{"type":"text","text":"verschiedenen Fraktionen"},{"type":"text","text":" zu spielen, sofern diese strikt voneinander getrennt sind und keine Informationen oder Vorteile übertragen werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.4 – Verbot von Charakter-Missbrauch"},{"type":"hardBreak"},{"type":"text","text":" Das Erstellen oder Nutzen mehrerer Charaktere innerhalb einer Fraktion zur Umgehung von Regeln, Rangsystemen oder Konsequenzen gilt als Missbrauch und ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.5 – Realistische Charakterführung"},{"type":"hardBreak"},{"type":"text","text":" Jeder Charakter ist eigenständig und realistisch auszuspielen. Ein häufiger oder unlogischer Wechsel zwischen Charakteren innerhalb einer Fraktion ist nicht zulässig."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.6 – Konsequenzen bei Verstößen"},{"type":"hardBreak"},{"type":"text","text":" Verstöße gegen diese Regelung werden sanktioniert. Maßnahmen können je nach Schwere des Verstoßes von Verwarnungen über Fraktionsausschlüsse bis hin zu temporären oder permanenten Sperren führen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§43 Charakterregelung' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§43 Charakterregelung', "order" = 43, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-43-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§43.1 – Ein Charakter pro Fraktion"},{"type":"hardBreak"},{"type":"text","text":" Jeder Spieler darf innerhalb einer Fraktion ausschließlich "},{"type":"text","text":"einen festen Charakter"},{"type":"text","text":" führen. Mehrere Charaktere innerhalb derselben Fraktion sind nicht gestattet."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.2 – Trennung von Charakteren"},{"type":"hardBreak"},{"type":"text","text":" Das gleichzeitige oder abwechselnde Spielen mehrerer Charaktere in derselben Fraktion, um sich Vorteile zu verschaffen oder Rollen zu umgehen, ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.3 – Fraktionsübergreifende Charaktere"},{"type":"hardBreak"},{"type":"text","text":" Es ist erlaubt, unterschiedliche Charaktere in "},{"type":"text","text":"verschiedenen Fraktionen"},{"type":"text","text":" zu spielen, sofern diese strikt voneinander getrennt sind und keine Informationen oder Vorteile übertragen werden."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.4 – Verbot von Charakter-Missbrauch"},{"type":"hardBreak"},{"type":"text","text":" Das Erstellen oder Nutzen mehrerer Charaktere innerhalb einer Fraktion zur Umgehung von Regeln, Rangsystemen oder Konsequenzen gilt als Missbrauch und ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.5 – Realistische Charakterführung"},{"type":"hardBreak"},{"type":"text","text":" Jeder Charakter ist eigenständig und realistisch auszuspielen. Ein häufiger oder unlogischer Wechsel zwischen Charakteren innerhalb einer Fraktion ist nicht zulässig."}]},{"type":"paragraph","content":[{"type":"text","text":"§43.6 – Konsequenzen bei Verstößen"},{"type":"hardBreak"},{"type":"text","text":" Verstöße gegen diese Regelung werden sanktioniert. Maßnahmen können je nach Schwere des Verstoßes von Verwarnungen über Fraktionsausschlüsse bis hin zu temporären oder permanenten Sperren führen."}]}]}'::jsonb, '§43 Charakterregelung §43.1 – Ein Charakter pro Fraktion Jeder Spieler darf innerhalb einer Fraktion ausschließlich einen festen Charakter führen. Mehrere Charaktere innerhalb derselben Fraktion sind nicht gestattet. §43.2 – Trennung von Charakteren Das gleichzeitige oder abwechselnde Spielen mehrerer Charaktere in derselben Fraktion, um sich Vorteile zu verschaffen oder Rollen zu umgehen, ist untersagt. §43.3 – Fraktionsübergreifende Charaktere Es ist erlaubt, unterschiedliche Charaktere in verschiedenen Fraktionen zu spielen, sofern diese strikt voneinander getrennt sind und keine Informationen oder Vorteile übertragen werden. §43.4 – Verbot von Charakter-Missbrauch Das Erstellen oder Nutzen mehrerer Charaktere innerhalb einer Fraktion zur Umgehung von Regeln, Rangsystemen oder Konsequenzen gilt als Missbrauch und ist untersagt. §43.5 – Realistische Charakterführung Jeder Charakter ist eigenständig und realistisch auszuspielen. Ein häufiger oder unlogischer Wechsel zwischen Charakteren innerhalb einer Fraktion ist nicht zulässig. §43.6 – Konsequenzen bei Verstößen Verstöße gegen diese Regelung werden sanktioniert. Maßnahmen können je nach Schwere des Verstoßes von Verwarnungen über Fraktionsausschlüsse bis hin zu temporären oder permanenten Sperren führen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-44';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-44', 'main-44', 'main-44', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', 'Roleplay-Regelwerk', '§44 Drittpartei', 44, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.1 Definition"}]},{"type":"paragraph","content":[{"type":"text","text":"Als Drittpartei gilt jede Person oder Fraktion, die "},{"type":"text","text":"nicht aktiv an einer laufenden RP-Situation beteiligt ist"},{"type":"text","text":", sich jedoch nachträglich in diese einmischt."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.2 Grundsatz"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Eingreifen als Drittpartei ist "},{"type":"text","text":"situationsabhängig geregelt"},{"type":"text","text":" und nicht pauschal verboten."},{"type":"hardBreak"},{"type":"text","text":" Dabei wird zwischen "},{"type":"text","text":"kleinen"},{"type":"text","text":" und "},{"type":"text","text":"großen RP-Situationen"},{"type":"text","text":" unterschieden."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.3 Große RP-Situationen"}]},{"type":"paragraph","content":[{"type":"text","text":"Bei größeren, bereits laufenden Lagen ist das Eingreifen als Drittpartei "},{"type":"text","text":"grundsätzlich untersagt"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Dazu zählen insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"Großunfälle"}]},{"type":"paragraph","content":[{"type":"text","text":"Geiselnahmen (z. B. Bank, Juwelier)"}]},{"type":"paragraph","content":[{"type":"text","text":"Großeinsatzlagen mit mehreren beteiligten Parteien"}]},{"type":"paragraph","content":[{"type":"text","text":"koordinierte oder geplante Events"}]},{"type":"paragraph","content":[{"type":"text","text":"In solchen Situationen dürfen "},{"type":"text","text":"keine weiteren Parteien ohne klare Einbindung"},{"type":"text","text":" eingreifen, um Chaos, Unfairness und Eskalationen zu verhindern."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.4 Kleine RP-Situationen"}]},{"type":"paragraph","content":[{"type":"text","text":"Bei kleineren, überschaubaren Situationen ist eine Einmischung als Drittpartei "},{"type":"text","text":"grundsätzlich erlaubt"},{"type":"text","text":", sofern diese "},{"type":"text","text":"realistisch und nachvollziehbar"},{"type":"text","text":" erfolgt."}]},{"type":"paragraph","content":[{"type":"text","text":"Dazu zählen insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"Verkehrskontrollen"}]},{"type":"paragraph","content":[{"type":"text","text":"Personenkontrollen oder Gespräche"}]},{"type":"paragraph","content":[{"type":"text","text":"kleinere Einzel- oder Alltagssituationen"}]},{"type":"paragraph","content":[{"type":"text","text":"In diesen Fällen ist es erlaubt:"}]},{"type":"paragraph","content":[{"type":"text","text":"sich in das Geschehen einzubringen"}]},{"type":"paragraph","content":[{"type":"text","text":"Situationen zu beeinflussen oder zu erweitern"}]},{"type":"paragraph","content":[{"type":"text","text":"unter Umständen auch Geiselnahmen oder ähnliche Handlungen einzuleiten"}]},{"type":"paragraph","content":[{"type":"text","text":"Voraussetzung ist immer, dass das Eingreifen "},{"type":"text","text":"sauber ausgespielt und logisch begründet"},{"type":"text","text":" ist."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.5 Einschränkungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Auch bei erlaubter Einmischung gilt:"}]},{"type":"paragraph","content":[{"type":"text","text":"Kein unrealistisches oder erzwungenes Verhalten"}]},{"type":"paragraph","content":[{"type":"text","text":"Keine massenhaften Eingriffe ohne RP-Grund"}]},{"type":"paragraph","content":[{"type":"text","text":"Kein gezieltes Stören oder „Zerstören“ von laufendem RP"},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§44 Drittpartei' OR current_rule."category" IS DISTINCT FROM 'Roleplay-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk', "category" = 'Roleplay-Regelwerk', "title" = '§44 Drittpartei', "order" = 44, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-44-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.1 Definition"}]},{"type":"paragraph","content":[{"type":"text","text":"Als Drittpartei gilt jede Person oder Fraktion, die "},{"type":"text","text":"nicht aktiv an einer laufenden RP-Situation beteiligt ist"},{"type":"text","text":", sich jedoch nachträglich in diese einmischt."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.2 Grundsatz"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Eingreifen als Drittpartei ist "},{"type":"text","text":"situationsabhängig geregelt"},{"type":"text","text":" und nicht pauschal verboten."},{"type":"hardBreak"},{"type":"text","text":" Dabei wird zwischen "},{"type":"text","text":"kleinen"},{"type":"text","text":" und "},{"type":"text","text":"großen RP-Situationen"},{"type":"text","text":" unterschieden."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.3 Große RP-Situationen"}]},{"type":"paragraph","content":[{"type":"text","text":"Bei größeren, bereits laufenden Lagen ist das Eingreifen als Drittpartei "},{"type":"text","text":"grundsätzlich untersagt"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Dazu zählen insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"Großunfälle"}]},{"type":"paragraph","content":[{"type":"text","text":"Geiselnahmen (z. B. Bank, Juwelier)"}]},{"type":"paragraph","content":[{"type":"text","text":"Großeinsatzlagen mit mehreren beteiligten Parteien"}]},{"type":"paragraph","content":[{"type":"text","text":"koordinierte oder geplante Events"}]},{"type":"paragraph","content":[{"type":"text","text":"In solchen Situationen dürfen "},{"type":"text","text":"keine weiteren Parteien ohne klare Einbindung"},{"type":"text","text":" eingreifen, um Chaos, Unfairness und Eskalationen zu verhindern."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.4 Kleine RP-Situationen"}]},{"type":"paragraph","content":[{"type":"text","text":"Bei kleineren, überschaubaren Situationen ist eine Einmischung als Drittpartei "},{"type":"text","text":"grundsätzlich erlaubt"},{"type":"text","text":", sofern diese "},{"type":"text","text":"realistisch und nachvollziehbar"},{"type":"text","text":" erfolgt."}]},{"type":"paragraph","content":[{"type":"text","text":"Dazu zählen insbesondere:"}]},{"type":"paragraph","content":[{"type":"text","text":"Verkehrskontrollen"}]},{"type":"paragraph","content":[{"type":"text","text":"Personenkontrollen oder Gespräche"}]},{"type":"paragraph","content":[{"type":"text","text":"kleinere Einzel- oder Alltagssituationen"}]},{"type":"paragraph","content":[{"type":"text","text":"In diesen Fällen ist es erlaubt:"}]},{"type":"paragraph","content":[{"type":"text","text":"sich in das Geschehen einzubringen"}]},{"type":"paragraph","content":[{"type":"text","text":"Situationen zu beeinflussen oder zu erweitern"}]},{"type":"paragraph","content":[{"type":"text","text":"unter Umständen auch Geiselnahmen oder ähnliche Handlungen einzuleiten"}]},{"type":"paragraph","content":[{"type":"text","text":"Voraussetzung ist immer, dass das Eingreifen "},{"type":"text","text":"sauber ausgespielt und logisch begründet"},{"type":"text","text":" ist."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§44.5 Einschränkungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Auch bei erlaubter Einmischung gilt:"}]},{"type":"paragraph","content":[{"type":"text","text":"Kein unrealistisches oder erzwungenes Verhalten"}]},{"type":"paragraph","content":[{"type":"text","text":"Keine massenhaften Eingriffe ohne RP-Grund"}]},{"type":"paragraph","content":[{"type":"text","text":"Kein gezieltes Stören oder „Zerstören“ von laufendem RP"},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§44 Drittpartei §44.1 Definition Als Drittpartei gilt jede Person oder Fraktion, die nicht aktiv an einer laufenden RP-Situation beteiligt ist , sich jedoch nachträglich in diese einmischt. §44.2 Grundsatz Das Eingreifen als Drittpartei ist situationsabhängig geregelt und nicht pauschal verboten. Dabei wird zwischen kleinen und großen RP-Situationen unterschieden. §44.3 Große RP-Situationen Bei größeren, bereits laufenden Lagen ist das Eingreifen als Drittpartei grundsätzlich untersagt . Dazu zählen insbesondere: Großunfälle Geiselnahmen (z. B. Bank, Juwelier) Großeinsatzlagen mit mehreren beteiligten Parteien koordinierte oder geplante Events In solchen Situationen dürfen keine weiteren Parteien ohne klare Einbindung eingreifen, um Chaos, Unfairness und Eskalationen zu verhindern. §44.4 Kleine RP-Situationen Bei kleineren, überschaubaren Situationen ist eine Einmischung als Drittpartei grundsätzlich erlaubt , sofern diese realistisch und nachvollziehbar erfolgt. Dazu zählen insbesondere: Verkehrskontrollen Personenkontrollen oder Gespräche kleinere Einzel- oder Alltagssituationen In diesen Fällen ist es erlaubt: sich in das Geschehen einzubringen Situationen zu beeinflussen oder zu erweitern unter Umständen auch Geiselnahmen oder ähnliche Handlungen einzuleiten Voraussetzung ist immer, dass das Eingreifen sauber ausgespielt und logisch begründet ist. §44.5 Einschränkungen Auch bei erlaubter Einmischung gilt: Kein unrealistisches oder erzwungenes Verhalten Keine massenhaften Eingriffe ohne RP-Grund Kein gezieltes Stören oder „Zerstören“ von laufendem RP', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

