      ('revision-main-47-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§47.1 Grundsatz"}]},{"type":"paragraph","content":[{"type":"text","text":"Deutschland Roleplay ist ein öffentlich zugänglicher Roleplay-Server. Aus diesem Grund sind sämtliche Inhalte mit sexuellem oder pornografischem Charakter untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Roleplay hat jederzeit auf einem angemessenen und jugendgerechten Niveau stattzufinden."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§47.2 Verbotene Inhalte"}]},{"type":"paragraph","content":[{"type":"text","text":"Insbesondere untersagt sind:"}]},{"type":"paragraph","content":[{"type":"text","text":"Sexuelles oder pornografisches Roleplay."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Ausspielen sexueller Handlungen oder Andeutungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Erotische oder stark sexualisierte Charakterdarstellungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Aufforderungen zu sexuellen Handlungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Prostitution oder vergleichbare Dienstleistungen."}]},{"type":"paragraph","content":[{"type":"text","text":"BDSM-, Fetisch- oder ähnliche Inhalte."}]},{"type":"paragraph","content":[{"type":"text","text":"Übermäßig sexualisierte Dialoge oder Emotes."}]},{"type":"paragraph","content":[{"type":"text","text":"Das bewusste Ausspielen intimer Körperbereiche oder Handlungen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§47.3 Belästigung"}]},{"type":"paragraph","content":[{"type":"text","text":"Ebenso untersagt sind:"}]},{"type":"paragraph","content":[{"type":"text","text":"Sexuelle Belästigung anderer Spieler."}]},{"type":"paragraph","content":[{"type":"text","text":"Ungewollte sexuelle Annäherungen im Roleplay."}]},{"type":"paragraph","content":[{"type":"text","text":"Anzügliche oder eindeutig sexuelle Nachrichten, sofern diese über normales, angemessenes Flirten hinausgehen."}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliches Verhalten, das andere Spieler belästigt oder unter Druck setzt."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"§47.4 Konsequenzen"}]},{"type":"paragraph","content":[{"type":"text","text":"Verstöße gegen diese Regel werden aufgrund ihrer Schwere konsequent geahndet und können abhängig vom Einzelfall unmittelbar zu schwerwiegenden Sanktionen führen."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§47 FSK-18-Inhalte und sexualisiertes Roleplay §47.1 Grundsatz Deutschland Roleplay ist ein öffentlich zugänglicher Roleplay-Server. Aus diesem Grund sind sämtliche Inhalte mit sexuellem oder pornografischem Charakter untersagt. Roleplay hat jederzeit auf einem angemessenen und jugendgerechten Niveau stattzufinden. §47.2 Verbotene Inhalte Insbesondere untersagt sind: Sexuelles oder pornografisches Roleplay. Das Ausspielen sexueller Handlungen oder Andeutungen. Erotische oder stark sexualisierte Charakterdarstellungen. Aufforderungen zu sexuellen Handlungen. Prostitution oder vergleichbare Dienstleistungen. BDSM-, Fetisch- oder ähnliche Inhalte. Übermäßig sexualisierte Dialoge oder Emotes. Das bewusste Ausspielen intimer Körperbereiche oder Handlungen. §47.3 Belästigung Ebenso untersagt sind: Sexuelle Belästigung anderer Spieler. Ungewollte sexuelle Annäherungen im Roleplay. Anzügliche oder eindeutig sexuelle Nachrichten, sofern diese über normales, angemessenes Flirten hinausgehen. Jegliches Verhalten, das andere Spieler belästigt oder unter Druck setzt. §47.4 Konsequenzen Verstöße gegen diese Regel werden aufgrund ihrer Schwere konsequent geahndet und können abhängig vom Einzelfall unmittelbar zu schwerwiegenden Sanktionen führen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

