DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'discord-1';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-discord-1', 'discord-1', 'discord-1', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk/discord-regelwerk', 'Discord-Regelwerk', '§1. Allgemeine Verhaltensregeln', 1, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.1 Respektvoller Umgang"}]},{"type":"paragraph","content":[{"type":"text","text":"Jedes Mitglied verpflichtet sich zu einem respektvollen, höflichen und angemessenen Umgangston – unabhängig von Herkunft, Geschlecht, Religion oder anderen persönlichen Merkmalen."}]},{"type":"paragraph","content":[{"type":"text","text":"Beleidigungen, Mobbing, Provokationen, toxisches Verhalten oder persönliche Angriffe sind strengstens untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Ironie oder Sarkasmus auf Kosten anderer ist zu vermeiden, insbesondere wenn diese nicht eindeutig als solche erkennbar ist."}]},{"type":"paragraph","content":[{"type":"text","text":"Diskussionen über hochgradig kontroverse Themen (z. B. Politik, aktuelle Kriege oder Religion) sind auf diesem Server nicht gestattet. Wir möchten einen sicheren Ort für alle Menschen bieten, unabhängig von ihrer Weltanschauung."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.2 OOC-Themenabbruch"}]},{"type":"paragraph","content":[{"type":"text","text":"Jedes Mitglied hat das Recht, ein laufendes OOC-Gespräch (Out of Character) zu beenden, wenn das Thema als belastend, unangenehm oder verletzend empfunden wird."}]},{"type":"paragraph","content":[{"type":"text","text":"Sobald ein Teilnehmer klar signalisiert, dass das Thema beendet werden soll (z. B. „Ich möchte darüber nicht weiter reden“ oder „Themenwechsel bitte“), haben alle anderen Beteiligten dies sofort zu respektieren. Bei Zuwiderhandlung greift das Team sanktionierend ein."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.3 Kommunikation & Medien"}]},{"type":"paragraph","content":[{"type":"text","text":"Gespräche sollen stets auf einer sachlichen und reifen Ebene stattfinden."}]},{"type":"paragraph","content":[{"type":"text","text":"Spam, Capslock (permanentes Schreiben in Großbuchstaben), übermäßiger Gebrauch von Emojis, NSFW-Inhalte (Not Safe For Work) oder unnötige Ping-Wellen (Massenmarkierungen) sind verboten."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Kommunikation im Voicechat hat klar, deutlich und ohne störende Hintergrundgeräusche zu erfolgen. Der Missbrauch von Soundboards, Stimmenverzerrern oder Musikbots ohne ausdrückliche Erlaubnis der Channel-Teilnehmer ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Keine Missionierung:"},{"type":"text","text":" Es ist strikt verboten, zu versuchen, andere Mitglieder von der eigenen politischen, religiösen oder ideologischen Meinung zu überzeugen. Der Discord dient dem Austausch über das RP-Projekt, nicht der politischen Debatte oder Mobilisierung."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.4 Werbung und externe Inhalte"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von Eigenwerbung für andere Server, Communities, Social-Media-Kanäle oder fremde Projekte ist verboten – dies gilt sowohl öffentlich als auch in privaten Nachrichten (DMs) an Mitglieder dieses Servers (User-Advertising)."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Teilen von Links zu externen Inhalten (z. B. YouTube, Twitch, Webseiten) ist in den öffentlichen Channels nur mit vorheriger Genehmigung durch das Server-Team gestattet (ausgenommen sind dafür speziell eingerichtete Media-Channels)."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§1. Allgemeine Verhaltensregeln' OR current_rule."category" IS DISTINCT FROM 'Discord-Regelwerk' THEN
      next_version := current_rule."version" + 1;
