    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-discord-1-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.1 Respektvoller Umgang"}]},{"type":"paragraph","content":[{"type":"text","text":"Jedes Mitglied verpflichtet sich zu einem respektvollen, höflichen und angemessenen Umgangston – unabhängig von Herkunft, Geschlecht, Religion oder anderen persönlichen Merkmalen."}]},{"type":"paragraph","content":[{"type":"text","text":"Beleidigungen, Mobbing, Provokationen, toxisches Verhalten oder persönliche Angriffe sind strengstens untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Ironie oder Sarkasmus auf Kosten anderer ist zu vermeiden, insbesondere wenn diese nicht eindeutig als solche erkennbar ist."}]},{"type":"paragraph","content":[{"type":"text","text":"Diskussionen über hochgradig kontroverse Themen (z. B. Politik, aktuelle Kriege oder Religion) sind auf diesem Server nicht gestattet. Wir möchten einen sicheren Ort für alle Menschen bieten, unabhängig von ihrer Weltanschauung."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.2 OOC-Themenabbruch"}]},{"type":"paragraph","content":[{"type":"text","text":"Jedes Mitglied hat das Recht, ein laufendes OOC-Gespräch (Out of Character) zu beenden, wenn das Thema als belastend, unangenehm oder verletzend empfunden wird."}]},{"type":"paragraph","content":[{"type":"text","text":"Sobald ein Teilnehmer klar signalisiert, dass das Thema beendet werden soll (z. B. „Ich möchte darüber nicht weiter reden“ oder „Themenwechsel bitte“), haben alle anderen Beteiligten dies sofort zu respektieren. Bei Zuwiderhandlung greift das Team sanktionierend ein."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.3 Kommunikation & Medien"}]},{"type":"paragraph","content":[{"type":"text","text":"Gespräche sollen stets auf einer sachlichen und reifen Ebene stattfinden."}]},{"type":"paragraph","content":[{"type":"text","text":"Spam, Capslock (permanentes Schreiben in Großbuchstaben), übermäßiger Gebrauch von Emojis, NSFW-Inhalte (Not Safe For Work) oder unnötige Ping-Wellen (Massenmarkierungen) sind verboten."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Kommunikation im Voicechat hat klar, deutlich und ohne störende Hintergrundgeräusche zu erfolgen. Der Missbrauch von Soundboards, Stimmenverzerrern oder Musikbots ohne ausdrückliche Erlaubnis der Channel-Teilnehmer ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Keine Missionierung:"},{"type":"text","text":" Es ist strikt verboten, zu versuchen, andere Mitglieder von der eigenen politischen, religiösen oder ideologischen Meinung zu überzeugen. Der Discord dient dem Austausch über das RP-Projekt, nicht der politischen Debatte oder Mobilisierung."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§1.4 Werbung und externe Inhalte"}]},{"type":"paragraph","content":[{"type":"text","text":"Jegliche Form von Eigenwerbung für andere Server, Communities, Social-Media-Kanäle oder fremde Projekte ist verboten – dies gilt sowohl öffentlich als auch in privaten Nachrichten (DMs) an Mitglieder dieses Servers (User-Advertising)."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Teilen von Links zu externen Inhalten (z. B. YouTube, Twitch, Webseiten) ist in den öffentlichen Channels nur mit vorheriger Genehmigung durch das Server-Team gestattet (ausgenommen sind dafür speziell eingerichtete Media-Channels)."}]}]}'::jsonb, '§1. Allgemeine Verhaltensregeln §1.1 Respektvoller Umgang Jedes Mitglied verpflichtet sich zu einem respektvollen, höflichen und angemessenen Umgangston – unabhängig von Herkunft, Geschlecht, Religion oder anderen persönlichen Merkmalen. Beleidigungen, Mobbing, Provokationen, toxisches Verhalten oder persönliche Angriffe sind strengstens untersagt. Ironie oder Sarkasmus auf Kosten anderer ist zu vermeiden, insbesondere wenn diese nicht eindeutig als solche erkennbar ist. Diskussionen über hochgradig kontroverse Themen (z. B. Politik, aktuelle Kriege oder Religion) sind auf diesem Server nicht gestattet. Wir möchten einen sicheren Ort für alle Menschen bieten, unabhängig von ihrer Weltanschauung. §1.2 OOC-Themenabbruch Jedes Mitglied hat das Recht, ein laufendes OOC-Gespräch (Out of Character) zu beenden, wenn das Thema als belastend, unangenehm oder verletzend empfunden wird. Sobald ein Teilnehmer klar signalisiert, dass das Thema beendet werden soll (z. B. „Ich möchte darüber nicht weiter reden“ oder „Themenwechsel bitte“), haben alle anderen Beteiligten dies sofort zu respektieren. Bei Zuwiderhandlung greift das Team sanktionierend ein. §1.3 Kommunikation & Medien Gespräche sollen stets auf einer sachlichen und reifen Ebene stattfinden. Spam, Capslock (permanentes Schreiben in Großbuchstaben), übermäßiger Gebrauch von Emojis, NSFW-Inhalte (Not Safe For Work) oder unnötige Ping-Wellen (Massenmarkierungen) sind verboten. Die Kommunikation im Voicechat hat klar, deutlich und ohne störende Hintergrundgeräusche zu erfolgen. Der Missbrauch von Soundboards, Stimmenverzerrern oder Musikbots ohne ausdrückliche Erlaubnis der Channel-Teilnehmer ist untersagt. Keine Missionierung: Es ist strikt verboten, zu versuchen, andere Mitglieder von der eigenen politischen, religiösen oder ideologischen Meinung zu überzeugen. Der Discord dient dem Austausch über das RP-Projekt, nicht der politischen Debatte oder Mobilisierung. §1.4 Werbung und externe Inhalte Jegliche Form von Eigenwerbung für andere Server, Communities, Social-Media-Kanäle oder fremde Projekte ist verboten – dies gilt sowohl öffentlich als auch in privaten Nachrichten (DMs) an Mitglieder dieses Servers (User-Advertising). Das Teilen von Links zu externen Inhalten (z. B. YouTube, Twitch, Webseiten) ist in den öffentlichen Channels nur mit vorheriger Genehmigung durch das Server-Team gestattet (ausgenommen sind dafür speziell eingerichtete Media-Channels).', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'discord-2';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-discord-2', 'discord-2', 'discord-2', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk/discord-regelwerk', 'Discord-Regelwerk', '§2. Discord-Nutzung und Kanalverhalten', 2, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§2.1 Kanalverhalten"}]},{"type":"paragraph","content":[{"type":"text","text":"Jeder Channel besitzt eine zugewiesene Funktion und ist dementsprechend zu nutzen. Beiträge, die nicht zum Thema des Kanals passen (Off-Topic), können vom Team kommentarlos gelöscht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Diskussionen, die ausarten oder ins Off-Topic abgleiten, sind eigenständig in die dafür vorgesehenen Channels zu verschieben."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§2.2 Nickname und Profilbild"}]},{"type":"paragraph","content":[{"type":"text","text":"Nicknamen dürfen keine anstößigen, provozierenden, rassistischen oder irreführenden Begriffe (wie z.B. das Vortäuschen von Team-Rängen) enthalten."}]},{"type":"paragraph","content":[{"type":"text","text":"Profilbilder oder Status-Meldungen mit NSFW-, Gewalt-, oder extremistischen Inhalten sind untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Team behält sich das Recht vor, unangemessene Namen oder Avatare serverseitig zu ändern und das Mitglied zu verwarnen."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§2.3 Unterbindung von Gesprächsmonopolen & Venting"}]},{"type":"paragraph","content":[{"type":"text","text":"Kanäle dürfen nicht so genutzt werden, dass die Teilnahme anderer User gezielt behindert, unterdrückt oder im Keim erstickt wird."}]},{"type":"paragraph","content":[{"type":"text","text":"Venting-Verbot:"},{"type":"text","text":" Der öffentliche Chat ist kein Ort, um ungefiltert privaten Frust oder psychische Belastungen abzuladen („Venting“). Bei persönlichen Problemen wende dich bitte an Freunde per DM oder nutze entsprechende professionelle Hilfsangebote außerhalb des Servers."}]},{"type":"paragraph","content":[{"type":"text","text":"Langanhaltende Diskussionen, die nur zwei Personen betreffen, sind unverzüglich in die Direktnachrichten (DMs) zu verlegen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§2. Discord-Nutzung und Kanalverhalten' OR current_rule."category" IS DISTINCT FROM 'Discord-Regelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk/discord-regelwerk', "category" = 'Discord-Regelwerk', "title" = '§2. Discord-Nutzung und Kanalverhalten', "order" = 2, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-discord-2-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§2.1 Kanalverhalten"}]},{"type":"paragraph","content":[{"type":"text","text":"Jeder Channel besitzt eine zugewiesene Funktion und ist dementsprechend zu nutzen. Beiträge, die nicht zum Thema des Kanals passen (Off-Topic), können vom Team kommentarlos gelöscht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Diskussionen, die ausarten oder ins Off-Topic abgleiten, sind eigenständig in die dafür vorgesehenen Channels zu verschieben."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§2.2 Nickname und Profilbild"}]},{"type":"paragraph","content":[{"type":"text","text":"Nicknamen dürfen keine anstößigen, provozierenden, rassistischen oder irreführenden Begriffe (wie z.B. das Vortäuschen von Team-Rängen) enthalten."}]},{"type":"paragraph","content":[{"type":"text","text":"Profilbilder oder Status-Meldungen mit NSFW-, Gewalt-, oder extremistischen Inhalten sind untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Team behält sich das Recht vor, unangemessene Namen oder Avatare serverseitig zu ändern und das Mitglied zu verwarnen."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§2.3 Unterbindung von Gesprächsmonopolen & Venting"}]},{"type":"paragraph","content":[{"type":"text","text":"Kanäle dürfen nicht so genutzt werden, dass die Teilnahme anderer User gezielt behindert, unterdrückt oder im Keim erstickt wird."}]},{"type":"paragraph","content":[{"type":"text","text":"Venting-Verbot:"},{"type":"text","text":" Der öffentliche Chat ist kein Ort, um ungefiltert privaten Frust oder psychische Belastungen abzuladen („Venting“). Bei persönlichen Problemen wende dich bitte an Freunde per DM oder nutze entsprechende professionelle Hilfsangebote außerhalb des Servers."}]},{"type":"paragraph","content":[{"type":"text","text":"Langanhaltende Diskussionen, die nur zwei Personen betreffen, sind unverzüglich in die Direktnachrichten (DMs) zu verlegen."}]}]}'::jsonb, '§2. Discord-Nutzung und Kanalverhalten §2.1 Kanalverhalten Jeder Channel besitzt eine zugewiesene Funktion und ist dementsprechend zu nutzen. Beiträge, die nicht zum Thema des Kanals passen (Off-Topic), können vom Team kommentarlos gelöscht werden. Diskussionen, die ausarten oder ins Off-Topic abgleiten, sind eigenständig in die dafür vorgesehenen Channels zu verschieben. §2.2 Nickname und Profilbild Nicknamen dürfen keine anstößigen, provozierenden, rassistischen oder irreführenden Begriffe (wie z.B. das Vortäuschen von Team-Rängen) enthalten. Profilbilder oder Status-Meldungen mit NSFW-, Gewalt-, oder extremistischen Inhalten sind untersagt. Das Team behält sich das Recht vor, unangemessene Namen oder Avatare serverseitig zu ändern und das Mitglied zu verwarnen. §2.3 Unterbindung von Gesprächsmonopolen & Venting Kanäle dürfen nicht so genutzt werden, dass die Teilnahme anderer User gezielt behindert, unterdrückt oder im Keim erstickt wird. Venting-Verbot: Der öffentliche Chat ist kein Ort, um ungefiltert privaten Frust oder psychische Belastungen abzuladen („Venting“). Bei persönlichen Problemen wende dich bitte an Freunde per DM oder nutze entsprechende professionelle Hilfsangebote außerhalb des Servers. Langanhaltende Diskussionen, die nur zwei Personen betreffen, sind unverzüglich in die Direktnachrichten (DMs) zu verlegen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

