      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk/discord-regelwerk', "category" = 'Discord-Regelwerk', "title" = '§3. Rollen, Rechte und Teamstruktur', "order" = 3, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-discord-3-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§3.1 Rollenverteilung"}]},{"type":"paragraph","content":[{"type":"text","text":"Rollen werden ausschließlich durch das Server-Team entsprechend der Funktion im RP oder in der Community vergeben. Das gezielte Erfragen oder „Erbetteln“ von Rollen, Rechten oder Team-Posten ist zu unterlassen."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§3.2 Umgang mit dem Server-Team"}]},{"type":"paragraph","content":[{"type":"text","text":"Den Anweisungen des Server-Teams (Supporter, Moderatoren, Admins, Projektleitung) ist Folge zu leisten."}]},{"type":"paragraph","content":[{"type":"text","text":"Diskussionen über administrative Entscheidungen sind auf sachliche Weise über die vorgesehenen Wege (Ticketsystem) zu führen."}]},{"type":"paragraph","content":[{"type":"text","text":"Diskussionsverbot:"},{"type":"text","text":" Wer wiederholt oder absichtlich Diskussionen mit dem Team im öffentlichen Chat in die Länge zieht, um Unruhe zu stiften, muss mit sofortigen Sanktionen rechnen."}]},{"type":"paragraph","content":[{"type":"text","text":"Fehlverhalten von Teammitgliedern kann mit stichhaltigen Beweisen vertraulich über ein Ticket direkt an die Projektleitung gemeldet werden."}]}]}'::jsonb, '§3. Rollen, Rechte und Teamstruktur §3.1 Rollenverteilung Rollen werden ausschließlich durch das Server-Team entsprechend der Funktion im RP oder in der Community vergeben. Das gezielte Erfragen oder „Erbetteln“ von Rollen, Rechten oder Team-Posten ist zu unterlassen. §3.2 Umgang mit dem Server-Team Den Anweisungen des Server-Teams (Supporter, Moderatoren, Admins, Projektleitung) ist Folge zu leisten. Diskussionen über administrative Entscheidungen sind auf sachliche Weise über die vorgesehenen Wege (Ticketsystem) zu führen. Diskussionsverbot: Wer wiederholt oder absichtlich Diskussionen mit dem Team im öffentlichen Chat in die Länge zieht, um Unruhe zu stiften, muss mit sofortigen Sanktionen rechnen. Fehlverhalten von Teammitgliedern kann mit stichhaltigen Beweisen vertraulich über ein Ticket direkt an die Projektleitung gemeldet werden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

