      ('revision-discord-5-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§5.1 Datenschutz & Privatsphäre"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Verbreiten personenbezogener Daten (Doxing) – egal ob von dir selbst oder anderen – wie echte Namen, Wohnorte, Adressen, Telefonnummern oder private Social-Media-Profile, ist strengstens untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Veröffentlichung von vertraulichen Inhalten – insbesondere Screenshots aus privaten Chats (DMs) oder internen Team-Kanälen – ohne ausdrückliche Erlaubnis aller Beteiligten ist verboten."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§5.2 Aufnahmen und Screenshots"}]},{"type":"paragraph","content":[{"type":"text","text":"Voice-Aufnahmen:"},{"type":"text","text":" Das Mitschneiden von Gesprächen im Voice-Chat ist grundsätzlich nur mit vorheriger Zustimmung aller Beteiligten erlaubt."},{"type":"text","text":"Ausnahme:"},{"type":"text","text":" Zu Beweiszwecken bei Regelverstößen für den Support ist eine Aufnahme gestattet. Diese Aufnahme darf jedoch "},{"type":"text","text":"ausschließlich"},{"type":"text","text":" dem Server-Team im Ticket vorgelegt und nirgendwo anders veröffentlicht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahme:"},{"type":"text","text":" Zu Beweiszwecken bei Regelverstößen für den Support ist eine Aufnahme gestattet. Diese Aufnahme darf jedoch "},{"type":"text","text":"ausschließlich"},{"type":"text","text":" dem Server-Team im Ticket vorgelegt und nirgendwo anders veröffentlicht werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Screenshots:"},{"type":"text","text":" Screenshots von privaten Chatverläufen dürfen nur zu Beweiszwecken für den Support angefertigt werden. In-Game-Screenshots für den normalen Community-Austausch sind natürlich erlaubt."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§5.3 Jugendschutz (Minderjährige)"}]},{"type":"paragraph","content":[{"type":"text","text":"Der Schutz minderjähriger Spieler hat oberste Priorität. Die Weitergabe von Klarnamen, Fotos, Standorten oder privaten Verläufen von Minderjährigen wird drakonisch bestraft."}]},{"type":"paragraph","content":[{"type":"text","text":"Wer gezielt versucht, sensible Informationen über das Privatleben minderjähriger User zu erschleichen oder zu sammeln, wird "},{"type":"text","text":"permanent und ohne Vorwarnung"},{"type":"text","text":" von gesamten Projekt (Discord & Roblox) ausgeschlossen. Bei schweren Verstößen behalten wir uns rechtliche Schritte vor."}]}]}'::jsonb, '§5. Sicherheit und Datenschutz §5.1 Datenschutz & Privatsphäre Das Verbreiten personenbezogener Daten (Doxing) – egal ob von dir selbst oder anderen – wie echte Namen, Wohnorte, Adressen, Telefonnummern oder private Social-Media-Profile, ist strengstens untersagt. Die Veröffentlichung von vertraulichen Inhalten – insbesondere Screenshots aus privaten Chats (DMs) oder internen Team-Kanälen – ohne ausdrückliche Erlaubnis aller Beteiligten ist verboten. §5.2 Aufnahmen und Screenshots Voice-Aufnahmen: Das Mitschneiden von Gesprächen im Voice-Chat ist grundsätzlich nur mit vorheriger Zustimmung aller Beteiligten erlaubt. Ausnahme: Zu Beweiszwecken bei Regelverstößen für den Support ist eine Aufnahme gestattet. Diese Aufnahme darf jedoch ausschließlich dem Server-Team im Ticket vorgelegt und nirgendwo anders veröffentlicht werden. Ausnahme: Zu Beweiszwecken bei Regelverstößen für den Support ist eine Aufnahme gestattet. Diese Aufnahme darf jedoch ausschließlich dem Server-Team im Ticket vorgelegt und nirgendwo anders veröffentlicht werden. Screenshots: Screenshots von privaten Chatverläufen dürfen nur zu Beweiszwecken für den Support angefertigt werden. In-Game-Screenshots für den normalen Community-Austausch sind natürlich erlaubt. §5.3 Jugendschutz (Minderjährige) Der Schutz minderjähriger Spieler hat oberste Priorität. Die Weitergabe von Klarnamen, Fotos, Standorten oder privaten Verläufen von Minderjährigen wird drakonisch bestraft. Wer gezielt versucht, sensible Informationen über das Privatleben minderjähriger User zu erschleichen oder zu sammeln, wird permanent und ohne Vorwarnung von gesamten Projekt (Discord & Roblox) ausgeschlossen. Bei schweren Verstößen behalten wir uns rechtliche Schritte vor.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

