      ('rule-discord-6', 'discord-6', 'discord-6', 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk/discord-regelwerk', 'Discord-Regelwerk', '§6. Sanktionen und Beschwerden', 6, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
