    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.1 Sanktionen bei Regelverstößen"}]},{"type":"paragraph","content":[{"type":"text","text":"Regelverstöße werden je nach Schwere und Häufigkeit gestaffelt sanktioniert (Mündliche Verwarnung, System-Warn, temporärer Server-Timeout, temporärer oder permanenter Ausschluss)."}]},{"type":"paragraph","content":[{"type":"text","text":"Wiederholte Verstöße auf dem Discord spiegeln sich auf deine Community-Akte wider und können zum dauerhaften Ausschluss vom gesamten RP-Projekt führen."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.2 Beschwerden und Einsprüche"}]},{"type":"paragraph","content":[{"type":"text","text":"Beschwerden über andere Nutzer oder Teammitglieder sind mit aussagekräftigen Beweisen (unbearbeitete Screenshots/Videos) über das Ticketsystem einzureichen."}]},{"type":"paragraph","content":[{"type":"text","text":"Einsprüche gegen Strafen können schriftlich via Ticket eingereicht werden. Dabei ist eine sachliche und respektvolle Form zu wahren. Unhöfliche Einsprüche werden direkt abgelehnt."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§6. Sanktionen und Beschwerden' OR current_rule."category" IS DISTINCT FROM 'Discord-Regelwerk' THEN
