    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/regelwerk/discord-regelwerk', "category" = 'Discord-Regelwerk', "title" = '§6. Sanktionen und Beschwerden', "order" = 6, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-discord-6-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.1 Sanktionen bei Regelverstößen"}]},{"type":"paragraph","content":[{"type":"text","text":"Regelverstöße werden je nach Schwere und Häufigkeit gestaffelt sanktioniert (Mündliche Verwarnung, System-Warn, temporärer Server-Timeout, temporärer oder permanenter Ausschluss)."}]},{"type":"paragraph","content":[{"type":"text","text":"Wiederholte Verstöße auf dem Discord spiegeln sich auf deine Community-Akte wider und können zum dauerhaften Ausschluss vom gesamten RP-Projekt führen."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.2 Beschwerden und Einsprüche"}]},{"type":"paragraph","content":[{"type":"text","text":"Beschwerden über andere Nutzer oder Teammitglieder sind mit aussagekräftigen Beweisen (unbearbeitete Screenshots/Videos) über das Ticketsystem einzureichen."}]},{"type":"paragraph","content":[{"type":"text","text":"Einsprüche gegen Strafen können schriftlich via Ticket eingereicht werden. Dabei ist eine sachliche und respektvolle Form zu wahren. Unhöfliche Einsprüche werden direkt abgelehnt."},{"type":"hardBreak"},{"type":"hardBreak"}]}]}'::jsonb, '§6. Sanktionen und Beschwerden §6.1 Sanktionen bei Regelverstößen Regelverstöße werden je nach Schwere und Häufigkeit gestaffelt sanktioniert (Mündliche Verwarnung, System-Warn, temporärer Server-Timeout, temporärer oder permanenter Ausschluss). Wiederholte Verstöße auf dem Discord spiegeln sich auf deine Community-Akte wider und können zum dauerhaften Ausschluss vom gesamten RP-Projekt führen. §6.2 Beschwerden und Einsprüche Beschwerden über andere Nutzer oder Teammitglieder sind mit aussagekräftigen Beweisen (unbearbeitete Screenshots/Videos) über das Ticketsystem einzureichen. Einsprüche gegen Strafen können schriftlich via Ticket eingereicht werden. Dabei ist eine sachliche und respektvolle Form zu wahren. Unhöfliche Einsprüche werden direkt abgelehnt.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

