    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§1.1 Begriffserklärung"}]},{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen: "},{"type":"text","text":"Hauptfraktionen sind die zentralen Organisationen des Servers, welche die Grundversorgung des Roleplays sicherstellen (z. B. Polizei, Feuerwehr, Rettungsdienst). Aufgrund ihrer tragenden Rolle für Sicherheit und Ordnung gelten für sie und ihre Mitglieder verschärfte Anforderungen an Aktivität, Serverpräsenz und vorbildliches Verhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"Unterfraktionen: "},{"type":"text","text":"Unterfraktionen / Abteilungen sind eigegliederte Fraktionen die unter der Hauptfraktionen aggieren und unterstüzen, diese haben denoch eine eigene leitung."}]},{"type":"paragraph","content":[{"type":"text","text":"Legale Fraktionen: "},{"type":"text","text":"Diese Agieren als Firmen im Roleplay und verfolgen behördliche und wirtschaftliche Ziele."}]},{"type":"paragraph","content":[{"type":"text","text":"Illegale Fraktionen / Gangs: "},{"type":"text","text":"Sie sind auf Kriminelle Aktivitäten ausgelegt und agieren auserhalb des Gesetzes."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktions-Discords & Kompetenzen:"},{"type":"text","text":" Die übergeordnete Verwaltung aller Fraktionen obliegt dem Fraktionsmanagement und dem Project Manager / Ass.. Für alle offiziellen Fraktions-Discord-Server gilt:"}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM muss jederzeit vollen Lese- und Kontrollzugriff (mindestens Audit-Log-Einsicht) besitzen. Dh das FM "},{"type":"text","text":"MUSS "},{"type":"text","text":"in alle channels reinschauen können zur Kontrolle."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsleitungen dürfen ihren Mitgliedern "},{"type":"text","text":"keine administrativen Rechte"},{"type":"text","text":" (z. B. \"Server verwalten\", \"Rollen verwalten\", \"Administrator\") auf den Fraktions-Discords geben, um Missbrauch vorzubeugen. Admin-Rechte liegen exklusiv beim FM/Serverleitung."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.2 Verantwortlichkeiten"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsleitung:"},{"type":"text","text":" Ist vollumfänglich für die interne Organisation, die Aktivitätskontrolle, das Fehlverhalten ihrer Mitglieder sowie die Durchsetzung des Regelwerks innerhalb der Fraktion verantwortlich."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsmanagement (FM):"},{"type":"text","text":" Überwacht die Fraktionslandschaft, agiert als neutrale Beschwerdestelle, greift bei Missständen ein und sorgt für ein faires Balancing im Gesamt-RP."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsmitglieder:"},{"type":"text","text":" Sind zur aktiven Teilnahme am Fraktions-RP sowie zur lückenlosen Einhaltung dieses Regelwerks verpflichtet. Fehlverhalten spiegelt sich immer auch auf die gesamte Fraktion wider."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§1 - Grundlagen & Begriffsdefinition' OR current_rule."category" IS DISTINCT FROM 'Fraktionsregelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', "category" = 'Fraktionsregelwerk', "title" = '§1 - Grundlagen & Begriffsdefinition', "order" = 1, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-faction-1-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§1.1 Begriffserklärung"}]},{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen: "},{"type":"text","text":"Hauptfraktionen sind die zentralen Organisationen des Servers, welche die Grundversorgung des Roleplays sicherstellen (z. B. Polizei, Feuerwehr, Rettungsdienst). Aufgrund ihrer tragenden Rolle für Sicherheit und Ordnung gelten für sie und ihre Mitglieder verschärfte Anforderungen an Aktivität, Serverpräsenz und vorbildliches Verhalten."}]},{"type":"paragraph","content":[{"type":"text","text":"Unterfraktionen: "},{"type":"text","text":"Unterfraktionen / Abteilungen sind eigegliederte Fraktionen die unter der Hauptfraktionen aggieren und unterstüzen, diese haben denoch eine eigene leitung."}]},{"type":"paragraph","content":[{"type":"text","text":"Legale Fraktionen: "},{"type":"text","text":"Diese Agieren als Firmen im Roleplay und verfolgen behördliche und wirtschaftliche Ziele."}]},{"type":"paragraph","content":[{"type":"text","text":"Illegale Fraktionen / Gangs: "},{"type":"text","text":"Sie sind auf Kriminelle Aktivitäten ausgelegt und agieren auserhalb des Gesetzes."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktions-Discords & Kompetenzen:"},{"type":"text","text":" Die übergeordnete Verwaltung aller Fraktionen obliegt dem Fraktionsmanagement und dem Project Manager / Ass.. Für alle offiziellen Fraktions-Discord-Server gilt:"}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM muss jederzeit vollen Lese- und Kontrollzugriff (mindestens Audit-Log-Einsicht) besitzen. Dh das FM "},{"type":"text","text":"MUSS "},{"type":"text","text":"in alle channels reinschauen können zur Kontrolle."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsleitungen dürfen ihren Mitgliedern "},{"type":"text","text":"keine administrativen Rechte"},{"type":"text","text":" (z. B. \"Server verwalten\", \"Rollen verwalten\", \"Administrator\") auf den Fraktions-Discords geben, um Missbrauch vorzubeugen. Admin-Rechte liegen exklusiv beim FM/Serverleitung."}]},{"type":"paragraph","content":[{"type":"text","text":"§1.2 Verantwortlichkeiten"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsleitung:"},{"type":"text","text":" Ist vollumfänglich für die interne Organisation, die Aktivitätskontrolle, das Fehlverhalten ihrer Mitglieder sowie die Durchsetzung des Regelwerks innerhalb der Fraktion verantwortlich."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsmanagement (FM):"},{"type":"text","text":" Überwacht die Fraktionslandschaft, agiert als neutrale Beschwerdestelle, greift bei Missständen ein und sorgt für ein faires Balancing im Gesamt-RP."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsmitglieder:"},{"type":"text","text":" Sind zur aktiven Teilnahme am Fraktions-RP sowie zur lückenlosen Einhaltung dieses Regelwerks verpflichtet. Fehlverhalten spiegelt sich immer auch auf die gesamte Fraktion wider."}]}]}'::jsonb, '§1 - Grundlagen & Begriffsdefinition §1.1 Begriffserklärung Hauptfraktionen: Hauptfraktionen sind die zentralen Organisationen des Servers, welche die Grundversorgung des Roleplays sicherstellen (z. B. Polizei, Feuerwehr, Rettungsdienst). Aufgrund ihrer tragenden Rolle für Sicherheit und Ordnung gelten für sie und ihre Mitglieder verschärfte Anforderungen an Aktivität, Serverpräsenz und vorbildliches Verhalten. Unterfraktionen: Unterfraktionen / Abteilungen sind eigegliederte Fraktionen die unter der Hauptfraktionen aggieren und unterstüzen, diese haben denoch eine eigene leitung. Legale Fraktionen: Diese Agieren als Firmen im Roleplay und verfolgen behördliche und wirtschaftliche Ziele. Illegale Fraktionen / Gangs: Sie sind auf Kriminelle Aktivitäten ausgelegt und agieren auserhalb des Gesetzes. Fraktions-Discords & Kompetenzen: Die übergeordnete Verwaltung aller Fraktionen obliegt dem Fraktionsmanagement und dem Project Manager / Ass.. Für alle offiziellen Fraktions-Discord-Server gilt: Das FM muss jederzeit vollen Lese- und Kontrollzugriff (mindestens Audit-Log-Einsicht) besitzen. Dh das FM MUSS in alle channels reinschauen können zur Kontrolle. Fraktionsleitungen dürfen ihren Mitgliedern keine administrativen Rechte (z. B. "Server verwalten", "Rollen verwalten", "Administrator") auf den Fraktions-Discords geben, um Missbrauch vorzubeugen. Admin-Rechte liegen exklusiv beim FM/Serverleitung. §1.2 Verantwortlichkeiten Fraktionsleitung: Ist vollumfänglich für die interne Organisation, die Aktivitätskontrolle, das Fehlverhalten ihrer Mitglieder sowie die Durchsetzung des Regelwerks innerhalb der Fraktion verantwortlich. Fraktionsmanagement (FM): Überwacht die Fraktionslandschaft, agiert als neutrale Beschwerdestelle, greift bei Missständen ein und sorgt für ein faires Balancing im Gesamt-RP. Fraktionsmitglieder: Sind zur aktiven Teilnahme am Fraktions-RP sowie zur lückenlosen Einhaltung dieses Regelwerks verpflichtet. Fehlverhalten spiegelt sich immer auch auf die gesamte Fraktion wider.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

