      ('rule-faction-2', 'faction-2', 'faction-2', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', 'Fraktionsregelwerk', '§2 - Gründungsverfahren / Warn-System / Auflösung', 2, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§2.1 Gründung"}]},{"type":"paragraph","content":[{"type":"text","text":"Bewerbungsphase:"},{"type":"text","text":" Eine Fraktion kann nur gegründet werden, wenn die Fraktionsbewerbungen offiziell geöffnet sind."}]},{"type":"paragraph","content":[{"type":"text","text":"Ticket-Erstellung:"},{"type":"text","text":" Zur Antragstellung muss auf dem offiziellen Discord-Server von "},{"type":"text","text":"Deutschland Roleplay (DRP)"},{"type":"text","text":" ein "},{"type":"text","text":"\"Fraktions-Ticket\""},{"type":"text","text":" eröffnet werden."}]},{"type":"paragraph","content":[{"type":"text","text":"RP-Mehrwert & Notwendigkeit:"},{"type":"text","text":" Jede Fraktion muss einen klaren Mehrwert für das Roleplay bieten. Hierzu zählen fortlaufende Aufgaben, ein aktives Konzept sowie ein erkennbarer Nutzen für den Server."}]},{"type":"paragraph","content":[{"type":"text","text":"Ablauf & Bearbeitung:"},{"type":"text","text":" Das Fraktionsmanagement (FM) begleitet euch durch den gesamten Prozess im Ticket und gibt dort die finale Entscheidung über Anahme oder Ablehnung bekannt."}]},{"type":"paragraph","content":[{"type":"text","text":"Testphase: "},{"type":"text","text":"Nach erfolgreicher Annahme hat die Jeweilige Fraktion eine 2 Wöchige Testphase diese beginnt sobald die Fraktion Offiziell Angekündigt wurde."}]},{"type":"paragraph","content":[{"type":"text","text":"§2.2 Warn-System / Auflösung"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Fraktionsmanagement (FM) behält sich das Recht vor, bei Regelverstößen Sanktionen gegen die jeweilige Fraktion auszusprechen. Alle Fälle werden individuell und situativ bewertet; es gibt keine starren Strafmaße."}]},{"type":"paragraph","content":[{"type":"text","text":"Warn Stufen:"}]},{"type":"paragraph","content":[{"type":"text","text":"Ermahnung: "},{"type":"text","text":"Wird bei leichten Vergehen ausgesprochen oder dient als deutlicher Hinweis darauf, dass das Verhalten der Fraktion angepasst werden muss."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktions Warn: "},{"type":"text","text":"Wird bei schwerwiegenden Verstößen verhängt. Bei Erreichen von "},{"type":"text","text":"3 Fraktions-Warns"},{"type":"text","text":" wird die Fraktion unverzüglich aufgelöst."}]},{"type":"paragraph","content":[{"type":"text","text":"Temporäre Sperrung: "},{"type":"text","text":"Bei Schwierigen Situationen wo die klärung länger dauert kann das FM die Fraktion Temporär das RP verbieten."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktions Auflösung: "},{"type":"text","text":"Führt zur sofortigen Einstellung aller Aktivitäten im Roleplay. Eine Auflösung erfolgt unter folgenden Bedingungen:"}]},{"type":"paragraph","content":[{"type":"text","text":"Erhalt eines Warns innerhalb der zweiwöchigen Testphase"}]},{"type":"paragraph","content":[{"type":"text","text":"Ansammlung von insgesamt 3 Fraktions-Warns"}]},{"type":"paragraph","content":[{"type":"text","text":"Begehung eines extrem schweren Regelbruchs"}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§2 - Gründungsverfahren / Warn-System / Auflösung' OR current_rule."category" IS DISTINCT FROM 'Fraktionsregelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', "category" = 'Fraktionsregelwerk', "title" = '§2 - Gründungsverfahren / Warn-System / Auflösung', "order" = 2, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-faction-2-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§2.1 Gründung"}]},{"type":"paragraph","content":[{"type":"text","text":"Bewerbungsphase:"},{"type":"text","text":" Eine Fraktion kann nur gegründet werden, wenn die Fraktionsbewerbungen offiziell geöffnet sind."}]},{"type":"paragraph","content":[{"type":"text","text":"Ticket-Erstellung:"},{"type":"text","text":" Zur Antragstellung muss auf dem offiziellen Discord-Server von "},{"type":"text","text":"Deutschland Roleplay (DRP)"},{"type":"text","text":" ein "},{"type":"text","text":"\"Fraktions-Ticket\""},{"type":"text","text":" eröffnet werden."}]},{"type":"paragraph","content":[{"type":"text","text":"RP-Mehrwert & Notwendigkeit:"},{"type":"text","text":" Jede Fraktion muss einen klaren Mehrwert für das Roleplay bieten. Hierzu zählen fortlaufende Aufgaben, ein aktives Konzept sowie ein erkennbarer Nutzen für den Server."}]},{"type":"paragraph","content":[{"type":"text","text":"Ablauf & Bearbeitung:"},{"type":"text","text":" Das Fraktionsmanagement (FM) begleitet euch durch den gesamten Prozess im Ticket und gibt dort die finale Entscheidung über Anahme oder Ablehnung bekannt."}]},{"type":"paragraph","content":[{"type":"text","text":"Testphase: "},{"type":"text","text":"Nach erfolgreicher Annahme hat die Jeweilige Fraktion eine 2 Wöchige Testphase diese beginnt sobald die Fraktion Offiziell Angekündigt wurde."}]},{"type":"paragraph","content":[{"type":"text","text":"§2.2 Warn-System / Auflösung"}]},{"type":"paragraph","content":[{"type":"text","text":"Das Fraktionsmanagement (FM) behält sich das Recht vor, bei Regelverstößen Sanktionen gegen die jeweilige Fraktion auszusprechen. Alle Fälle werden individuell und situativ bewertet; es gibt keine starren Strafmaße."}]},{"type":"paragraph","content":[{"type":"text","text":"Warn Stufen:"}]},{"type":"paragraph","content":[{"type":"text","text":"Ermahnung: "},{"type":"text","text":"Wird bei leichten Vergehen ausgesprochen oder dient als deutlicher Hinweis darauf, dass das Verhalten der Fraktion angepasst werden muss."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktions Warn: "},{"type":"text","text":"Wird bei schwerwiegenden Verstößen verhängt. Bei Erreichen von "},{"type":"text","text":"3 Fraktions-Warns"},{"type":"text","text":" wird die Fraktion unverzüglich aufgelöst."}]},{"type":"paragraph","content":[{"type":"text","text":"Temporäre Sperrung: "},{"type":"text","text":"Bei Schwierigen Situationen wo die klärung länger dauert kann das FM die Fraktion Temporär das RP verbieten."}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktions Auflösung: "},{"type":"text","text":"Führt zur sofortigen Einstellung aller Aktivitäten im Roleplay. Eine Auflösung erfolgt unter folgenden Bedingungen:"}]},{"type":"paragraph","content":[{"type":"text","text":"Erhalt eines Warns innerhalb der zweiwöchigen Testphase"}]},{"type":"paragraph","content":[{"type":"text","text":"Ansammlung von insgesamt 3 Fraktions-Warns"}]},{"type":"paragraph","content":[{"type":"text","text":"Begehung eines extrem schweren Regelbruchs"}]}]}'::jsonb, '§2 - Gründungsverfahren / Warn-System / Auflösung §2.1 Gründung Bewerbungsphase: Eine Fraktion kann nur gegründet werden, wenn die Fraktionsbewerbungen offiziell geöffnet sind. Ticket-Erstellung: Zur Antragstellung muss auf dem offiziellen Discord-Server von Deutschland Roleplay (DRP) ein "Fraktions-Ticket" eröffnet werden. RP-Mehrwert & Notwendigkeit: Jede Fraktion muss einen klaren Mehrwert für das Roleplay bieten. Hierzu zählen fortlaufende Aufgaben, ein aktives Konzept sowie ein erkennbarer Nutzen für den Server. Ablauf & Bearbeitung: Das Fraktionsmanagement (FM) begleitet euch durch den gesamten Prozess im Ticket und gibt dort die finale Entscheidung über Anahme oder Ablehnung bekannt. Testphase: Nach erfolgreicher Annahme hat die Jeweilige Fraktion eine 2 Wöchige Testphase diese beginnt sobald die Fraktion Offiziell Angekündigt wurde. §2.2 Warn-System / Auflösung Das Fraktionsmanagement (FM) behält sich das Recht vor, bei Regelverstößen Sanktionen gegen die jeweilige Fraktion auszusprechen. Alle Fälle werden individuell und situativ bewertet; es gibt keine starren Strafmaße. Warn Stufen: Ermahnung: Wird bei leichten Vergehen ausgesprochen oder dient als deutlicher Hinweis darauf, dass das Verhalten der Fraktion angepasst werden muss. Fraktions Warn: Wird bei schwerwiegenden Verstößen verhängt. Bei Erreichen von 3 Fraktions-Warns wird die Fraktion unverzüglich aufgelöst. Temporäre Sperrung: Bei Schwierigen Situationen wo die klärung länger dauert kann das FM die Fraktion Temporär das RP verbieten. Fraktions Auflösung: Führt zur sofortigen Einstellung aller Aktivitäten im Roleplay. Eine Auflösung erfolgt unter folgenden Bedingungen: Erhalt eines Warns innerhalb der zweiwöchigen Testphase Ansammlung von insgesamt 3 Fraktions-Warns Begehung eines extrem schweren Regelbruchs', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'faction-3';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-faction-3', 'faction-3', 'faction-3', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', 'Fraktionsregelwerk', '§3 - Verantwortungsstruktur & Moderation', 3, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§3.1 Eigenverantwortung der Fraktionen"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionen genießen administrative Autonomie und organisieren sich intern selbstständig."}]},{"type":"paragraph","content":[{"type":"text","text":"Interne Richtlinien:"},{"type":"text","text":" Eigene Fraktionsordnungen und Dienstvorschriften sind erlaubt, dürfen jedoch niemals das übergeordnete Serverregelwerk aushebeln."}]},{"type":"paragraph","content":[{"type":"text","text":"Dienstweg:"},{"type":"text","text":" Konflikte oder Probleme sind zwingend zuerst intern über die Fraktionsleitung zu klären, bevor das Fraktionsmanagement (FM) eingeschaltet wird."}]},{"type":"paragraph","content":[{"type":"text","text":"Meldepflicht:"},{"type":"text","text":" Schwere Verstöße (z. B. Korruption ohne Absprache, Fail-RP im großen Stil, Beleidigungen) müssen von der Leitung sofort an das FM gemeldet werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Discord- & Serverpflicht:"},{"type":"text","text":" Jedes Fraktionsmitglied muss sowohl auf dem "},{"type":"text","text":"Haupt-Discord des Servers"},{"type":"text","text":" als auch auf dem jeweiligen "},{"type":"text","text":"Fraktions-Discord"},{"type":"text","text":" registriert sein. Spieler ohne Discord-Präsenz dürfen nicht in der Fraktion verbleiben."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.2 Aufgaben des Fraktionsmanagements (FM)"}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM agiert als Aufsichtsbehörde und greift nach dem Prinzip „Sanktion als letztes Mittel“ ein."}]},{"type":"paragraph","content":[{"type":"text","text":"Aufgaben:"},{"type":"text","text":" Beratung der Leitungen, Überwachung der RP-Qualität und finale Schlichtung bei Konflikten "},{"type":"text","text":"zwischen"},{"type":"text","text":" verschiedenen Fraktionen."}]},{"type":"paragraph","content":[{"type":"text","text":"Sanktionsstufen bei Fehlverhalten:"},{"type":"text","text":"Mündliche/Schriftliche Verwarnung der Fraktion."},{"type":"text","text":"Temporäre Einschränkung von Fraktionsrechten (z. B. Beschränkung von Mitgliederzahlen, Sperre für bestimmte RP-Aktionen)."},{"type":"text","text":"Administrative Entlassung einzelner Mitglieder/Leiter."},{"type":"text","text":"Komplette Auflösung der Fraktion (Unfraktionierung)."}]},{"type":"paragraph","content":[{"type":"text","text":"Mündliche/Schriftliche Verwarnung der Fraktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Temporäre Einschränkung von Fraktionsrechten (z. B. Beschränkung von Mitgliederzahlen, Sperre für bestimmte RP-Aktionen)."}]},{"type":"paragraph","content":[{"type":"text","text":"Administrative Entlassung einzelner Mitglieder/Leiter."}]},{"type":"paragraph","content":[{"type":"text","text":"Komplette Auflösung der Fraktion (Unfraktionierung)."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.3 Fraktionsübergreifende Leitungsverbote"}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Person darf maximal "},{"type":"text","text":"eine"},{"type":"text","text":" Fraktion oder Gang als Leitung (Leader/Co-Leader) führen."}]},{"type":"paragraph","content":[{"type":"text","text":"Interessenkonflikte:"},{"type":"text","text":" Um Metagaming und unfaire Machtkonzentrationen zu verhindern, ist es Mitgliedern der Chefetage (High-Command) einer Hauptfraktion (z.B. Polizei-Leitung) untersagt, zeitgleich eine tragende Rolle (z. B. Ranghöherer, Planer) in einer illegalen Fraktion einzunehmen."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.4 Machtbalance"}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM behält sich das Recht vor, Fraktionsentscheidungen (z. B. ungerechtfertigte Massenentlassungen, unfaire Bündnisse oder Kriege) zu annullieren, wenn sie das Balancing des Servers gefährden. Kein Bündnis und keine Fraktion darf das Server-RP dauerhaft diktieren oder monopolisieren."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.5 Aktivitätslogs & Fristen"}]},{"type":"paragraph","content":[{"type":"text","text":"Jede Fraktion ist zur lückenlosen Führung eines Aktivitätslogs (nach Vorgabe des FM) verpflichtet."}]},{"type":"paragraph","content":[{"type":"text","text":"Abgabefrist:"},{"type":"text","text":" Wöchentlich bis "},{"type":"text","text":"Samstag um 20:00 Uhr"},{"type":"text","text":". Nachreichungen werden nicht akzeptiert und als \"nicht abgegeben\" gewertet."}]},{"type":"paragraph","content":[{"type":"text","text":"Inaktivitäts-Strafen:"},{"type":"text","text":"1 Woche unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Schriftlicher Hinweis an die Leitung."},{"type":"text","text":"2 Wochen unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Erteilung eines Fraktions-Strikes."},{"type":"text","text":"3 Strikes:"},{"type":"text","text":" Bei Erreichen des dritten Strikes wird die Fraktion automatisch aufgelöst oder die Leitung komplett ausgetauscht."}]},{"type":"paragraph","content":[{"type":"text","text":"1 Woche unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Schriftlicher Hinweis an die Leitung."}]},{"type":"paragraph","content":[{"type":"text","text":"2 Wochen unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Erteilung eines Fraktions-Strikes."}]},{"type":"paragraph","content":[{"type":"text","text":"3 Strikes:"},{"type":"text","text":" Bei Erreichen des dritten Strikes wird die Fraktion automatisch aufgelöst oder die Leitung komplett ausgetauscht."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§3 - Verantwortungsstruktur & Moderation' OR current_rule."category" IS DISTINCT FROM 'Fraktionsregelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', "category" = 'Fraktionsregelwerk', "title" = '§3 - Verantwortungsstruktur & Moderation', "order" = 3, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-faction-3-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§3.1 Eigenverantwortung der Fraktionen"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionen genießen administrative Autonomie und organisieren sich intern selbstständig."}]},{"type":"paragraph","content":[{"type":"text","text":"Interne Richtlinien:"},{"type":"text","text":" Eigene Fraktionsordnungen und Dienstvorschriften sind erlaubt, dürfen jedoch niemals das übergeordnete Serverregelwerk aushebeln."}]},{"type":"paragraph","content":[{"type":"text","text":"Dienstweg:"},{"type":"text","text":" Konflikte oder Probleme sind zwingend zuerst intern über die Fraktionsleitung zu klären, bevor das Fraktionsmanagement (FM) eingeschaltet wird."}]},{"type":"paragraph","content":[{"type":"text","text":"Meldepflicht:"},{"type":"text","text":" Schwere Verstöße (z. B. Korruption ohne Absprache, Fail-RP im großen Stil, Beleidigungen) müssen von der Leitung sofort an das FM gemeldet werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Discord- & Serverpflicht:"},{"type":"text","text":" Jedes Fraktionsmitglied muss sowohl auf dem "},{"type":"text","text":"Haupt-Discord des Servers"},{"type":"text","text":" als auch auf dem jeweiligen "},{"type":"text","text":"Fraktions-Discord"},{"type":"text","text":" registriert sein. Spieler ohne Discord-Präsenz dürfen nicht in der Fraktion verbleiben."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.2 Aufgaben des Fraktionsmanagements (FM)"}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM agiert als Aufsichtsbehörde und greift nach dem Prinzip „Sanktion als letztes Mittel“ ein."}]},{"type":"paragraph","content":[{"type":"text","text":"Aufgaben:"},{"type":"text","text":" Beratung der Leitungen, Überwachung der RP-Qualität und finale Schlichtung bei Konflikten "},{"type":"text","text":"zwischen"},{"type":"text","text":" verschiedenen Fraktionen."}]},{"type":"paragraph","content":[{"type":"text","text":"Sanktionsstufen bei Fehlverhalten:"},{"type":"text","text":"Mündliche/Schriftliche Verwarnung der Fraktion."},{"type":"text","text":"Temporäre Einschränkung von Fraktionsrechten (z. B. Beschränkung von Mitgliederzahlen, Sperre für bestimmte RP-Aktionen)."},{"type":"text","text":"Administrative Entlassung einzelner Mitglieder/Leiter."},{"type":"text","text":"Komplette Auflösung der Fraktion (Unfraktionierung)."}]},{"type":"paragraph","content":[{"type":"text","text":"Mündliche/Schriftliche Verwarnung der Fraktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Temporäre Einschränkung von Fraktionsrechten (z. B. Beschränkung von Mitgliederzahlen, Sperre für bestimmte RP-Aktionen)."}]},{"type":"paragraph","content":[{"type":"text","text":"Administrative Entlassung einzelner Mitglieder/Leiter."}]},{"type":"paragraph","content":[{"type":"text","text":"Komplette Auflösung der Fraktion (Unfraktionierung)."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.3 Fraktionsübergreifende Leitungsverbote"}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Person darf maximal "},{"type":"text","text":"eine"},{"type":"text","text":" Fraktion oder Gang als Leitung (Leader/Co-Leader) führen."}]},{"type":"paragraph","content":[{"type":"text","text":"Interessenkonflikte:"},{"type":"text","text":" Um Metagaming und unfaire Machtkonzentrationen zu verhindern, ist es Mitgliedern der Chefetage (High-Command) einer Hauptfraktion (z.B. Polizei-Leitung) untersagt, zeitgleich eine tragende Rolle (z. B. Ranghöherer, Planer) in einer illegalen Fraktion einzunehmen."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.4 Machtbalance"}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM behält sich das Recht vor, Fraktionsentscheidungen (z. B. ungerechtfertigte Massenentlassungen, unfaire Bündnisse oder Kriege) zu annullieren, wenn sie das Balancing des Servers gefährden. Kein Bündnis und keine Fraktion darf das Server-RP dauerhaft diktieren oder monopolisieren."}]},{"type":"paragraph","content":[{"type":"text","text":"§3.5 Aktivitätslogs & Fristen"}]},{"type":"paragraph","content":[{"type":"text","text":"Jede Fraktion ist zur lückenlosen Führung eines Aktivitätslogs (nach Vorgabe des FM) verpflichtet."}]},{"type":"paragraph","content":[{"type":"text","text":"Abgabefrist:"},{"type":"text","text":" Wöchentlich bis "},{"type":"text","text":"Samstag um 20:00 Uhr"},{"type":"text","text":". Nachreichungen werden nicht akzeptiert und als \"nicht abgegeben\" gewertet."}]},{"type":"paragraph","content":[{"type":"text","text":"Inaktivitäts-Strafen:"},{"type":"text","text":"1 Woche unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Schriftlicher Hinweis an die Leitung."},{"type":"text","text":"2 Wochen unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Erteilung eines Fraktions-Strikes."},{"type":"text","text":"3 Strikes:"},{"type":"text","text":" Bei Erreichen des dritten Strikes wird die Fraktion automatisch aufgelöst oder die Leitung komplett ausgetauscht."}]},{"type":"paragraph","content":[{"type":"text","text":"1 Woche unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Schriftlicher Hinweis an die Leitung."}]},{"type":"paragraph","content":[{"type":"text","text":"2 Wochen unentschuldigt inaktiv / kein Log:"},{"type":"text","text":" Erteilung eines Fraktions-Strikes."}]},{"type":"paragraph","content":[{"type":"text","text":"3 Strikes:"},{"type":"text","text":" Bei Erreichen des dritten Strikes wird die Fraktion automatisch aufgelöst oder die Leitung komplett ausgetauscht."}]}]}'::jsonb, '§3 - Verantwortungsstruktur & Moderation §3.1 Eigenverantwortung der Fraktionen Fraktionen genießen administrative Autonomie und organisieren sich intern selbstständig. Interne Richtlinien: Eigene Fraktionsordnungen und Dienstvorschriften sind erlaubt, dürfen jedoch niemals das übergeordnete Serverregelwerk aushebeln. Dienstweg: Konflikte oder Probleme sind zwingend zuerst intern über die Fraktionsleitung zu klären, bevor das Fraktionsmanagement (FM) eingeschaltet wird. Meldepflicht: Schwere Verstöße (z. B. Korruption ohne Absprache, Fail-RP im großen Stil, Beleidigungen) müssen von der Leitung sofort an das FM gemeldet werden. Discord- & Serverpflicht: Jedes Fraktionsmitglied muss sowohl auf dem Haupt-Discord des Servers als auch auf dem jeweiligen Fraktions-Discord registriert sein. Spieler ohne Discord-Präsenz dürfen nicht in der Fraktion verbleiben. §3.2 Aufgaben des Fraktionsmanagements (FM) Das FM agiert als Aufsichtsbehörde und greift nach dem Prinzip „Sanktion als letztes Mittel“ ein. Aufgaben: Beratung der Leitungen, Überwachung der RP-Qualität und finale Schlichtung bei Konflikten zwischen verschiedenen Fraktionen. Sanktionsstufen bei Fehlverhalten: Mündliche/Schriftliche Verwarnung der Fraktion. Temporäre Einschränkung von Fraktionsrechten (z. B. Beschränkung von Mitgliederzahlen, Sperre für bestimmte RP-Aktionen). Administrative Entlassung einzelner Mitglieder/Leiter. Komplette Auflösung der Fraktion (Unfraktionierung). Mündliche/Schriftliche Verwarnung der Fraktion. Temporäre Einschränkung von Fraktionsrechten (z. B. Beschränkung von Mitgliederzahlen, Sperre für bestimmte RP-Aktionen). Administrative Entlassung einzelner Mitglieder/Leiter. Komplette Auflösung der Fraktion (Unfraktionierung). §3.3 Fraktionsübergreifende Leitungsverbote Eine Person darf maximal eine Fraktion oder Gang als Leitung (Leader/Co-Leader) führen. Interessenkonflikte: Um Metagaming und unfaire Machtkonzentrationen zu verhindern, ist es Mitgliedern der Chefetage (High-Command) einer Hauptfraktion (z.B. Polizei-Leitung) untersagt, zeitgleich eine tragende Rolle (z. B. Ranghöherer, Planer) in einer illegalen Fraktion einzunehmen. §3.4 Machtbalance Das FM behält sich das Recht vor, Fraktionsentscheidungen (z. B. ungerechtfertigte Massenentlassungen, unfaire Bündnisse oder Kriege) zu annullieren, wenn sie das Balancing des Servers gefährden. Kein Bündnis und keine Fraktion darf das Server-RP dauerhaft diktieren oder monopolisieren. §3.5 Aktivitätslogs & Fristen Jede Fraktion ist zur lückenlosen Führung eines Aktivitätslogs (nach Vorgabe des FM) verpflichtet. Abgabefrist: Wöchentlich bis Samstag um 20:00 Uhr . Nachreichungen werden nicht akzeptiert und als "nicht abgegeben" gewertet. Inaktivitäts-Strafen: 1 Woche unentschuldigt inaktiv / kein Log: Schriftlicher Hinweis an die Leitung. 2 Wochen unentschuldigt inaktiv / kein Log: Erteilung eines Fraktions-Strikes. 3 Strikes: Bei Erreichen des dritten Strikes wird die Fraktion automatisch aufgelöst oder die Leitung komplett ausgetauscht. 1 Woche unentschuldigt inaktiv / kein Log: Schriftlicher Hinweis an die Leitung. 2 Wochen unentschuldigt inaktiv / kein Log: Erteilung eines Fraktions-Strikes. 3 Strikes: Bei Erreichen des dritten Strikes wird die Fraktion automatisch aufgelöst oder die Leitung komplett ausgetauscht.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'faction-4';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-faction-4', 'faction-4', 'faction-4', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', 'Fraktionsregelwerk', '§4 – Organisation & Technische Sicherheit', 4, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§4.1 Discord-Sicherheit & Bot-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"Um die Sicherheit der Community vor Raids, Datenklau oder schadhaften Verlinkungen zu schützen, gelten für alle Fraktions-Discords strenge Sicherheitsauflagen."}]},{"type":"paragraph","content":[{"type":"text","text":"Zugelassene Bots:"},{"type":"text","text":" Es dürfen ausschließlich weltweit bekannte, verifizierte und vom Fraktionsmanagement freigegebene Bots (z. B. Ticket-Bots, Musik-Bots) genutzt werden. Unverifizierte oder dubiose Public-Bots sind strengstens untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Verbot von Fremd-Custom-Bots:"},{"type":"text","text":" Das Einladen von selbstprogrammierten Bots von Drittanbietern ist verboten. Ausgenommen sind lediglich offizielle Custom-Bots der Serverleitung."}]},{"type":"paragraph","content":[{"type":"text","text":"Verpflichtender Raid-Schutz:"},{"type":"text","text":" Jeder Fraktions-Discord muss zwingend über einen voll eingerichteten und aktiven Wick-Bot verfügen."}]},{"type":"paragraph","content":[{"type":"text","text":"Ablauf der Genehmigung:"},{"type":"text","text":" Eine Fraktion darf ihren Discord erst nach der offiziellen Zusage des FM erstellen. Nach der Erstellung hat die Leitung "},{"type":"text","text":"24 Stunden Zeit"},{"type":"text","text":", den Sicherheits-Bot (Wick) vollständig einzurichten und dem FM den Kontrollzugriff zu gewähren. Erst nach erfolgreicher technischer Abnahme durch das FM wird die Fraktion für den Spielbetrieb freigegeben."}]},{"type":"paragraph","content":[{"type":"text","text":"Rechte-Minimierung:"},{"type":"text","text":" Kein Bot (außer der verifizierte Sicherheits-Bot) darf über administrative Rechte ("},{"type":"text","text":"Administrator"},{"type":"text","text":") verfügen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§4 – Organisation & Technische Sicherheit' OR current_rule."category" IS DISTINCT FROM 'Fraktionsregelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', "category" = 'Fraktionsregelwerk', "title" = '§4 – Organisation & Technische Sicherheit', "order" = 4, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-faction-4-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"§4.1 Discord-Sicherheit & Bot-Richtlinien"}]},{"type":"paragraph","content":[{"type":"text","text":"Um die Sicherheit der Community vor Raids, Datenklau oder schadhaften Verlinkungen zu schützen, gelten für alle Fraktions-Discords strenge Sicherheitsauflagen."}]},{"type":"paragraph","content":[{"type":"text","text":"Zugelassene Bots:"},{"type":"text","text":" Es dürfen ausschließlich weltweit bekannte, verifizierte und vom Fraktionsmanagement freigegebene Bots (z. B. Ticket-Bots, Musik-Bots) genutzt werden. Unverifizierte oder dubiose Public-Bots sind strengstens untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Verbot von Fremd-Custom-Bots:"},{"type":"text","text":" Das Einladen von selbstprogrammierten Bots von Drittanbietern ist verboten. Ausgenommen sind lediglich offizielle Custom-Bots der Serverleitung."}]},{"type":"paragraph","content":[{"type":"text","text":"Verpflichtender Raid-Schutz:"},{"type":"text","text":" Jeder Fraktions-Discord muss zwingend über einen voll eingerichteten und aktiven Wick-Bot verfügen."}]},{"type":"paragraph","content":[{"type":"text","text":"Ablauf der Genehmigung:"},{"type":"text","text":" Eine Fraktion darf ihren Discord erst nach der offiziellen Zusage des FM erstellen. Nach der Erstellung hat die Leitung "},{"type":"text","text":"24 Stunden Zeit"},{"type":"text","text":", den Sicherheits-Bot (Wick) vollständig einzurichten und dem FM den Kontrollzugriff zu gewähren. Erst nach erfolgreicher technischer Abnahme durch das FM wird die Fraktion für den Spielbetrieb freigegeben."}]},{"type":"paragraph","content":[{"type":"text","text":"Rechte-Minimierung:"},{"type":"text","text":" Kein Bot (außer der verifizierte Sicherheits-Bot) darf über administrative Rechte ("},{"type":"text","text":"Administrator"},{"type":"text","text":") verfügen."}]}]}'::jsonb, '§4 – Organisation & Technische Sicherheit §4.1 Discord-Sicherheit & Bot-Richtlinien Um die Sicherheit der Community vor Raids, Datenklau oder schadhaften Verlinkungen zu schützen, gelten für alle Fraktions-Discords strenge Sicherheitsauflagen. Zugelassene Bots: Es dürfen ausschließlich weltweit bekannte, verifizierte und vom Fraktionsmanagement freigegebene Bots (z. B. Ticket-Bots, Musik-Bots) genutzt werden. Unverifizierte oder dubiose Public-Bots sind strengstens untersagt. Verbot von Fremd-Custom-Bots: Das Einladen von selbstprogrammierten Bots von Drittanbietern ist verboten. Ausgenommen sind lediglich offizielle Custom-Bots der Serverleitung. Verpflichtender Raid-Schutz: Jeder Fraktions-Discord muss zwingend über einen voll eingerichteten und aktiven Wick-Bot verfügen. Ablauf der Genehmigung: Eine Fraktion darf ihren Discord erst nach der offiziellen Zusage des FM erstellen. Nach der Erstellung hat die Leitung 24 Stunden Zeit , den Sicherheits-Bot (Wick) vollständig einzurichten und dem FM den Kontrollzugriff zu gewähren. Erst nach erfolgreicher technischer Abnahme durch das FM wird die Fraktion für den Spielbetrieb freigegeben. Rechte-Minimierung: Kein Bot (außer der verifizierte Sicherheits-Bot) darf über administrative Rechte ( Administrator ) verfügen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'faction-5';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-faction-5', 'faction-5', 'faction-5', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', 'Fraktionsregelwerk', '§5 – Rechte und Pflichten der Fraktionsmitglieder', 5, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mitglieder einer Fraktion tragen Verantwortung, genießen aber auch Privilegien. Dieser Abschnitt regelt, was ihnen zusteht – und wofür sie im Gegenzug einstehen müssen. Nur durch ein Gleichgewicht zwischen Rechten und Pflichten kann ein fairer und lebendiger Fraktionsalltag entstehen."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§5.1 – Rechte der Mitglieder"}]},{"type":"paragraph","content":[{"type":"text","text":"Teilnahme am Rollenspiel:"},{"type":"hardBreak"},{"type":"text","text":" Jedes Mitglied hat das grundsätzliche Recht, aktiv am RP teilzunehmen. Dabei sollen alle die Möglichkeit haben, sich mit eigenen Ideen und Charakterzügen in die Fraktion einzubringen. Kreativität und Engagement sind ausdrücklich erwünscht."}]},{"type":"paragraph","content":[{"type":"text","text":"Zugriff auf Ressourcen:"},{"type":"hardBreak"},{"type":"text","text":" Mitglieder erhalten Zugang zu den für die Fraktion vorgesehenen Ressourcen – darunter Fahrzeuge, Ausrüstung und ggf. spezielle Discord-Channels oder Tools. Der Umfang dieses Zugriffs orientiert sich dabei an der jeweiligen Rolle und dem Rang innerhalb der Fraktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Mitspracherecht:"},{"type":"hardBreak"},{"type":"text","text":" Die Meinung jedes Mitglieds zählt. Je nach Hierarchiestufe besteht ein Mitspracherecht bei fraktionsinternen Entscheidungen – ob bei der Planung von Einsätzen, internen Umstrukturierungen oder Regelanpassungen."},{"type":"hardBreak"},{"type":"text","text":" In Hauptfraktionen sowie auf Bundesebene gilt außerdem: Auch bei Nebenfraktionen kann in bestimmten Fällen ein Mitspracherecht bestehen, sofern dies die Struktur oder das Zusammenspiel im RP betrifft."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§5.2 – Pflichten der Mitglieder"}]},{"type":"paragraph","content":[{"type":"text","text":"Einhaltung aller Regeln:"},{"type":"hardBreak"},{"type":"text","text":" Jedes Mitglied ist verpflichtet, sich an die geltenden Fraktionsregeln sowie an die allgemeinen Serverregeln zu halten. Das umfasst sowohl RP-relevante Inhalte als auch den respektvollen Umgang miteinander – auf dem Server und im Discord. Für dem Team auch das Team Regelwerk."}]},{"type":"paragraph","content":[{"type":"text","text":"Teilnahme an Schulungen:"},{"type":"hardBreak"},{"type":"text","text":" Für Mitglieder der Hauptfraktionen besteht die Pflicht, regelmäßig an Schulungen teilzunehmen. Diese fördern nicht nur die RP-Qualität, sondern sind auch Voraussetzung für Beförderungen oder Spezialisierungen innerhalb der Fraktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Loyalität gegenüber der Fraktion:"},{"type":"hardBreak"},{"type":"text","text":" Mitglieder sollten sich mit ihrer Fraktion identifizieren und deren Werte vertreten. Ein fairer, engagierter und verantwortungsvoller Umgang mit den Aufgaben und Mitspielern stärkt nicht nur das Miteinander, sondern auch das Ansehen der Fraktion im Servergeschehen."}]},{"type":"paragraph","content":[{"type":"text","text":"Respektvolles Verhalten:"},{"type":"hardBreak"},{"type":"text","text":" Egal ob im RP oder im OOC-Bereich – ein höflicher und respektvoller Umgang ist Pflicht. Beleidigungen, Diskriminierung oder toxisches Verhalten haben in einer funktionierenden Fraktion keinen Platz. Auch bei Konflikten ist der ruhige Dialog stets der erste Weg."}]},{"type":"paragraph","content":[{"type":"text","text":"Neutralität medizinischer Fraktionen:"},{"type":"hardBreak"},{"type":"text","text":" Fraktionen wie das DRK oder andere medizinische Dienste haben eine besondere Verantwortung: Sie müssen im RP neutral agieren und dürfen sich nicht in politische oder kriminelle Strukturen einmischen. Bevorzugung einzelner Fraktionen ist untersagt – medizinische Hilfe gilt allen gleichermaßen."}]},{"type":"paragraph","content":[{"type":"text","text":"Teilnahme am Roleplay"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsbesitzer sowie sämtliche Mitglieder einer Fraktion sind verpflichtet, aktiv am Roleplay teilzunehmen und regelmäßig ingame Aktivität zu zeigen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Fraktion soll das Server-RP aktiv bereichern und darf nicht lediglich auf dem Papier existieren. Dazu gehört insbesondere die Teilnahme an Einsätzen, Situationen, internen Abläufen sowie allgemeinen RP-Handlungen im Alltag des Servers."}]},{"type":"paragraph","content":[{"type":"text","text":"Dauerhafte Inaktivität, fehlende Beteiligung am Roleplay oder das bloße Besitzen einer Fraktion ohne erkennbare Aktivität widersprechen dem Zweck einer Fraktion und können durch das Fraktionsmanagement überprüft sowie entsprechend sanktioniert werden."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§5 – Rechte und Pflichten der Fraktionsmitglieder' OR current_rule."category" IS DISTINCT FROM 'Fraktionsregelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', "category" = 'Fraktionsregelwerk', "title" = '§5 – Rechte und Pflichten der Fraktionsmitglieder', "order" = 5, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-faction-5-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mitglieder einer Fraktion tragen Verantwortung, genießen aber auch Privilegien. Dieser Abschnitt regelt, was ihnen zusteht – und wofür sie im Gegenzug einstehen müssen. Nur durch ein Gleichgewicht zwischen Rechten und Pflichten kann ein fairer und lebendiger Fraktionsalltag entstehen."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§5.1 – Rechte der Mitglieder"}]},{"type":"paragraph","content":[{"type":"text","text":"Teilnahme am Rollenspiel:"},{"type":"hardBreak"},{"type":"text","text":" Jedes Mitglied hat das grundsätzliche Recht, aktiv am RP teilzunehmen. Dabei sollen alle die Möglichkeit haben, sich mit eigenen Ideen und Charakterzügen in die Fraktion einzubringen. Kreativität und Engagement sind ausdrücklich erwünscht."}]},{"type":"paragraph","content":[{"type":"text","text":"Zugriff auf Ressourcen:"},{"type":"hardBreak"},{"type":"text","text":" Mitglieder erhalten Zugang zu den für die Fraktion vorgesehenen Ressourcen – darunter Fahrzeuge, Ausrüstung und ggf. spezielle Discord-Channels oder Tools. Der Umfang dieses Zugriffs orientiert sich dabei an der jeweiligen Rolle und dem Rang innerhalb der Fraktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Mitspracherecht:"},{"type":"hardBreak"},{"type":"text","text":" Die Meinung jedes Mitglieds zählt. Je nach Hierarchiestufe besteht ein Mitspracherecht bei fraktionsinternen Entscheidungen – ob bei der Planung von Einsätzen, internen Umstrukturierungen oder Regelanpassungen."},{"type":"hardBreak"},{"type":"text","text":" In Hauptfraktionen sowie auf Bundesebene gilt außerdem: Auch bei Nebenfraktionen kann in bestimmten Fällen ein Mitspracherecht bestehen, sofern dies die Struktur oder das Zusammenspiel im RP betrifft."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§5.2 – Pflichten der Mitglieder"}]},{"type":"paragraph","content":[{"type":"text","text":"Einhaltung aller Regeln:"},{"type":"hardBreak"},{"type":"text","text":" Jedes Mitglied ist verpflichtet, sich an die geltenden Fraktionsregeln sowie an die allgemeinen Serverregeln zu halten. Das umfasst sowohl RP-relevante Inhalte als auch den respektvollen Umgang miteinander – auf dem Server und im Discord. Für dem Team auch das Team Regelwerk."}]},{"type":"paragraph","content":[{"type":"text","text":"Teilnahme an Schulungen:"},{"type":"hardBreak"},{"type":"text","text":" Für Mitglieder der Hauptfraktionen besteht die Pflicht, regelmäßig an Schulungen teilzunehmen. Diese fördern nicht nur die RP-Qualität, sondern sind auch Voraussetzung für Beförderungen oder Spezialisierungen innerhalb der Fraktion."}]},{"type":"paragraph","content":[{"type":"text","text":"Loyalität gegenüber der Fraktion:"},{"type":"hardBreak"},{"type":"text","text":" Mitglieder sollten sich mit ihrer Fraktion identifizieren und deren Werte vertreten. Ein fairer, engagierter und verantwortungsvoller Umgang mit den Aufgaben und Mitspielern stärkt nicht nur das Miteinander, sondern auch das Ansehen der Fraktion im Servergeschehen."}]},{"type":"paragraph","content":[{"type":"text","text":"Respektvolles Verhalten:"},{"type":"hardBreak"},{"type":"text","text":" Egal ob im RP oder im OOC-Bereich – ein höflicher und respektvoller Umgang ist Pflicht. Beleidigungen, Diskriminierung oder toxisches Verhalten haben in einer funktionierenden Fraktion keinen Platz. Auch bei Konflikten ist der ruhige Dialog stets der erste Weg."}]},{"type":"paragraph","content":[{"type":"text","text":"Neutralität medizinischer Fraktionen:"},{"type":"hardBreak"},{"type":"text","text":" Fraktionen wie das DRK oder andere medizinische Dienste haben eine besondere Verantwortung: Sie müssen im RP neutral agieren und dürfen sich nicht in politische oder kriminelle Strukturen einmischen. Bevorzugung einzelner Fraktionen ist untersagt – medizinische Hilfe gilt allen gleichermaßen."}]},{"type":"paragraph","content":[{"type":"text","text":"Teilnahme am Roleplay"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktionsbesitzer sowie sämtliche Mitglieder einer Fraktion sind verpflichtet, aktiv am Roleplay teilzunehmen und regelmäßig ingame Aktivität zu zeigen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Fraktion soll das Server-RP aktiv bereichern und darf nicht lediglich auf dem Papier existieren. Dazu gehört insbesondere die Teilnahme an Einsätzen, Situationen, internen Abläufen sowie allgemeinen RP-Handlungen im Alltag des Servers."}]},{"type":"paragraph","content":[{"type":"text","text":"Dauerhafte Inaktivität, fehlende Beteiligung am Roleplay oder das bloße Besitzen einer Fraktion ohne erkennbare Aktivität widersprechen dem Zweck einer Fraktion und können durch das Fraktionsmanagement überprüft sowie entsprechend sanktioniert werden."}]}]}'::jsonb, '§5 – Rechte und Pflichten der Fraktionsmitglieder Mitglieder einer Fraktion tragen Verantwortung, genießen aber auch Privilegien. Dieser Abschnitt regelt, was ihnen zusteht – und wofür sie im Gegenzug einstehen müssen. Nur durch ein Gleichgewicht zwischen Rechten und Pflichten kann ein fairer und lebendiger Fraktionsalltag entstehen. §5.1 – Rechte der Mitglieder Teilnahme am Rollenspiel: Jedes Mitglied hat das grundsätzliche Recht, aktiv am RP teilzunehmen. Dabei sollen alle die Möglichkeit haben, sich mit eigenen Ideen und Charakterzügen in die Fraktion einzubringen. Kreativität und Engagement sind ausdrücklich erwünscht. Zugriff auf Ressourcen: Mitglieder erhalten Zugang zu den für die Fraktion vorgesehenen Ressourcen – darunter Fahrzeuge, Ausrüstung und ggf. spezielle Discord-Channels oder Tools. Der Umfang dieses Zugriffs orientiert sich dabei an der jeweiligen Rolle und dem Rang innerhalb der Fraktion. Mitspracherecht: Die Meinung jedes Mitglieds zählt. Je nach Hierarchiestufe besteht ein Mitspracherecht bei fraktionsinternen Entscheidungen – ob bei der Planung von Einsätzen, internen Umstrukturierungen oder Regelanpassungen. In Hauptfraktionen sowie auf Bundesebene gilt außerdem: Auch bei Nebenfraktionen kann in bestimmten Fällen ein Mitspracherecht bestehen, sofern dies die Struktur oder das Zusammenspiel im RP betrifft. §5.2 – Pflichten der Mitglieder Einhaltung aller Regeln: Jedes Mitglied ist verpflichtet, sich an die geltenden Fraktionsregeln sowie an die allgemeinen Serverregeln zu halten. Das umfasst sowohl RP-relevante Inhalte als auch den respektvollen Umgang miteinander – auf dem Server und im Discord. Für dem Team auch das Team Regelwerk. Teilnahme an Schulungen: Für Mitglieder der Hauptfraktionen besteht die Pflicht, regelmäßig an Schulungen teilzunehmen. Diese fördern nicht nur die RP-Qualität, sondern sind auch Voraussetzung für Beförderungen oder Spezialisierungen innerhalb der Fraktion. Loyalität gegenüber der Fraktion: Mitglieder sollten sich mit ihrer Fraktion identifizieren und deren Werte vertreten. Ein fairer, engagierter und verantwortungsvoller Umgang mit den Aufgaben und Mitspielern stärkt nicht nur das Miteinander, sondern auch das Ansehen der Fraktion im Servergeschehen. Respektvolles Verhalten: Egal ob im RP oder im OOC-Bereich – ein höflicher und respektvoller Umgang ist Pflicht. Beleidigungen, Diskriminierung oder toxisches Verhalten haben in einer funktionierenden Fraktion keinen Platz. Auch bei Konflikten ist der ruhige Dialog stets der erste Weg. Neutralität medizinischer Fraktionen: Fraktionen wie das DRK oder andere medizinische Dienste haben eine besondere Verantwortung: Sie müssen im RP neutral agieren und dürfen sich nicht in politische oder kriminelle Strukturen einmischen. Bevorzugung einzelner Fraktionen ist untersagt – medizinische Hilfe gilt allen gleichermaßen. Teilnahme am Roleplay Fraktionsbesitzer sowie sämtliche Mitglieder einer Fraktion sind verpflichtet, aktiv am Roleplay teilzunehmen und regelmäßig ingame Aktivität zu zeigen. Eine Fraktion soll das Server-RP aktiv bereichern und darf nicht lediglich auf dem Papier existieren. Dazu gehört insbesondere die Teilnahme an Einsätzen, Situationen, internen Abläufen sowie allgemeinen RP-Handlungen im Alltag des Servers. Dauerhafte Inaktivität, fehlende Beteiligung am Roleplay oder das bloße Besitzen einer Fraktion ohne erkennbare Aktivität widersprechen dem Zweck einer Fraktion und können durch das Fraktionsmanagement überprüft sowie entsprechend sanktioniert werden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'faction-6';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-faction-6', 'faction-6', 'faction-6', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', 'Fraktionsregelwerk', '§6 Blacklist', 6, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Als "},{"type":"text","text":"„Blacklisted Fraktionen“"},{"type":"text","text":" gelten Fraktionen, deren Existenz, Ausrichtung oder Aktivitäten in direktem Widerspruch zu geltendem Recht, den RP-Serverregeln oder ethischen Standards stehen. Eine Blacklistung bedeutet ein vollständiges Verbot dieser Fraktionen auf dem Server. Jegliche Neugründung, Darstellung oder Bezugnahme auf diese Gruppen ist untersagt."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.1 Gründe für eine Blacklistung"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Gründe für eine Aufnahme auf die Blacklist umfassen unter anderem:"}]},{"type":"paragraph","content":[{"type":"text","text":"Illegale Aktivitäten:"},{"type":"text","text":" Beteiligung an oder Verherrlichung von kriminellen Handlungen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Hasspropaganda:"},{"type":"text","text":" Diskriminierung, Hetze oder gezielte Ausgrenzung von Personen(gruppen)."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Gewaltverherrlichung:"},{"type":"text","text":" Darstellung oder Befürwortung von Gewalt, Terrorismus oder radikalen Aktionen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Störung des Spielbetriebs:"},{"type":"text","text":" Dauerhafte Beeinträchtigung des Roleplay-Erlebnisses anderer Spieler durch unangemessenes Verhalten oder Konzept."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Wiederholte Regelverstöße:"},{"type":"text","text":" Anhaltende oder schwerwiegende Verstöße gegen Server- oder Fraktionsrichtlinien."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Geringer RP-Wert:"},{"type":"text","text":" Fraktionen, die keinen sinnvollen Beitrag zum RP leisten oder sich nicht in das Gesamtbild einfügen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mehrfache Ablehnung durch das Fraktionsmanagement:"},{"type":"text","text":" Bei wiederholt eingereichten und abgelehnten Konzepten."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.2 Allgemein verbotene Fraktionstypen"}]},{"type":"paragraph","content":[{"type":"text","text":"Die folgenden Fraktionstypen sind serverweit dauerhaft verboten:"}]},{"type":"paragraph","content":[{"type":"text","text":"Reale illegale Organisationen:"},{"type":"text","text":" z. B. Drogenkartelle (Sinaloa-Kartell), Terrororganisationen (IS, Al-Qaida), mafiöse Strukturen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Anti-Terror- und Drogen-Sondereinheiten (Realbezug):"},{"type":"text","text":" Aufgrund der realpolitischen Sensibilität, fehlender RP-Balance und häufiger Missbrauch dieser Fraktionen für Macht-RP."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.3 Konkrete Blacklistete Fraktionen (inkl. Begründung)"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktion"}]},{"type":"paragraph","content":[{"type":"text","text":"Grund für die Blacklistung"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Reale Gang´s"},{"type":"hardBreak"},{"type":"text","text":"Da DRP, keine echten Gangs und somit auch deren Gewalten fördern möchte."}]},{"type":"paragraph","content":[{"type":"text","text":"Bundes POL"}]},{"type":"paragraph","content":[{"type":"text","text":"Keinen Nutzen"}]},{"type":"paragraph","content":[{"type":"text","text":"Wasserpolizei"}]},{"type":"paragraph","content":[{"type":"text","text":"Kann nicht ausgespielt werden"}]},{"type":"paragraph","content":[{"type":"text","text":"Bundeswehr"}]},{"type":"paragraph","content":[{"type":"text","text":"Mehrere Regelverstöße und keinen Mehrwert."}]},{"type":"paragraph","content":[{"type":"text","text":"Kommando Delta (Delta D)"},{"type":"hardBreak"},{"type":"text","text":"Wiederholte Regelverstöße, kein ernsthaftes RP, Störung des Spielbetriebs, Gambo Truppe"}]},{"type":"paragraph","content":[{"type":"text","text":"Geheimdienste"},{"type":"hardBreak"},{"type":"text","text":"Zu geringe Relevanz im RP-Alltag, fehlender Spielmehrwert, wiederholt ohne Erfolg beantragt – kein erkennbarer RP-Nutzen."}]},{"type":"paragraph","content":[{"type":"text","text":"DLRG"}]},{"type":"paragraph","content":[{"type":"text","text":"Zu geringe Relevanz im RP-Alltag, kaum Spielbeteiligung, mehrfach ohne Erfolg beantragt, kein RP-Nutzen."}]},{"type":"paragraph","content":[{"type":"text","text":"Verfassungsschutz"}]},{"type":"paragraph","content":[{"type":"text","text":"Kein RP-Nutzen ohne tiefgreifende Sicherheitsmechanik."}]},{"type":"paragraph","content":[{"type":"text","text":"GSG9 / MEK"}]},{"type":"paragraph","content":[{"type":"text","text":"Unnötige Spezialeinheit + zu viel Gambo"}]},{"type":"paragraph","content":[{"type":"text","text":"Anti-Gang-Force / Anti-Tuning-Taskforce / Anti-RP-Crime-Unit"},{"type":"hardBreak"},{"type":"text","text":"Aufgaben gehören zur normalen Polizei, Reines Power-RP, Künstliche Rechtfertigung für Sonderrechte"}]},{"type":"paragraph","content":[{"type":"text","text":"BKA / LKA"},{"type":"hardBreak"},{"type":"text","text":"Unnötig und hat viele probleme gemacht"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Forstamt"},{"type":"hardBreak"},{"type":"text","text":"Keine richtigen aufgaben"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Fahrschule"},{"type":"hardBreak"},{"type":"text","text":"Da sie keinen nutzen hat"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Mehrfach-Fraktionen mit gleichem Zweck (zb 2 Feuerwehr, 2 Rettungsdienste)"}]},{"type":"paragraph","content":[{"type":"text","text":"Spaltet Spieler, Führt zu Unterbesetzung, Keine spielerischen Vorteile"}]},{"type":"paragraph","content":[{"type":"text","text":"Zentrale Unterstüzungsgruppe Zoll"}]},{"type":"paragraph","content":[{"type":"text","text":"unnötig da das SEK Exsistiert."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Zoll"},{"type":"hardBreak"},{"type":"text","text":"Unnötig, in ERLC keinen Zweck"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Regierung / Ämter / Bundesregierung"},{"type":"hardBreak"},{"type":"text","text":"Unnötig, zu viel macht, nicht ausspielbar."}]},{"type":"paragraph","content":[{"type":"text","text":"Justiz"}]},{"type":"paragraph","content":[{"type":"text","text":"Aktuell zu wenig aufgaben, und unnötig durch das fehlende Gericht."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§6 Blacklist' OR current_rule."category" IS DISTINCT FROM 'Fraktionsregelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', "category" = 'Fraktionsregelwerk', "title" = '§6 Blacklist', "order" = 6, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-faction-6-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Als "},{"type":"text","text":"„Blacklisted Fraktionen“"},{"type":"text","text":" gelten Fraktionen, deren Existenz, Ausrichtung oder Aktivitäten in direktem Widerspruch zu geltendem Recht, den RP-Serverregeln oder ethischen Standards stehen. Eine Blacklistung bedeutet ein vollständiges Verbot dieser Fraktionen auf dem Server. Jegliche Neugründung, Darstellung oder Bezugnahme auf diese Gruppen ist untersagt."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.1 Gründe für eine Blacklistung"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Gründe für eine Aufnahme auf die Blacklist umfassen unter anderem:"}]},{"type":"paragraph","content":[{"type":"text","text":"Illegale Aktivitäten:"},{"type":"text","text":" Beteiligung an oder Verherrlichung von kriminellen Handlungen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Hasspropaganda:"},{"type":"text","text":" Diskriminierung, Hetze oder gezielte Ausgrenzung von Personen(gruppen)."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Gewaltverherrlichung:"},{"type":"text","text":" Darstellung oder Befürwortung von Gewalt, Terrorismus oder radikalen Aktionen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Störung des Spielbetriebs:"},{"type":"text","text":" Dauerhafte Beeinträchtigung des Roleplay-Erlebnisses anderer Spieler durch unangemessenes Verhalten oder Konzept."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Wiederholte Regelverstöße:"},{"type":"text","text":" Anhaltende oder schwerwiegende Verstöße gegen Server- oder Fraktionsrichtlinien."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Geringer RP-Wert:"},{"type":"text","text":" Fraktionen, die keinen sinnvollen Beitrag zum RP leisten oder sich nicht in das Gesamtbild einfügen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mehrfache Ablehnung durch das Fraktionsmanagement:"},{"type":"text","text":" Bei wiederholt eingereichten und abgelehnten Konzepten."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.2 Allgemein verbotene Fraktionstypen"}]},{"type":"paragraph","content":[{"type":"text","text":"Die folgenden Fraktionstypen sind serverweit dauerhaft verboten:"}]},{"type":"paragraph","content":[{"type":"text","text":"Reale illegale Organisationen:"},{"type":"text","text":" z. B. Drogenkartelle (Sinaloa-Kartell), Terrororganisationen (IS, Al-Qaida), mafiöse Strukturen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Anti-Terror- und Drogen-Sondereinheiten (Realbezug):"},{"type":"text","text":" Aufgrund der realpolitischen Sensibilität, fehlender RP-Balance und häufiger Missbrauch dieser Fraktionen für Macht-RP."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"§6.3 Konkrete Blacklistete Fraktionen (inkl. Begründung)"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraktion"}]},{"type":"paragraph","content":[{"type":"text","text":"Grund für die Blacklistung"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Reale Gang´s"},{"type":"hardBreak"},{"type":"text","text":"Da DRP, keine echten Gangs und somit auch deren Gewalten fördern möchte."}]},{"type":"paragraph","content":[{"type":"text","text":"Bundes POL"}]},{"type":"paragraph","content":[{"type":"text","text":"Keinen Nutzen"}]},{"type":"paragraph","content":[{"type":"text","text":"Wasserpolizei"}]},{"type":"paragraph","content":[{"type":"text","text":"Kann nicht ausgespielt werden"}]},{"type":"paragraph","content":[{"type":"text","text":"Bundeswehr"}]},{"type":"paragraph","content":[{"type":"text","text":"Mehrere Regelverstöße und keinen Mehrwert."}]},{"type":"paragraph","content":[{"type":"text","text":"Kommando Delta (Delta D)"},{"type":"hardBreak"},{"type":"text","text":"Wiederholte Regelverstöße, kein ernsthaftes RP, Störung des Spielbetriebs, Gambo Truppe"}]},{"type":"paragraph","content":[{"type":"text","text":"Geheimdienste"},{"type":"hardBreak"},{"type":"text","text":"Zu geringe Relevanz im RP-Alltag, fehlender Spielmehrwert, wiederholt ohne Erfolg beantragt – kein erkennbarer RP-Nutzen."}]},{"type":"paragraph","content":[{"type":"text","text":"DLRG"}]},{"type":"paragraph","content":[{"type":"text","text":"Zu geringe Relevanz im RP-Alltag, kaum Spielbeteiligung, mehrfach ohne Erfolg beantragt, kein RP-Nutzen."}]},{"type":"paragraph","content":[{"type":"text","text":"Verfassungsschutz"}]},{"type":"paragraph","content":[{"type":"text","text":"Kein RP-Nutzen ohne tiefgreifende Sicherheitsmechanik."}]},{"type":"paragraph","content":[{"type":"text","text":"GSG9 / MEK"}]},{"type":"paragraph","content":[{"type":"text","text":"Unnötige Spezialeinheit + zu viel Gambo"}]},{"type":"paragraph","content":[{"type":"text","text":"Anti-Gang-Force / Anti-Tuning-Taskforce / Anti-RP-Crime-Unit"},{"type":"hardBreak"},{"type":"text","text":"Aufgaben gehören zur normalen Polizei, Reines Power-RP, Künstliche Rechtfertigung für Sonderrechte"}]},{"type":"paragraph","content":[{"type":"text","text":"BKA / LKA"},{"type":"hardBreak"},{"type":"text","text":"Unnötig und hat viele probleme gemacht"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Forstamt"},{"type":"hardBreak"},{"type":"text","text":"Keine richtigen aufgaben"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Fahrschule"},{"type":"hardBreak"},{"type":"text","text":"Da sie keinen nutzen hat"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Mehrfach-Fraktionen mit gleichem Zweck (zb 2 Feuerwehr, 2 Rettungsdienste)"}]},{"type":"paragraph","content":[{"type":"text","text":"Spaltet Spieler, Führt zu Unterbesetzung, Keine spielerischen Vorteile"}]},{"type":"paragraph","content":[{"type":"text","text":"Zentrale Unterstüzungsgruppe Zoll"}]},{"type":"paragraph","content":[{"type":"text","text":"unnötig da das SEK Exsistiert."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Zoll"},{"type":"hardBreak"},{"type":"text","text":"Unnötig, in ERLC keinen Zweck"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Regierung / Ämter / Bundesregierung"},{"type":"hardBreak"},{"type":"text","text":"Unnötig, zu viel macht, nicht ausspielbar."}]},{"type":"paragraph","content":[{"type":"text","text":"Justiz"}]},{"type":"paragraph","content":[{"type":"text","text":"Aktuell zu wenig aufgaben, und unnötig durch das fehlende Gericht."}]}]}'::jsonb, '§6 Blacklist Als „Blacklisted Fraktionen“ gelten Fraktionen, deren Existenz, Ausrichtung oder Aktivitäten in direktem Widerspruch zu geltendem Recht, den RP-Serverregeln oder ethischen Standards stehen. Eine Blacklistung bedeutet ein vollständiges Verbot dieser Fraktionen auf dem Server. Jegliche Neugründung, Darstellung oder Bezugnahme auf diese Gruppen ist untersagt. §6.1 Gründe für eine Blacklistung Die Gründe für eine Aufnahme auf die Blacklist umfassen unter anderem: Illegale Aktivitäten: Beteiligung an oder Verherrlichung von kriminellen Handlungen. Hasspropaganda: Diskriminierung, Hetze oder gezielte Ausgrenzung von Personen(gruppen). Gewaltverherrlichung: Darstellung oder Befürwortung von Gewalt, Terrorismus oder radikalen Aktionen. Störung des Spielbetriebs: Dauerhafte Beeinträchtigung des Roleplay-Erlebnisses anderer Spieler durch unangemessenes Verhalten oder Konzept. Wiederholte Regelverstöße: Anhaltende oder schwerwiegende Verstöße gegen Server- oder Fraktionsrichtlinien. Geringer RP-Wert: Fraktionen, die keinen sinnvollen Beitrag zum RP leisten oder sich nicht in das Gesamtbild einfügen. Mehrfache Ablehnung durch das Fraktionsmanagement: Bei wiederholt eingereichten und abgelehnten Konzepten. §6.2 Allgemein verbotene Fraktionstypen Die folgenden Fraktionstypen sind serverweit dauerhaft verboten: Reale illegale Organisationen: z. B. Drogenkartelle (Sinaloa-Kartell), Terrororganisationen (IS, Al-Qaida), mafiöse Strukturen. Anti-Terror- und Drogen-Sondereinheiten (Realbezug): Aufgrund der realpolitischen Sensibilität, fehlender RP-Balance und häufiger Missbrauch dieser Fraktionen für Macht-RP. §6.3 Konkrete Blacklistete Fraktionen (inkl. Begründung) Fraktion Grund für die Blacklistung Reale Gang´s Da DRP, keine echten Gangs und somit auch deren Gewalten fördern möchte. Bundes POL Keinen Nutzen Wasserpolizei Kann nicht ausgespielt werden Bundeswehr Mehrere Regelverstöße und keinen Mehrwert. Kommando Delta (Delta D) Wiederholte Regelverstöße, kein ernsthaftes RP, Störung des Spielbetriebs, Gambo Truppe Geheimdienste Zu geringe Relevanz im RP-Alltag, fehlender Spielmehrwert, wiederholt ohne Erfolg beantragt – kein erkennbarer RP-Nutzen. DLRG Zu geringe Relevanz im RP-Alltag, kaum Spielbeteiligung, mehrfach ohne Erfolg beantragt, kein RP-Nutzen. Verfassungsschutz Kein RP-Nutzen ohne tiefgreifende Sicherheitsmechanik. GSG9 / MEK Unnötige Spezialeinheit + zu viel Gambo Anti-Gang-Force / Anti-Tuning-Taskforce / Anti-RP-Crime-Unit Aufgaben gehören zur normalen Polizei, Reines Power-RP, Künstliche Rechtfertigung für Sonderrechte BKA / LKA Unnötig und hat viele probleme gemacht Forstamt Keine richtigen aufgaben Fahrschule Da sie keinen nutzen hat Mehrfach-Fraktionen mit gleichem Zweck (zb 2 Feuerwehr, 2 Rettungsdienste) Spaltet Spieler, Führt zu Unterbesetzung, Keine spielerischen Vorteile Zentrale Unterstüzungsgruppe Zoll unnötig da das SEK Exsistiert. Zoll Unnötig, in ERLC keinen Zweck Regierung / Ämter / Bundesregierung Unnötig, zu viel macht, nicht ausspielbar. Justiz Aktuell zu wenig aufgaben, und unnötig durch das fehlende Gericht.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
