  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-faction-7', 'faction-7', 'faction-7', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', 'Fraktionsregelwerk', '§7 - Mitgliederbegrenzung', 7, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
