    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Da auf dem Server "},{"type":"text","text":"maximal 49 Spieler gleichzeitig"},{"type":"text","text":" aktiv sein können, gelten folgende Regelungen für die Anzahl aktiver Mitglieder je Fraktion:"}]},{"type":"paragraph","content":[{"type":"text","text":"➤ "},{"type":"text","text":"Gangs:"}]},{"type":"paragraph","content":[{"type":"text","text":"Es dürfen "},{"type":"text","text":"maximal 8 Mitglieder einer Gang gleichzeitig"},{"type":"text","text":" auf dem Server aktiv sein."}]},{"type":"paragraph","content":[{"type":"text","text":"➤ "},{"type":"text","text":"Allgemein:"}]},{"type":"paragraph","content":[{"type":"text","text":"Es kann mit einer Ankündigung Mitglieder eingeschränkt werden bei Dysbalancen:"},{"type":"text","text":"Die Einschränkungen umfassen"},{"type":"text","text":"Verwehrung der Teilhabe"},{"type":"text","text":"Command Vollstreckung (:wanted)"},{"type":"text","text":"Einsprüche:"},{"type":"text","text":"Mitten in einer RP-Situation"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Einschränkungen umfassen"},{"type":"text","text":"Verwehrung der Teilhabe"},{"type":"text","text":"Command Vollstreckung (:wanted)"}]},{"type":"paragraph","content":[{"type":"text","text":"Verwehrung der Teilhabe"}]},{"type":"paragraph","content":[{"type":"text","text":"Command Vollstreckung (:wanted)"}]},{"type":"paragraph","content":[{"type":"text","text":"Einsprüche:"},{"type":"text","text":"Mitten in einer RP-Situation"}]},{"type":"paragraph","content":[{"type":"text","text":"Mitten in einer RP-Situation"}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"§7.1 Besondere Regelungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Serverauslastung:"},{"type":"hardBreak"},{"type":"text","text":" Wenn der Server nahezu voll ist (über 45/49 Spielern), kann das Serverteam die aktiven Mitgliederzahlen der Fraktionen kurzfristig weiter begrenzen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Ereignisbasierte Ausnahmen:"},{"type":"hardBreak"},{"type":"text","text":" Bei offiziellen Server-Events, Großeinsätzen oder geplanten RP-Szenarien kann die Fraktionsleitung Sondergenehmigungen beim Serverteam beantragen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Verpflichtung zur Rotation:"},{"type":"hardBreak"},{"type":"text","text":" Fraktionsleitungen sind verpflichtet, bei hoher Serverauslastung eine faire Rotation ihrer Mitglieder zu organisieren, sodass möglichst viele Spieler die Chance haben, mitzuspielen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§7 - Mitgliederbegrenzung' OR current_rule."category" IS DISTINCT FROM 'Fraktionsregelwerk' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk', "category" = 'Fraktionsregelwerk', "title" = '§7 - Mitgliederbegrenzung', "order" = 7, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-faction-7-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Da auf dem Server "},{"type":"text","text":"maximal 49 Spieler gleichzeitig"},{"type":"text","text":" aktiv sein können, gelten folgende Regelungen für die Anzahl aktiver Mitglieder je Fraktion:"}]},{"type":"paragraph","content":[{"type":"text","text":"➤ "},{"type":"text","text":"Gangs:"}]},{"type":"paragraph","content":[{"type":"text","text":"Es dürfen "},{"type":"text","text":"maximal 8 Mitglieder einer Gang gleichzeitig"},{"type":"text","text":" auf dem Server aktiv sein."}]},{"type":"paragraph","content":[{"type":"text","text":"➤ "},{"type":"text","text":"Allgemein:"}]},{"type":"paragraph","content":[{"type":"text","text":"Es kann mit einer Ankündigung Mitglieder eingeschränkt werden bei Dysbalancen:"},{"type":"text","text":"Die Einschränkungen umfassen"},{"type":"text","text":"Verwehrung der Teilhabe"},{"type":"text","text":"Command Vollstreckung (:wanted)"},{"type":"text","text":"Einsprüche:"},{"type":"text","text":"Mitten in einer RP-Situation"}]},{"type":"paragraph","content":[{"type":"text","text":"Die Einschränkungen umfassen"},{"type":"text","text":"Verwehrung der Teilhabe"},{"type":"text","text":"Command Vollstreckung (:wanted)"}]},{"type":"paragraph","content":[{"type":"text","text":"Verwehrung der Teilhabe"}]},{"type":"paragraph","content":[{"type":"text","text":"Command Vollstreckung (:wanted)"}]},{"type":"paragraph","content":[{"type":"text","text":"Einsprüche:"},{"type":"text","text":"Mitten in einer RP-Situation"}]},{"type":"paragraph","content":[{"type":"text","text":"Mitten in einer RP-Situation"}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"§7.1 Besondere Regelungen"}]},{"type":"paragraph","content":[{"type":"text","text":"Serverauslastung:"},{"type":"hardBreak"},{"type":"text","text":" Wenn der Server nahezu voll ist (über 45/49 Spielern), kann das Serverteam die aktiven Mitgliederzahlen der Fraktionen kurzfristig weiter begrenzen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Ereignisbasierte Ausnahmen:"},{"type":"hardBreak"},{"type":"text","text":" Bei offiziellen Server-Events, Großeinsätzen oder geplanten RP-Szenarien kann die Fraktionsleitung Sondergenehmigungen beim Serverteam beantragen."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Verpflichtung zur Rotation:"},{"type":"hardBreak"},{"type":"text","text":" Fraktionsleitungen sind verpflichtet, bei hoher Serverauslastung eine faire Rotation ihrer Mitglieder zu organisieren, sodass möglichst viele Spieler die Chance haben, mitzuspielen."}]}]}'::jsonb, '§7 - Mitgliederbegrenzung Da auf dem Server maximal 49 Spieler gleichzeitig aktiv sein können, gelten folgende Regelungen für die Anzahl aktiver Mitglieder je Fraktion: ➤ Gangs: Es dürfen maximal 8 Mitglieder einer Gang gleichzeitig auf dem Server aktiv sein. ➤ Allgemein: Es kann mit einer Ankündigung Mitglieder eingeschränkt werden bei Dysbalancen: Die Einschränkungen umfassen Verwehrung der Teilhabe Command Vollstreckung (:wanted) Einsprüche: Mitten in einer RP-Situation Die Einschränkungen umfassen Verwehrung der Teilhabe Command Vollstreckung (:wanted) Verwehrung der Teilhabe Command Vollstreckung (:wanted) Einsprüche: Mitten in einer RP-Situation Mitten in einer RP-Situation §7.1 Besondere Regelungen Serverauslastung: Wenn der Server nahezu voll ist (über 45/49 Spielern), kann das Serverteam die aktiven Mitgliederzahlen der Fraktionen kurzfristig weiter begrenzen. Ereignisbasierte Ausnahmen: Bei offiziellen Server-Events, Großeinsätzen oder geplanten RP-Szenarien kann die Fraktionsleitung Sondergenehmigungen beim Serverteam beantragen. Verpflichtung zur Rotation: Fraktionsleitungen sind verpflichtet, bei hoher Serverauslastung eine faire Rotation ihrer Mitglieder zu organisieren, sodass möglichst viele Spieler die Chance haben, mitzuspielen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-factions-1';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-factions-1', 'main-factions-1', 'main-factions-1', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', 'Hauptfraktionen', '§ 1 Definition & Sonderstatus von Hauptfraktionen', 1, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen bilden das staatliche und infrastrukturelle Fundament des Server-Roleplays."}]},{"type":"paragraph","content":[{"type":"text","text":"Zu den Hauptfraktionen zählen ausschließlich behördliche Institutionen wie die Polizei , der Rettungsdienst und die Feuerwehr."}]},{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen genießen Sonderrechte im Servergeschehen, unterliegen im Gegenzug jedoch veränderten und strengeren Auflagen seitens des Fraktionsmanagements (FM)."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 1 Definition & Sonderstatus von Hauptfraktionen' OR current_rule."category" IS DISTINCT FROM 'Hauptfraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', "category" = 'Hauptfraktionen', "title" = '§ 1 Definition & Sonderstatus von Hauptfraktionen', "order" = 1, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-factions-1-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen bilden das staatliche und infrastrukturelle Fundament des Server-Roleplays."}]},{"type":"paragraph","content":[{"type":"text","text":"Zu den Hauptfraktionen zählen ausschließlich behördliche Institutionen wie die Polizei , der Rettungsdienst und die Feuerwehr."}]},{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen genießen Sonderrechte im Servergeschehen, unterliegen im Gegenzug jedoch veränderten und strengeren Auflagen seitens des Fraktionsmanagements (FM)."}]}]}'::jsonb, '§ 1 Definition & Sonderstatus von Hauptfraktionen Hauptfraktionen bilden das staatliche und infrastrukturelle Fundament des Server-Roleplays. Zu den Hauptfraktionen zählen ausschließlich behördliche Institutionen wie die Polizei , der Rettungsdienst und die Feuerwehr. Hauptfraktionen genießen Sonderrechte im Servergeschehen, unterliegen im Gegenzug jedoch veränderten und strengeren Auflagen seitens des Fraktionsmanagements (FM).', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-factions-2';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-factions-2', 'main-factions-2', 'main-factions-2', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', 'Hauptfraktionen', '§ 2 Vergabe & Übernahme der Fraktionsleitung', 2, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen können "},{"type":"text","text":"nicht"},{"type":"text","text":" über den regulären Weg der privaten Fraktionsgründung beantragt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Vergabe einer Hauptfraktionsleitung erfolgt ausschließlich über offizielle Ausschreibungen, gesonderte Bewerbungsphasen oder die direkte Einsetzung durch die Serverleitung bzw. das FM."}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM behält sich das Recht vor, Bewerbungen für Hauptfraktionen ohne Angabe von Gründen abzulehnen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 2 Vergabe & Übernahme der Fraktionsleitung' OR current_rule."category" IS DISTINCT FROM 'Hauptfraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
