  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-factions-2-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hauptfraktionen können "},{"type":"text","text":"nicht"},{"type":"text","text":" über den regulären Weg der privaten Fraktionsgründung beantragt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Vergabe einer Hauptfraktionsleitung erfolgt ausschließlich über offizielle Ausschreibungen, gesonderte Bewerbungsphasen oder die direkte Einsetzung durch die Serverleitung bzw. das FM."}]},{"type":"paragraph","content":[{"type":"text","text":"Das FM behält sich das Recht vor, Bewerbungen für Hauptfraktionen ohne Angabe von Gründen abzulehnen."}]}]}'::jsonb, '§ 2 Vergabe & Übernahme der Fraktionsleitung Hauptfraktionen können nicht über den regulären Weg der privaten Fraktionsgründung beantragt werden. Die Vergabe einer Hauptfraktionsleitung erfolgt ausschließlich über offizielle Ausschreibungen, gesonderte Bewerbungsphasen oder die direkte Einsetzung durch die Serverleitung bzw. das FM. Das FM behält sich das Recht vor, Bewerbungen für Hauptfraktionen ohne Angabe von Gründen abzulehnen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
