      ('revision-main-factions-8-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das zur Verfügung gestellte Equipment (Waffen, Fahrzeuge, Spezialausrüstung) darf ausschließlich für dienstliche Zwecke genutzt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Nutzung von behördlichen Fahrzeugen oder Waffen außerhalb des Dienstes (\"Off-Duty\") ist untersagt, sofern keine spezifische Dienstanweisung dies gestattet."}]}]}'::jsonb, '§ 8 Equipment & Fuhrparknutzung Das zur Verfügung gestellte Equipment (Waffen, Fahrzeuge, Spezialausrüstung) darf ausschließlich für dienstliche Zwecke genutzt werden. Die Nutzung von behördlichen Fahrzeugen oder Waffen außerhalb des Dienstes ("Off-Duty") ist untersagt, sofern keine spezifische Dienstanweisung dies gestattet.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

