      ('rule-main-factions-9', 'main-factions-9', 'main-factions-9', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', 'Hauptfraktionen', '§ 9 Sanktions- & Auswechselmodell', 9, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
