    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Regelungen des allgemeinen Fraktions-Warn-Systems gelten sinngemäß auch für Hauptfraktionen."}]},{"type":"paragraph","content":[{"type":"text","text":"Besonderheit bei Hauptfraktionen:"},{"type":"text","text":" Bei Erreichen von 3 Fraktions-Warns oder bei einer Schließungsentscheidung wird "},{"type":"text","text":"niemals die Behörde als Ganzes vom Server gelöscht"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Stattdessen wird die aktuelle "},{"type":"text","text":"Fraktionsleitung entlassen und ausgetauscht"},{"type":"text","text":". Die Struktur der Fraktion bleibt bestehen und wird einer neuen Führung übergeben."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 9 Sanktions- & Auswechselmodell' OR current_rule."category" IS DISTINCT FROM 'Hauptfraktionen' THEN
      next_version := current_rule."version" + 1;
