    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', "category" = 'Hauptfraktionen', "title" = '§ 9 Sanktions- & Auswechselmodell', "order" = 9, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
