    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-factions-9-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Regelungen des allgemeinen Fraktions-Warn-Systems gelten sinngemäß auch für Hauptfraktionen."}]},{"type":"paragraph","content":[{"type":"text","text":"Besonderheit bei Hauptfraktionen:"},{"type":"text","text":" Bei Erreichen von 3 Fraktions-Warns oder bei einer Schließungsentscheidung wird "},{"type":"text","text":"niemals die Behörde als Ganzes vom Server gelöscht"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Stattdessen wird die aktuelle "},{"type":"text","text":"Fraktionsleitung entlassen und ausgetauscht"},{"type":"text","text":". Die Struktur der Fraktion bleibt bestehen und wird einer neuen Führung übergeben."}]}]}'::jsonb, '§ 9 Sanktions- & Auswechselmodell Die Regelungen des allgemeinen Fraktions-Warn-Systems gelten sinngemäß auch für Hauptfraktionen. Besonderheit bei Hauptfraktionen: Bei Erreichen von 3 Fraktions-Warns oder bei einer Schließungsentscheidung wird niemals die Behörde als Ganzes vom Server gelöscht . Stattdessen wird die aktuelle Fraktionsleitung entlassen und ausgetauscht . Die Struktur der Fraktion bleibt bestehen und wird einer neuen Führung übergeben.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

