  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-factions-11';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-factions-11', 'main-factions-11', 'main-factions-11', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', 'Hauptfraktionen', '§ 11 Gründung von Neben- & Unterfraktionen', 11, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Erstellung einer eigenständigen Unterfraktion oder Spezialabteilung (z. B. SEK/MEK, Kripo, Task Force, Air Support) innerhalb einer Hauptfraktion ist "},{"type":"text","text":"genehmigungspflichtig"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Hauptfraktionsleitung muss vor der Eröffnung ein schriftliches Konzept beim Fraktionsmanagement (FM) per Ticket einreichen."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Konzept muss folgende Punkte beinhalten:"},{"type":"text","text":"Sinn & RP-Mehrwert:"},{"type":"text","text":" Warum ist diese Unterfraktion notwendig?"},{"type":"text","text":"Aufgabenbereich:"},{"type":"text","text":" Welches spezifische Einsatzgebiet deckt die Einheit ab?"},{"type":"text","text":"Zugangsvoraussetzungen:"},{"type":"text","text":" Welche Ausbildungen und Ränge werden für den Beitritt benötigt?"},{"type":"text","text":"Leitung:"},{"type":"text","text":" Wer übernimmt die Abteilungsleitung?"}]},{"type":"paragraph","content":[{"type":"text","text":"Sinn & RP-Mehrwert:"},{"type":"text","text":" Warum ist diese Unterfraktion notwendig?"}]},{"type":"paragraph","content":[{"type":"text","text":"Aufgabenbereich:"},{"type":"text","text":" Welches spezifische Einsatzgebiet deckt die Einheit ab?"}]},{"type":"paragraph","content":[{"type":"text","text":"Zugangsvoraussetzungen:"},{"type":"text","text":" Welche Ausbildungen und Ränge werden für den Beitritt benötigt?"}]},{"type":"paragraph","content":[{"type":"text","text":"Leitung:"},{"type":"text","text":" Wer übernimmt die Abteilungsleitung?"}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Unterfraktion darf erst nach ausdrücklicher, schriftlicher Freigabe durch das FM im RP agieren."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 11 Gründung von Neben- & Unterfraktionen' OR current_rule."category" IS DISTINCT FROM 'Hauptfraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', "category" = 'Hauptfraktionen', "title" = '§ 11 Gründung von Neben- & Unterfraktionen', "order" = 11, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-factions-11-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Erstellung einer eigenständigen Unterfraktion oder Spezialabteilung (z. B. SEK/MEK, Kripo, Task Force, Air Support) innerhalb einer Hauptfraktion ist "},{"type":"text","text":"genehmigungspflichtig"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Hauptfraktionsleitung muss vor der Eröffnung ein schriftliches Konzept beim Fraktionsmanagement (FM) per Ticket einreichen."}]},{"type":"paragraph","content":[{"type":"text","text":"Das Konzept muss folgende Punkte beinhalten:"},{"type":"text","text":"Sinn & RP-Mehrwert:"},{"type":"text","text":" Warum ist diese Unterfraktion notwendig?"},{"type":"text","text":"Aufgabenbereich:"},{"type":"text","text":" Welches spezifische Einsatzgebiet deckt die Einheit ab?"},{"type":"text","text":"Zugangsvoraussetzungen:"},{"type":"text","text":" Welche Ausbildungen und Ränge werden für den Beitritt benötigt?"},{"type":"text","text":"Leitung:"},{"type":"text","text":" Wer übernimmt die Abteilungsleitung?"}]},{"type":"paragraph","content":[{"type":"text","text":"Sinn & RP-Mehrwert:"},{"type":"text","text":" Warum ist diese Unterfraktion notwendig?"}]},{"type":"paragraph","content":[{"type":"text","text":"Aufgabenbereich:"},{"type":"text","text":" Welches spezifische Einsatzgebiet deckt die Einheit ab?"}]},{"type":"paragraph","content":[{"type":"text","text":"Zugangsvoraussetzungen:"},{"type":"text","text":" Welche Ausbildungen und Ränge werden für den Beitritt benötigt?"}]},{"type":"paragraph","content":[{"type":"text","text":"Leitung:"},{"type":"text","text":" Wer übernimmt die Abteilungsleitung?"}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Unterfraktion darf erst nach ausdrücklicher, schriftlicher Freigabe durch das FM im RP agieren."}]}]}'::jsonb, '§ 11 Gründung von Neben- & Unterfraktionen Die Erstellung einer eigenständigen Unterfraktion oder Spezialabteilung (z. B. SEK/MEK, Kripo, Task Force, Air Support) innerhalb einer Hauptfraktion ist genehmigungspflichtig . Die Hauptfraktionsleitung muss vor der Eröffnung ein schriftliches Konzept beim Fraktionsmanagement (FM) per Ticket einreichen. Das Konzept muss folgende Punkte beinhalten: Sinn & RP-Mehrwert: Warum ist diese Unterfraktion notwendig? Aufgabenbereich: Welches spezifische Einsatzgebiet deckt die Einheit ab? Zugangsvoraussetzungen: Welche Ausbildungen und Ränge werden für den Beitritt benötigt? Leitung: Wer übernimmt die Abteilungsleitung? Sinn & RP-Mehrwert: Warum ist diese Unterfraktion notwendig? Aufgabenbereich: Welches spezifische Einsatzgebiet deckt die Einheit ab? Zugangsvoraussetzungen: Welche Ausbildungen und Ränge werden für den Beitritt benötigt? Leitung: Wer übernimmt die Abteilungsleitung? Eine Unterfraktion darf erst nach ausdrücklicher, schriftlicher Freigabe durch das FM im RP agieren.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-factions-12';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-factions-12', 'main-factions-12', 'main-factions-12', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', 'Hauptfraktionen', '§ 12 Verwaltung & Auflösung von Unterfraktionen', 12, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Verantwortung:"},{"type":"text","text":" Die Führung der Hauptfraktion bleibt gegenüber dem FM vollumfänglich für das Verhalten und die Einhaltung der Regeln innerhalb ihrer Unterfraktionen verantwortlich."}]},{"type":"paragraph","content":[{"type":"text","text":"Mitgliederlimit:"},{"type":"text","text":" Unterfraktionen dienen als spezialisierte Einheiten. Sie dürfen nicht die gesamte Mannstärke der Hauptfraktion umfassen; das FM kann personelle Obergrenzen (Mitglieder-Caps) festlegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eigenmächtigkeit:"},{"type":"text","text":" Unterfraktionen besitzen keine administrative Autonomie. Sie bleiben der Gesamtleitung der Hauptfraktion unterstellt."}]},{"type":"paragraph","content":[{"type":"text","text":"Schließung durch das FM:"},{"type":"text","text":" Sollte eine Unterfraktion das RP stören, durch übermäßige Härte/FailRP auffallen oder inaktiv werden, behält sich das FM das Recht vor, die Unterfraktion einzeln aufzulösen, ohne direkt die gesamte Hauptfraktion zu bestrafen."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 12 Verwaltung & Auflösung von Unterfraktionen' OR current_rule."category" IS DISTINCT FROM 'Hauptfraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', "category" = 'Hauptfraktionen', "title" = '§ 12 Verwaltung & Auflösung von Unterfraktionen', "order" = 12, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-factions-12-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Verantwortung:"},{"type":"text","text":" Die Führung der Hauptfraktion bleibt gegenüber dem FM vollumfänglich für das Verhalten und die Einhaltung der Regeln innerhalb ihrer Unterfraktionen verantwortlich."}]},{"type":"paragraph","content":[{"type":"text","text":"Mitgliederlimit:"},{"type":"text","text":" Unterfraktionen dienen als spezialisierte Einheiten. Sie dürfen nicht die gesamte Mannstärke der Hauptfraktion umfassen; das FM kann personelle Obergrenzen (Mitglieder-Caps) festlegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eigenmächtigkeit:"},{"type":"text","text":" Unterfraktionen besitzen keine administrative Autonomie. Sie bleiben der Gesamtleitung der Hauptfraktion unterstellt."}]},{"type":"paragraph","content":[{"type":"text","text":"Schließung durch das FM:"},{"type":"text","text":" Sollte eine Unterfraktion das RP stören, durch übermäßige Härte/FailRP auffallen oder inaktiv werden, behält sich das FM das Recht vor, die Unterfraktion einzeln aufzulösen, ohne direkt die gesamte Hauptfraktion zu bestrafen."}]}]}'::jsonb, '§ 12 Verwaltung & Auflösung von Unterfraktionen Verantwortung: Die Führung der Hauptfraktion bleibt gegenüber dem FM vollumfänglich für das Verhalten und die Einhaltung der Regeln innerhalb ihrer Unterfraktionen verantwortlich. Mitgliederlimit: Unterfraktionen dienen als spezialisierte Einheiten. Sie dürfen nicht die gesamte Mannstärke der Hauptfraktion umfassen; das FM kann personelle Obergrenzen (Mitglieder-Caps) festlegen. Eigenmächtigkeit: Unterfraktionen besitzen keine administrative Autonomie. Sie bleiben der Gesamtleitung der Hauptfraktion unterstellt. Schließung durch das FM: Sollte eine Unterfraktion das RP stören, durch übermäßige Härte/FailRP auffallen oder inaktiv werden, behält sich das FM das Recht vor, die Unterfraktion einzeln aufzulösen, ohne direkt die gesamte Hauptfraktion zu bestrafen.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'main-factions-13';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-main-factions-13', 'main-factions-13', 'main-factions-13', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', 'Hauptfraktionen', '§ 13 Absperrungen', 13, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grundsatz für Absperrungen:"},{"type":"hardBreak"},{"type":"text","text":"Jede Art von Absperrung – egal ob wegen Baustellen, Tagesbaustellen, Unfällen oder Veranstaltungen – muss so aufgebaut werden, dass der Verkehr weiterhin fließen kann. Es ist nicht erlaubt, Straßen ohne triftigen Grund komplett dichtzumachen. Wann immer möglich, muss mindestens eine Fahrspur für den Verkehr frei bleiben oder eine Ausweichmöglichkeit geschaffen werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Pflicht zur Umleitung:"},{"type":"hardBreak"},{"type":"text","text":"Sollte eine Fahrbahn oder ein Straßenabschnitt teilweise oder komplett gesperrt werden müssen, verpflichten sich die beteiligten Einsatzkräfte bzw. Fraktionen dazu, sofort eine verständliche und sichere Umleitung einzurichten. Diese muss entweder durch Absperrmaterial (z. B. Schilder, Baken, Absperrbänder) gut sichtbar ausgeschildert oder durch Personal vor Ort geregelt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahmen für Komplettsperrungen (Großschadenslagen):"},{"type":"hardBreak"},{"type":"text","text":"Eine vollständige Sperrung einer Straße ohne direkte Umleitung ist grundsätzlich verboten. Eine Ausnahme gilt ausschließlich bei extremen Notfällen und unvorhersehbaren Großschadenslagen, bei denen eine Durchfahrt eine unmittelbare Lebensgefahr darstellen würde. Dazu zählen zum Beispiel:"}]},{"type":"paragraph","content":[{"type":"text","text":"Abstürze von Flugzeugen oder Helikoptern auf Autobahnen oder Hauptverkehrsstraßen"}]},{"type":"paragraph","content":[{"type":"text","text":"Einstürze von Tunneln, Brücken oder Fahrbahnen"}]},{"type":"paragraph","content":[{"type":"text","text":"Massenunfälle mit akuter Explosions-, Brand- oder Einsturzgefahr"}]},{"type":"paragraph","content":[{"type":"text","text":"Rückbau und Teilfreigabe:"},{"type":"hardBreak"},{"type":"text","text":"Sobald die akute Gefahr vor Ort gebannt ist oder die Löscharbeiten und Rettungsmaßnahmen weit genug fortgeschritten sind, muss die Sperrung so schnell wie möglich auf das absolute Minimum reduziert werden. Wenn es die Lage zulässt, ist die Fahrbahn sofort wieder teilweise freizugeben oder eine Umleitung für das verbleibende RP einzurichten."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 13 Absperrungen' OR current_rule."category" IS DISTINCT FROM 'Hauptfraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/hauptfraktionen', "category" = 'Hauptfraktionen', "title" = '§ 13 Absperrungen', "order" = 13, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-main-factions-13-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grundsatz für Absperrungen:"},{"type":"hardBreak"},{"type":"text","text":"Jede Art von Absperrung – egal ob wegen Baustellen, Tagesbaustellen, Unfällen oder Veranstaltungen – muss so aufgebaut werden, dass der Verkehr weiterhin fließen kann. Es ist nicht erlaubt, Straßen ohne triftigen Grund komplett dichtzumachen. Wann immer möglich, muss mindestens eine Fahrspur für den Verkehr frei bleiben oder eine Ausweichmöglichkeit geschaffen werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Pflicht zur Umleitung:"},{"type":"hardBreak"},{"type":"text","text":"Sollte eine Fahrbahn oder ein Straßenabschnitt teilweise oder komplett gesperrt werden müssen, verpflichten sich die beteiligten Einsatzkräfte bzw. Fraktionen dazu, sofort eine verständliche und sichere Umleitung einzurichten. Diese muss entweder durch Absperrmaterial (z. B. Schilder, Baken, Absperrbänder) gut sichtbar ausgeschildert oder durch Personal vor Ort geregelt werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahmen für Komplettsperrungen (Großschadenslagen):"},{"type":"hardBreak"},{"type":"text","text":"Eine vollständige Sperrung einer Straße ohne direkte Umleitung ist grundsätzlich verboten. Eine Ausnahme gilt ausschließlich bei extremen Notfällen und unvorhersehbaren Großschadenslagen, bei denen eine Durchfahrt eine unmittelbare Lebensgefahr darstellen würde. Dazu zählen zum Beispiel:"}]},{"type":"paragraph","content":[{"type":"text","text":"Abstürze von Flugzeugen oder Helikoptern auf Autobahnen oder Hauptverkehrsstraßen"}]},{"type":"paragraph","content":[{"type":"text","text":"Einstürze von Tunneln, Brücken oder Fahrbahnen"}]},{"type":"paragraph","content":[{"type":"text","text":"Massenunfälle mit akuter Explosions-, Brand- oder Einsturzgefahr"}]},{"type":"paragraph","content":[{"type":"text","text":"Rückbau und Teilfreigabe:"},{"type":"hardBreak"},{"type":"text","text":"Sobald die akute Gefahr vor Ort gebannt ist oder die Löscharbeiten und Rettungsmaßnahmen weit genug fortgeschritten sind, muss die Sperrung so schnell wie möglich auf das absolute Minimum reduziert werden. Wenn es die Lage zulässt, ist die Fahrbahn sofort wieder teilweise freizugeben oder eine Umleitung für das verbleibende RP einzurichten."}]}]}'::jsonb, '§ 13 Absperrungen Grundsatz für Absperrungen: Jede Art von Absperrung – egal ob wegen Baustellen, Tagesbaustellen, Unfällen oder Veranstaltungen – muss so aufgebaut werden, dass der Verkehr weiterhin fließen kann. Es ist nicht erlaubt, Straßen ohne triftigen Grund komplett dichtzumachen. Wann immer möglich, muss mindestens eine Fahrspur für den Verkehr frei bleiben oder eine Ausweichmöglichkeit geschaffen werden. Pflicht zur Umleitung: Sollte eine Fahrbahn oder ein Straßenabschnitt teilweise oder komplett gesperrt werden müssen, verpflichten sich die beteiligten Einsatzkräfte bzw. Fraktionen dazu, sofort eine verständliche und sichere Umleitung einzurichten. Diese muss entweder durch Absperrmaterial (z. B. Schilder, Baken, Absperrbänder) gut sichtbar ausgeschildert oder durch Personal vor Ort geregelt werden. Ausnahmen für Komplettsperrungen (Großschadenslagen): Eine vollständige Sperrung einer Straße ohne direkte Umleitung ist grundsätzlich verboten. Eine Ausnahme gilt ausschließlich bei extremen Notfällen und unvorhersehbaren Großschadenslagen, bei denen eine Durchfahrt eine unmittelbare Lebensgefahr darstellen würde. Dazu zählen zum Beispiel: Abstürze von Flugzeugen oder Helikoptern auf Autobahnen oder Hauptverkehrsstraßen Einstürze von Tunneln, Brücken oder Fahrbahnen Massenunfälle mit akuter Explosions-, Brand- oder Einsturzgefahr Rückbau und Teilfreigabe: Sobald die akute Gefahr vor Ort gebannt ist oder die Löscharbeiten und Rettungsmaßnahmen weit genug fortgeschritten sind, muss die Sperrung so schnell wie möglich auf das absolute Minimum reduziert werden. Wenn es die Lage zulässt, ist die Fahrbahn sofort wieder teilweise freizugeben oder eine Umleitung für das verbleibende RP einzurichten.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

