    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-legal-factions-10', 'legal-factions-10', 'legal-factions-10', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/legale-fraktionen', 'Legale Fraktionen', '§ 10 Mitarbeiter-Obergrenze (Personal-Cap)', 10, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Um eine Monopolbildung zu verhindern und faire Chancen für alle Betriebe zu wahren, kann das Fraktionsmanagement (FM) ein personelles Limit für Angestellte festlegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Geschäftsführung ist verpflichtet, die aktuelle Mitarbeiterliste auf dem neuesten Stand zu halten und dem FM auf Anfrage offenzulegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Das gezielte und aggressive Abwerben von Angestellten anderer Firmen (\"Headhunting\") während deren Dienstzeit ist untersagt."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 10 Mitarbeiter-Obergrenze (Personal-Cap)' OR current_rule."category" IS DISTINCT FROM 'Legale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
