      ('revision-legal-factions-10-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Um eine Monopolbildung zu verhindern und faire Chancen für alle Betriebe zu wahren, kann das Fraktionsmanagement (FM) ein personelles Limit für Angestellte festlegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Die Geschäftsführung ist verpflichtet, die aktuelle Mitarbeiterliste auf dem neuesten Stand zu halten und dem FM auf Anfrage offenzulegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Das gezielte und aggressive Abwerben von Angestellten anderer Firmen (\"Headhunting\") während deren Dienstzeit ist untersagt."}]}]}'::jsonb, '§ 10 Mitarbeiter-Obergrenze (Personal-Cap) Um eine Monopolbildung zu verhindern und faire Chancen für alle Betriebe zu wahren, kann das Fraktionsmanagement (FM) ein personelles Limit für Angestellte festlegen. Die Geschäftsführung ist verpflichtet, die aktuelle Mitarbeiterliste auf dem neuesten Stand zu halten und dem FM auf Anfrage offenzulegen. Das gezielte und aggressive Abwerben von Angestellten anderer Firmen ("Headhunting") während deren Dienstzeit ist untersagt.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

