    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-legal-factions-12', 'legal-factions-12', 'legal-factions-12', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/legale-fraktionen', 'Legale Fraktionen', '§ 12 Verträge & Kooperationen (Hauptfraktionen & Gangs)', 12, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
