    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fraktionsfarbe:"},{"type":"text","text":" Jede Gang muss beim Fraktionsmanagement (FM) eine eindeutige Fraktionsfarbe beantragen und genehmigen lassen. Diese Farbe muss bei Fraktionsaktionen klar erkennbar getragen werden (z. B. Kleidung/Oberteile)."}]},{"type":"paragraph","content":[{"type":"text","text":"Fuhrpark:"},{"type":"text","text":" Einsatzfahrzeuge der Gang müssen in der genehmigten Fraktionsfarbe lackiert sein."}]},{"type":"paragraph","content":[{"type":"text","text":"Kennzeichen-Kürzel:"},{"type":"text","text":" Alle Mitgliedsfahrzeuge, die für Fraktionsaktivitäten genutzt werden, müssen das vom FM zugewiesene Kennzeichen-Kürzel tragen (z. B. Bloods)."}]},{"type":"paragraph","content":[{"type":"text","text":"Farben von anderen Gangs dürfen nicht verwendet werden."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 2 Identität (Fraktionsfarbe, Fuhrpark & Kennzeichen)' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
