DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'illegal-factions-3';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-illegal-factions-3', 'illegal-factions-3', 'illegal-factions-3', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', 'Illegale Fraktionen', '§ 3 Maskierung & Identitätsschutz', 3, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Während krimineller Handlungen oder Fraktionsaktionen ist das Tragen von Gesichtsmaskierungen gestattet, um die Identität RP-konform zu schützen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Vollmaskierung entbindet nicht von der Pflicht, die zugewiesene "},{"type":"text","text":"Fraktionsfarbe"},{"type":"text","text":" an der Kleidung zu tragen."}]},{"type":"paragraph","content":[{"type":"text","text":"Es ist untersagt, die Identität einer rivalisierenden Gang durch Tragen deren Farben oder Merkmale nachzuahmen, um Straftaten vorzutäuschen (\"False Flagging\"), es sei denn, dies wurde zuvor per FM-Ticket als RP-Konzept genehmigt."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 3 Maskierung & Identitätsschutz' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 3 Maskierung & Identitätsschutz', "order" = 3, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-3-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Während krimineller Handlungen oder Fraktionsaktionen ist das Tragen von Gesichtsmaskierungen gestattet, um die Identität RP-konform zu schützen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eine Vollmaskierung entbindet nicht von der Pflicht, die zugewiesene "},{"type":"text","text":"Fraktionsfarbe"},{"type":"text","text":" an der Kleidung zu tragen."}]},{"type":"paragraph","content":[{"type":"text","text":"Es ist untersagt, die Identität einer rivalisierenden Gang durch Tragen deren Farben oder Merkmale nachzuahmen, um Straftaten vorzutäuschen (\"False Flagging\"), es sei denn, dies wurde zuvor per FM-Ticket als RP-Konzept genehmigt."}]}]}'::jsonb, '§ 3 Maskierung & Identitätsschutz Während krimineller Handlungen oder Fraktionsaktionen ist das Tragen von Gesichtsmaskierungen gestattet, um die Identität RP-konform zu schützen. Eine Vollmaskierung entbindet nicht von der Pflicht, die zugewiesene Fraktionsfarbe an der Kleidung zu tragen. Es ist untersagt, die Identität einer rivalisierenden Gang durch Tragen deren Farben oder Merkmale nachzuahmen, um Straftaten vorzutäuschen ("False Flagging"), es sei denn, dies wurde zuvor per FM-Ticket als RP-Konzept genehmigt.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

