    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aktivitäts-Cap:"},{"type":"text","text":" In einer aktiven RP-Situation, Verfolgung, Schießerei oder Fraktionsaktion dürfen "},{"type":"text","text":"maximal 8 Mitglieder"},{"type":"text","text":" einer Gang gleichzeitig agieren."}]},{"type":"paragraph","content":[{"type":"text","text":"Verstärkungsverbot:"},{"type":"text","text":" Sobald eine Situation begonnen hat, dürfen keine weiteren Mitglieder nachgefordert werden, wenn das Limit von 8 Personen bereits erreicht ist."}]},{"type":"paragraph","content":[{"type":"text","text":"Massen-UnRP:"},{"type":"text","text":" Das Agieren mit mehr als 8 aktiven Personen in einer laufenden Situation gilt als schwerer Regelverstoß und schlägt direkt auf die gesamte Fraktion zurück."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 4 Mitglieder-Limit & Aktive Beteiligung (8er-Regel)' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 4 Mitglieder-Limit & Aktive Beteiligung (8er-Regel)', "order" = 4, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-4-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aktivitäts-Cap:"},{"type":"text","text":" In einer aktiven RP-Situation, Verfolgung, Schießerei oder Fraktionsaktion dürfen "},{"type":"text","text":"maximal 8 Mitglieder"},{"type":"text","text":" einer Gang gleichzeitig agieren."}]},{"type":"paragraph","content":[{"type":"text","text":"Verstärkungsverbot:"},{"type":"text","text":" Sobald eine Situation begonnen hat, dürfen keine weiteren Mitglieder nachgefordert werden, wenn das Limit von 8 Personen bereits erreicht ist."}]},{"type":"paragraph","content":[{"type":"text","text":"Massen-UnRP:"},{"type":"text","text":" Das Agieren mit mehr als 8 aktiven Personen in einer laufenden Situation gilt als schwerer Regelverstoß und schlägt direkt auf die gesamte Fraktion zurück."}]}]}'::jsonb, '§ 4 Mitglieder-Limit & Aktive Beteiligung (8er-Regel) Aktivitäts-Cap: In einer aktiven RP-Situation, Verfolgung, Schießerei oder Fraktionsaktion dürfen maximal 8 Mitglieder einer Gang gleichzeitig agieren. Verstärkungsverbot: Sobald eine Situation begonnen hat, dürfen keine weiteren Mitglieder nachgefordert werden, wenn das Limit von 8 Personen bereits erreicht ist. Massen-UnRP: Das Agieren mit mehr als 8 aktiven Personen in einer laufenden Situation gilt als schwerer Regelverstoß und schlägt direkt auf die gesamte Fraktion zurück.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'illegal-factions-5';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-illegal-factions-5', 'illegal-factions-5', 'illegal-factions-5', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', 'Illegale Fraktionen', '§ 5 Ganggebiete & Schusscall-Regelung', 5, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gebietshoheit:"},{"type":"text","text":" Jede offizielle Gang kann beim FM ein fest definiertes Ganggebiet (Hood/Turf) beantragen."}]},{"type":"paragraph","content":[{"type":"text","text":"Kein automatischer Schusscall:"},{"type":"text","text":" Das bloße Betreten eines Ganggebietes durch Zivilisten, andere Gangs oder Beamte rechtfertigt "},{"type":"text","text":"keinen automatischen Schusscall"},{"type":"text","text":" oder sofortiges Erschießen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eskalationsstufen im Gebiet:"},{"type":"text","text":"Betreten fremde Personen das Gebiet, müssen diese zunächst verbal aufgefordert werden, das Areal zu verlassen."},{"type":"text","text":"Bei Weigerung oder provokantem Verhalten folgt eine deutliche Bedrohung (z. B. Waffe ziehen und Zielansprache mit Deadline)."},{"type":"text","text":"Erst wenn die Gegenpartei der Aufforderung innerhalb einer angemessenen Reaktionszeit (mind. 5–10 Sekunden) nicht nachkommt oder selbst eine Waffe zieht, ist der Schusscall legitimiert."}]},{"type":"paragraph","content":[{"type":"text","text":"Betreten fremde Personen das Gebiet, müssen diese zunächst verbal aufgefordert werden, das Areal zu verlassen."}]},{"type":"paragraph","content":[{"type":"text","text":"Bei Weigerung oder provokantem Verhalten folgt eine deutliche Bedrohung (z. B. Waffe ziehen und Zielansprache mit Deadline)."}]},{"type":"paragraph","content":[{"type":"text","text":"Erst wenn die Gegenpartei der Aufforderung innerhalb einer angemessenen Reaktionszeit (mind. 5–10 Sekunden) nicht nachkommt oder selbst eine Waffe zieht, ist der Schusscall legitimiert."}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahme:"},{"type":"text","text":" Das unbefugte Eindringen einer rivalisierenden Gang in kompletter Montur und Bewaffnung während eines aktiven Bündnis-/Gebietskonflikts gilt als direkte Bedrohung und verkürzt die Vorwarnzeit."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 5 Ganggebiete & Schusscall-Regelung' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
