    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 5 Ganggebiete & Schusscall-Regelung', "order" = 5, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-5-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gebietshoheit:"},{"type":"text","text":" Jede offizielle Gang kann beim FM ein fest definiertes Ganggebiet (Hood/Turf) beantragen."}]},{"type":"paragraph","content":[{"type":"text","text":"Kein automatischer Schusscall:"},{"type":"text","text":" Das bloße Betreten eines Ganggebietes durch Zivilisten, andere Gangs oder Beamte rechtfertigt "},{"type":"text","text":"keinen automatischen Schusscall"},{"type":"text","text":" oder sofortiges Erschießen."}]},{"type":"paragraph","content":[{"type":"text","text":"Eskalationsstufen im Gebiet:"},{"type":"text","text":"Betreten fremde Personen das Gebiet, müssen diese zunächst verbal aufgefordert werden, das Areal zu verlassen."},{"type":"text","text":"Bei Weigerung oder provokantem Verhalten folgt eine deutliche Bedrohung (z. B. Waffe ziehen und Zielansprache mit Deadline)."},{"type":"text","text":"Erst wenn die Gegenpartei der Aufforderung innerhalb einer angemessenen Reaktionszeit (mind. 5–10 Sekunden) nicht nachkommt oder selbst eine Waffe zieht, ist der Schusscall legitimiert."}]},{"type":"paragraph","content":[{"type":"text","text":"Betreten fremde Personen das Gebiet, müssen diese zunächst verbal aufgefordert werden, das Areal zu verlassen."}]},{"type":"paragraph","content":[{"type":"text","text":"Bei Weigerung oder provokantem Verhalten folgt eine deutliche Bedrohung (z. B. Waffe ziehen und Zielansprache mit Deadline)."}]},{"type":"paragraph","content":[{"type":"text","text":"Erst wenn die Gegenpartei der Aufforderung innerhalb einer angemessenen Reaktionszeit (mind. 5–10 Sekunden) nicht nachkommt oder selbst eine Waffe zieht, ist der Schusscall legitimiert."}]},{"type":"paragraph","content":[{"type":"text","text":"Ausnahme:"},{"type":"text","text":" Das unbefugte Eindringen einer rivalisierenden Gang in kompletter Montur und Bewaffnung während eines aktiven Bündnis-/Gebietskonflikts gilt als direkte Bedrohung und verkürzt die Vorwarnzeit."}]}]}'::jsonb, '§ 5 Ganggebiete & Schusscall-Regelung Gebietshoheit: Jede offizielle Gang kann beim FM ein fest definiertes Ganggebiet (Hood/Turf) beantragen. Kein automatischer Schusscall: Das bloße Betreten eines Ganggebietes durch Zivilisten, andere Gangs oder Beamte rechtfertigt keinen automatischen Schusscall oder sofortiges Erschießen. Eskalationsstufen im Gebiet: Betreten fremde Personen das Gebiet, müssen diese zunächst verbal aufgefordert werden, das Areal zu verlassen. Bei Weigerung oder provokantem Verhalten folgt eine deutliche Bedrohung (z. B. Waffe ziehen und Zielansprache mit Deadline). Erst wenn die Gegenpartei der Aufforderung innerhalb einer angemessenen Reaktionszeit (mind. 5–10 Sekunden) nicht nachkommt oder selbst eine Waffe zieht, ist der Schusscall legitimiert. Betreten fremde Personen das Gebiet, müssen diese zunächst verbal aufgefordert werden, das Areal zu verlassen. Bei Weigerung oder provokantem Verhalten folgt eine deutliche Bedrohung (z. B. Waffe ziehen und Zielansprache mit Deadline). Erst wenn die Gegenpartei der Aufforderung innerhalb einer angemessenen Reaktionszeit (mind. 5–10 Sekunden) nicht nachkommt oder selbst eine Waffe zieht, ist der Schusscall legitimiert. Ausnahme: Das unbefugte Eindringen einer rivalisierenden Gang in kompletter Montur und Bewaffnung während eines aktiven Bündnis-/Gebietskonflikts gilt als direkte Bedrohung und verkürzt die Vorwarnzeit.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

