  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das vorsätzliche Überfahren von Personen (VDM) ist strengstens verboten und gilt nicht als valides Mittel zur Gefahrenabwehr."}]},{"type":"paragraph","content":[{"type":"text","text":"Sinnloses Rammen von Fahrzeugen mit unrealistisch hoher Geschwindigkeit (\"Car-Ramming\") ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"PIT-Manöver oder das Ausbremsen gegnerischer Fahrzeuge sind nur bei angemessener Geschwindigkeit gestattet, um den gegnerischen Wagen zum Anhalten zu zwingen. Aussteigen und Schießen ist erst erlaubt, wenn die Fahrzeuge vollständig zum Stillstand gekommen sind."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 6 Fahrzeugnutzung, Verfolgungen & VDM' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 6 Fahrzeugnutzung, Verfolgungen & VDM', "order" = 6, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-6-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das vorsätzliche Überfahren von Personen (VDM) ist strengstens verboten und gilt nicht als valides Mittel zur Gefahrenabwehr."}]},{"type":"paragraph","content":[{"type":"text","text":"Sinnloses Rammen von Fahrzeugen mit unrealistisch hoher Geschwindigkeit (\"Car-Ramming\") ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"PIT-Manöver oder das Ausbremsen gegnerischer Fahrzeuge sind nur bei angemessener Geschwindigkeit gestattet, um den gegnerischen Wagen zum Anhalten zu zwingen. Aussteigen und Schießen ist erst erlaubt, wenn die Fahrzeuge vollständig zum Stillstand gekommen sind."}]}]}'::jsonb, '§ 6 Fahrzeugnutzung, Verfolgungen & VDM Das vorsätzliche Überfahren von Personen (VDM) ist strengstens verboten und gilt nicht als valides Mittel zur Gefahrenabwehr. Sinnloses Rammen von Fahrzeugen mit unrealistisch hoher Geschwindigkeit ("Car-Ramming") ist untersagt. PIT-Manöver oder das Ausbremsen gegnerischer Fahrzeuge sind nur bei angemessener Geschwindigkeit gestattet, um den gegnerischen Wagen zum Anhalten zu zwingen. Aussteigen und Schießen ist erst erlaubt, wenn die Fahrzeuge vollständig zum Stillstand gekommen sind.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

