    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Anmeldung:"},{"type":"text","text":" Ein Gangkrieg zwischen zwei kriminellen Fraktionen kann nicht spontan ausgerufen werden, sondern erfordert eine schriftliche Anmeldung per Ticket beim FM inklusive RP-Hintergrund."}]},{"type":"paragraph","content":[{"type":"text","text":"Kriegsbedingungen:"},{"type":"text","text":" Vor Beginn müssen beide Parteien sowie das FM die Rahmenbedingungen (Dauer, erlaubte Waffen, Gebietsgrenzen, Beteiligtenanzahl) festlegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Einschränkung:"},{"type":"text","text":" Während eines offiziellen Gangkriegs gilt ebenfalls das Limit von "},{"type":"text","text":"maximal 8 aktiven Mitgliedern pro Partei"},{"type":"text","text":" in einzelnen Gefechten."}]},{"type":"paragraph","content":[{"type":"text","text":"Beendigung:"},{"type":"text","text":" Ein Gangkrieg endet durch eine Kapitulation, eine vertragliche Einigung oder durch die Decision des FM."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 7 Gangkriege & Fehden' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
