    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bündnisse & Pakte:"},{"type":"text","text":" Gangs dürfen Nichtangriffspakte (NAP), Schutzbündnisse oder Handelsabkommen untereinander schließen."}]},{"type":"paragraph","content":[{"type":"text","text":"Mindestanforderungen an Bündnisverträge:"},{"type":"text","text":"Vertragspartner:"},{"type":"text","text":" Nennung der beteiligten Fraktionsleitungen."},{"type":"text","text":"Laufzeit:"},{"type":"text","text":" Exakte Gültigkeitsdauer oder vertragliche Kündigungsfristen."},{"type":"text","text":"Inhalt:"},{"type":"text","text":" Genaue Festlegung von Gebietsgrenzen, Handelspreisen für Illegales oder Bündnispflichten."},{"type":"text","text":"Strafklausel:"},{"type":"text","text":" Konsequenzen bei Vertragsbruch (z. B. Diplomatie-Verlust, Entschädigungszahlungen)."}]},{"type":"paragraph","content":[{"type":"text","text":"Vertragspartner:"},{"type":"text","text":" Nennung der beteiligten Fraktionsleitungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Laufzeit:"},{"type":"text","text":" Exakte Gültigkeitsdauer oder vertragliche Kündigungsfristen."}]},{"type":"paragraph","content":[{"type":"text","text":"Inhalt:"},{"type":"text","text":" Genaue Festlegung von Gebietsgrenzen, Handelspreisen für Illegales oder Bündnispflichten."}]},{"type":"paragraph","content":[{"type":"text","text":"Strafklausel:"},{"type":"text","text":" Konsequenzen bei Vertragsbruch (z. B. Diplomatie-Verlust, Entschädigungszahlungen)."}]},{"type":"paragraph","content":[{"type":"text","text":"Maximale Bündnisgröße:"},{"type":"text","text":" In gemeinsamen Aktionen zweier verbündeter Gangs darf die Gesamtzahl aller Beteiligten zusammen das "},{"type":"text","text":"Limit von 8 Personen"},{"type":"text","text":" nicht überschreiten."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 8 Verträge & Diplomatie zwischen Gangs' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
