  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-8-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bündnisse & Pakte:"},{"type":"text","text":" Gangs dürfen Nichtangriffspakte (NAP), Schutzbündnisse oder Handelsabkommen untereinander schließen."}]},{"type":"paragraph","content":[{"type":"text","text":"Mindestanforderungen an Bündnisverträge:"},{"type":"text","text":"Vertragspartner:"},{"type":"text","text":" Nennung der beteiligten Fraktionsleitungen."},{"type":"text","text":"Laufzeit:"},{"type":"text","text":" Exakte Gültigkeitsdauer oder vertragliche Kündigungsfristen."},{"type":"text","text":"Inhalt:"},{"type":"text","text":" Genaue Festlegung von Gebietsgrenzen, Handelspreisen für Illegales oder Bündnispflichten."},{"type":"text","text":"Strafklausel:"},{"type":"text","text":" Konsequenzen bei Vertragsbruch (z. B. Diplomatie-Verlust, Entschädigungszahlungen)."}]},{"type":"paragraph","content":[{"type":"text","text":"Vertragspartner:"},{"type":"text","text":" Nennung der beteiligten Fraktionsleitungen."}]},{"type":"paragraph","content":[{"type":"text","text":"Laufzeit:"},{"type":"text","text":" Exakte Gültigkeitsdauer oder vertragliche Kündigungsfristen."}]},{"type":"paragraph","content":[{"type":"text","text":"Inhalt:"},{"type":"text","text":" Genaue Festlegung von Gebietsgrenzen, Handelspreisen für Illegales oder Bündnispflichten."}]},{"type":"paragraph","content":[{"type":"text","text":"Strafklausel:"},{"type":"text","text":" Konsequenzen bei Vertragsbruch (z. B. Diplomatie-Verlust, Entschädigungszahlungen)."}]},{"type":"paragraph","content":[{"type":"text","text":"Maximale Bündnisgröße:"},{"type":"text","text":" In gemeinsamen Aktionen zweier verbündeter Gangs darf die Gesamtzahl aller Beteiligten zusammen das "},{"type":"text","text":"Limit von 8 Personen"},{"type":"text","text":" nicht überschreiten."}]}]}'::jsonb, '§ 8 Verträge & Diplomatie zwischen Gangs Bündnisse & Pakte: Gangs dürfen Nichtangriffspakte (NAP), Schutzbündnisse oder Handelsabkommen untereinander schließen. Mindestanforderungen an Bündnisverträge: Vertragspartner: Nennung der beteiligten Fraktionsleitungen. Laufzeit: Exakte Gültigkeitsdauer oder vertragliche Kündigungsfristen. Inhalt: Genaue Festlegung von Gebietsgrenzen, Handelspreisen für Illegales oder Bündnispflichten. Strafklausel: Konsequenzen bei Vertragsbruch (z. B. Diplomatie-Verlust, Entschädigungszahlungen). Vertragspartner: Nennung der beteiligten Fraktionsleitungen. Laufzeit: Exakte Gültigkeitsdauer oder vertragliche Kündigungsfristen. Inhalt: Genaue Festlegung von Gebietsgrenzen, Handelspreisen für Illegales oder Bündnispflichten. Strafklausel: Konsequenzen bei Vertragsbruch (z. B. Diplomatie-Verlust, Entschädigungszahlungen). Maximale Bündnisgröße: In gemeinsamen Aktionen zweier verbündeter Gangs darf die Gesamtzahl aller Beteiligten zusammen das Limit von 8 Personen nicht überschreiten.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'illegal-factions-9';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-illegal-factions-9', 'illegal-factions-9', 'illegal-factions-9', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', 'Illegale Fraktionen', '§ 9 Interaktion mit Staatsfraktionen (Cop-Baiting & Respekt)', 9, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das gezielte Provozieren der Polizei ohne triftigen RP-Grund (\"Cop-Baiting\"), wie z. B. dauerhaftes Hupen vor der Polizeiwache, unnötiges Driften vor Streifenwagen oder grundloses Anschießen von Beamten, ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Geiselnahmen, Raubüberfälle (z. B. Bank, Juwelier) oder Hinterhalte gegen Einsatzkräfte müssen primär dem Story-Roleplay dienen und dürfen nicht als reine Schießerei-Anforderung missbraucht werden."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 9 Interaktion mit Staatsfraktionen (Cop-Baiting & Respekt)' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 9 Interaktion mit Staatsfraktionen (Cop-Baiting & Respekt)', "order" = 9, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-9-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das gezielte Provozieren der Polizei ohne triftigen RP-Grund (\"Cop-Baiting\"), wie z. B. dauerhaftes Hupen vor der Polizeiwache, unnötiges Driften vor Streifenwagen oder grundloses Anschießen von Beamten, ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Geiselnahmen, Raubüberfälle (z. B. Bank, Juwelier) oder Hinterhalte gegen Einsatzkräfte müssen primär dem Story-Roleplay dienen und dürfen nicht als reine Schießerei-Anforderung missbraucht werden."}]}]}'::jsonb, '§ 9 Interaktion mit Staatsfraktionen (Cop-Baiting & Respekt) Das gezielte Provozieren der Polizei ohne triftigen RP-Grund ("Cop-Baiting"), wie z. B. dauerhaftes Hupen vor der Polizeiwache, unnötiges Driften vor Streifenwagen oder grundloses Anschießen von Beamten, ist untersagt. Geiselnahmen, Raubüberfälle (z. B. Bank, Juwelier) oder Hinterhalte gegen Einsatzkräfte müssen primär dem Story-Roleplay dienen und dürfen nicht als reine Schießerei-Anforderung missbraucht werden.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'illegal-factions-10';
