      ('rule-illegal-factions-10', 'illegal-factions-10', 'illegal-factions-10', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', 'Illegale Fraktionen', '§ 10 Überfälle, Geiselnahmen & Erpressung', 10, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
