    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bei Geiselnahmen oder Überfällen auf Server-Hotspots muss der Fokus auf hochqualitativem RP liegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Forderungen an die Polizei oder Opfer müssen verhältnismäßig und realistisch bleiben."}]},{"type":"paragraph","content":[{"type":"text","text":"Geiseln dürfen nicht grundlos exekutiert werden, solange die gegnerische Partei oder die Polizei den geforderten Bedingungen nachkommt."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 10 Überfälle, Geiselnahmen & Erpressung' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
