    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 10 Überfälle, Geiselnahmen & Erpressung', "order" = 10, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
