    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-10-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bei Geiselnahmen oder Überfällen auf Server-Hotspots muss der Fokus auf hochqualitativem RP liegen."}]},{"type":"paragraph","content":[{"type":"text","text":"Forderungen an die Polizei oder Opfer müssen verhältnismäßig und realistisch bleiben."}]},{"type":"paragraph","content":[{"type":"text","text":"Geiseln dürfen nicht grundlos exekutiert werden, solange die gegnerische Partei oder die Polizei den geforderten Bedingungen nachkommt."}]}]}'::jsonb, '§ 10 Überfälle, Geiselnahmen & Erpressung Bei Geiselnahmen oder Überfällen auf Server-Hotspots muss der Fokus auf hochqualitativem RP liegen. Forderungen an die Polizei oder Opfer müssen verhältnismäßig und realistisch bleiben. Geiseln dürfen nicht grundlos exekutiert werden, solange die gegnerische Partei oder die Polizei den geforderten Bedingungen nachkommt.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'illegal-factions-11';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-illegal-factions-11', 'illegal-factions-11', 'illegal-factions-11', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', 'Illegale Fraktionen', '§ 11 Hinrichtungen, Blood-Outs & Charakter-Tod', 11, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ein \"Blood-Out\" (das endgültige, tödliche Entfernen eines Mitglieds aus der Gang) beendet die Zugehörigkeit des Spielers zur Fraktion dauerhaft."}]},{"type":"paragraph","content":[{"type":"text","text":"Ein Blood-Out muss einen schwerwiegenden RP-Grund haben (z. B. Verrat, Korruption) und erfordert die vorherige Zustimmung des FM per Ticket."}]},{"type":"paragraph","content":[{"type":"text","text":"Nach einem vollzogenen Blood-Out vergisst der betroffene Charakter alle internen Gang-Informationen (New Life Rule / Gedächtnisverlust bezüglich der Gang)."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 11 Hinrichtungen, Blood-Outs & Charakter-Tod' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 11 Hinrichtungen, Blood-Outs & Charakter-Tod', "order" = 11, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-11-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ein \"Blood-Out\" (das endgültige, tödliche Entfernen eines Mitglieds aus der Gang) beendet die Zugehörigkeit des Spielers zur Fraktion dauerhaft."}]},{"type":"paragraph","content":[{"type":"text","text":"Ein Blood-Out muss einen schwerwiegenden RP-Grund haben (z. B. Verrat, Korruption) und erfordert die vorherige Zustimmung des FM per Ticket."}]},{"type":"paragraph","content":[{"type":"text","text":"Nach einem vollzogenen Blood-Out vergisst der betroffene Charakter alle internen Gang-Informationen (New Life Rule / Gedächtnisverlust bezüglich der Gang)."}]}]}'::jsonb, '§ 11 Hinrichtungen, Blood-Outs & Charakter-Tod Ein "Blood-Out" (das endgültige, tödliche Entfernen eines Mitglieds aus der Gang) beendet die Zugehörigkeit des Spielers zur Fraktion dauerhaft. Ein Blood-Out muss einen schwerwiegenden RP-Grund haben (z. B. Verrat, Korruption) und erfordert die vorherige Zustimmung des FM per Ticket. Nach einem vollzogenen Blood-Out vergisst der betroffene Charakter alle internen Gang-Informationen (New Life Rule / Gedächtnisverlust bezüglich der Gang).', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'illegal-factions-12';
  IF NOT FOUND THEN
    next_version := 1;
    changed := true;
    INSERT INTO "Rule" ("id", "slug", "sourceKey", "sourceUrl", "category", "title", "order", "version", "published", "createdAt", "updatedAt") VALUES
      ('rule-illegal-factions-12', 'illegal-factions-12', 'illegal-factions-12', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', 'Illegale Fraktionen', '§ 12 Waffen-Pooling, Ausrüstungs-Weitergabe & Ingame-Finanzen', 12, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das Weitergeben von Gamepass-Waffen oder Werkzeugen an Spieler außerhalb der eigenen Fraktion zur Umgehung von Server-Regeln ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Wenn Fraktionsmitglieder Geld oder Ausrüstung für gemeinsame Käufe sammeln (z. B. für Ingame-Aktivitäten oder Events), muss dies transparent innerhalb der Gang-Leitung dokumentiert werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Das mutwillige Bestehlen der eigenen Fraktionsmitglieder oder das Ausnutzen von Vertrauen vor einem Austritt/Kick wird administrativ als Scamming/Trolling geahndet."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 12 Waffen-Pooling, Ausrüstungs-Weitergabe & Ingame-Finanzen' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 12 Waffen-Pooling, Ausrüstungs-Weitergabe & Ingame-Finanzen', "order" = 12, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-12-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Das Weitergeben von Gamepass-Waffen oder Werkzeugen an Spieler außerhalb der eigenen Fraktion zur Umgehung von Server-Regeln ist untersagt."}]},{"type":"paragraph","content":[{"type":"text","text":"Wenn Fraktionsmitglieder Geld oder Ausrüstung für gemeinsame Käufe sammeln (z. B. für Ingame-Aktivitäten oder Events), muss dies transparent innerhalb der Gang-Leitung dokumentiert werden."}]},{"type":"paragraph","content":[{"type":"text","text":"Das mutwillige Bestehlen der eigenen Fraktionsmitglieder oder das Ausnutzen von Vertrauen vor einem Austritt/Kick wird administrativ als Scamming/Trolling geahndet."}]}]}'::jsonb, '§ 12 Waffen-Pooling, Ausrüstungs-Weitergabe & Ingame-Finanzen Das Weitergeben von Gamepass-Waffen oder Werkzeugen an Spieler außerhalb der eigenen Fraktion zur Umgehung von Server-Regeln ist untersagt. Wenn Fraktionsmitglieder Geld oder Ausrüstung für gemeinsame Käufe sammeln (z. B. für Ingame-Aktivitäten oder Events), muss dies transparent innerhalb der Gang-Leitung dokumentiert werden. Das mutwillige Bestehlen der eigenen Fraktionsmitglieder oder das Ausnutzen von Vertrauen vor einem Austritt/Kick wird administrativ als Scamming/Trolling geahndet.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
  SELECT * INTO current_rule FROM "Rule" WHERE "sourceKey" = 'illegal-factions-13';
  IF NOT FOUND THEN
