      ('rule-illegal-factions-13', 'illegal-factions-13', 'illegal-factions-13', 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', 'Illegale Fraktionen', '§ 13 Inaktivität & Pflichten der Gang-Leitung', 13, next_version, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING * INTO current_rule;
  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Leitung einer Gang (Leader / Co-Leader) trägt die volle Verantwortung für das Verhalten ihrer Mitglieder."}]},{"type":"paragraph","content":[{"type":"text","text":"Sollte eine kriminelle Fraktion über einen Zeitraum von mehr als "},{"type":"text","text":"7 Tagen"},{"type":"text","text":" ohne Abmeldung beim FM unbegründete Inaktivität aufweisen, wird die Fraktion aufgelöst oder der Führungskader ausgetauscht."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 13 Inaktivität & Pflichten der Gang-Leitung' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
