      ('revision-illegal-factions-13-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Die Leitung einer Gang (Leader / Co-Leader) trägt die volle Verantwortung für das Verhalten ihrer Mitglieder."}]},{"type":"paragraph","content":[{"type":"text","text":"Sollte eine kriminelle Fraktion über einen Zeitraum von mehr als "},{"type":"text","text":"7 Tagen"},{"type":"text","text":" ohne Abmeldung beim FM unbegründete Inaktivität aufweisen, wird die Fraktion aufgelöst oder der Führungskader ausgetauscht."}]}]}'::jsonb, '§ 13 Inaktivität & Pflichten der Gang-Leitung Die Leitung einer Gang (Leader / Co-Leader) trägt die volle Verantwortung für das Verhalten ihrer Mitglieder. Sollte eine kriminelle Fraktion über einen Zeitraum von mehr als 7 Tagen ohne Abmeldung beim FM unbegründete Inaktivität aufweisen, wird die Fraktion aufgelöst oder der Führungskader ausgetauscht.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

DO $$ DECLARE current_rule "Rule"%ROWTYPE; current_content JSONB; next_version INTEGER; changed BOOLEAN := false; BEGIN
