  ELSE
    SELECT "content" INTO current_content FROM "RuleRevision" WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED' ORDER BY "publishedAt" DESC NULLS LAST, "createdAt" DESC LIMIT 1;
    IF current_content IS DISTINCT FROM '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bei Regelbrüchen (z. B. Verstoß gegen das 8er-Limit, RDM im Ganggebiet, fehlende Kennzeichen/Farben) greift das allgemeine Warn-System (Ermahnung, Fraktions-Warn, Schließung)."}]},{"type":"paragraph","content":[{"type":"text","text":"Bei Erreichen von "},{"type":"text","text":"3 Fraktions-Warns"},{"type":"text","text":" wird die kriminelle Fraktion aufgelöst, der Status aberkannt und das Ganggebiet freigegeben."}]}]}'::jsonb OR current_rule."title" IS DISTINCT FROM '§ 14 Sanktionen & Fraktionsauflösung' OR current_rule."category" IS DISTINCT FROM 'Illegale Fraktionen' THEN
      next_version := current_rule."version" + 1;
      changed := true;
      UPDATE "RuleRevision" SET "status" = 'SUPERSEDED', "updatedAt" = CURRENT_TIMESTAMP WHERE "ruleId" = current_rule."id" AND "status" = 'PUBLISHED';
    ELSE
      next_version := current_rule."version";
    END IF;
    UPDATE "Rule" SET "sourceUrl" = 'https://sites.google.com/view/deutschland-rp-regelwerk/fraktions-regelwerk/illegale-fraktionen', "category" = 'Illegale Fraktionen', "title" = '§ 14 Sanktionen & Fraktionsauflösung', "order" = 14, "version" = next_version, "published" = true, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = current_rule."id" RETURNING * INTO current_rule;
  END IF;
  IF changed OR NOT EXISTS (SELECT 1 FROM "RuleRevision" WHERE "ruleId" = current_rule."id") THEN
    INSERT INTO "RuleRevision" ("id", "ruleId", "status", "content", "searchText", "createdAt", "updatedAt", "publishedAt") VALUES
      ('revision-illegal-factions-14-v' || next_version, current_rule."id", 'PUBLISHED', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bei Regelbrüchen (z. B. Verstoß gegen das 8er-Limit, RDM im Ganggebiet, fehlende Kennzeichen/Farben) greift das allgemeine Warn-System (Ermahnung, Fraktions-Warn, Schließung)."}]},{"type":"paragraph","content":[{"type":"text","text":"Bei Erreichen von "},{"type":"text","text":"3 Fraktions-Warns"},{"type":"text","text":" wird die kriminelle Fraktion aufgelöst, der Status aberkannt und das Ganggebiet freigegeben."}]}]}'::jsonb, '§ 14 Sanktionen & Fraktionsauflösung Bei Regelbrüchen (z. B. Verstoß gegen das 8er-Limit, RDM im Ganggebiet, fehlende Kennzeichen/Farben) greift das allgemeine Warn-System (Ermahnung, Fraktions-Warn, Schließung). Bei Erreichen von 3 Fraktions-Warns wird die kriminelle Fraktion aufgelöst, der Status aberkannt und das Ganggebiet freigegeben.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
  END IF;
END $$;

